INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b9ecd820-3cc7-5cd8-ad21-5403831e7c3f', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 16, 16, 'እኔ መረጥኋችሁ እንጂ እናንተ የመረጣችሁኝ አይደለም፤ እንድትሄዱ፥ ፍሬም እንድታፈሩ፥ ፍሬአችሁም እንዲኖር፤ አብንም በስሜ የምትለምኑት ነገር ቢኖር ሁሉን እንዲሰጣችሁ ሾምኋችሁ።'),
  ('d359652d-8d32-5b66-a1de-7b9306829ed1', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 17, 17, 'እርስ በርሳችሁም እንድቷደዱ ይህን አዝዣችኋለሁ።'),
  ('245bc84c-b0a1-5441-a13b-b73d4bca2baf', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 1, 18, '“ዓለም ቢጠላችሁ አስቀድሞ እኔን እንደ ጠላ ዕወቁ።'),
  ('8104eed2-7c69-5a38-a114-ab31e306885f', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 2, 19, 'እናንተስ ከዓለም ብትሆኑ ዓለም በወደዳችሁ ነበር፤ ዓለም ወገኖቹን ይወዳልና፤ ነገር ግን እኔ ከዓለም መረጥኋችሁ እንጂ እናንተ ከዓለም አይደላችሁምና ስለዚህ ዓለም ይጠላችኋል።'),
  ('6679db5d-7310-5352-aaa8-6ea89442aa65', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 3, 20, 'እኔ፦ ከጌታው የሚበልጥ አገልጋይ የለም ያልኋችሁን ቃሌን ዐስቡ፤ እኔን ካሳደዱ እናንተንም ያሳድዱአችኋል፤ ቃሌን ጠብቀው ቢሆንስ ቃላችሁንም በጠበቁ ነበር።'),
  ('0a24debe-57ef-5b4b-a3fb-2570cf1f47aa', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 4, 21, 'ነገር ግን ስለ ስሜ ይህን ሁሉ ያደርጉባችኋል፤ የላከኝን አያውቁትምና።'),
  ('f91ba80e-313c-51ef-a9ba-6e312517539a', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 5, 22, 'ባልመጣሁና ባልነገርኋቸውስ ኖሮ ኀጢአት ባልሆነባቸውም ነበር፤ አሁን ግን ለኀጢአታቸው ምክንያት የላቸውም።'),
  ('8cf2d71c-9a1b-571b-a5f0-1aa617b305a4', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 6, 23, 'እኔን የሚጠላ አባቴን ይጠላል።'),
  ('55df5da6-5f19-562f-a49a-d8fef6e60eb6', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 7, 24, 'ሌላ ያልሠራውን ሥራ በመካከላቸው ባልሠራ ኖሮ ኀጢአት ባልሆነባቸውም ነበር፤ አሁን ግን እኔንም አባቴንም አይተዋል፤ ጠልተውማል።'),
  ('de9bb449-4d55-5082-ae8d-236247ea9448', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'cd513c79-5814-59d5-a50b-f9f9b015fbf7', 8, 25, 'ነገር ግን በኦሪታቸው፦ በከንቱ ጠሉኝ ተብሎ የተጻፈው ቃል ይፈጸም ዘንድ ነው።'),
  ('4e0728b4-96ac-5d55-af3d-51d12c2e7e45', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'c0a93126-2761-50cc-a5fb-c525df71090d', 1, 26, '“እኔ ከአብ ዘንድ የምልክላችሁ ጰራቅሊጦስ እርሱም ከአብ የሚወጣ የእውነት መንፈስ በመጣ ጊዜ፥ እርሱ ስለ እኔ ይመሰክራል።'),
  ('b09c9c39-925e-50a4-a05b-9bb2ae5f52d7', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', 'c0a93126-2761-50cc-a5fb-c525df71090d', 2, 27, 'እናንተም ትመሰክራላችሁ፤ ከጥንት ጀምሮ ከእኔ ጋር ኑራችኋልና።'),
  ('a8d0abef-5c90-5286-a8fc-008455052149', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'e04b6b1a-5955-5a04-a1f2-effccc9a1fe7', 1, 1, '“እንዳትሰናከሉ ይህን ነገርኋችሁ።'),
  ('291d2530-cc3b-5c26-a8e9-0cd95fa6e9f1', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'e04b6b1a-5955-5a04-a1f2-effccc9a1fe7', 2, 2, 'ከምኵራባቸው ያስወጡአችኋል፤ ደግሞም እናንተን የሚገድላችሁ ሁሉ ለእግዚአብሔር አገልግሎት የሚያቀርብ የሚመስልበት ጊዜ ይመጣል።'),
  ('1efe1d5d-ea9b-534f-ad5c-3c459f403585', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'e04b6b1a-5955-5a04-a1f2-effccc9a1fe7', 3, 3, 'ይህንም የሚያደርጉባችሁ አብንም፥ እኔንም ስላላወቁ ነው።'),
  ('7df1000f-6c0f-5455-adb2-94b5afb061e9', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'e04b6b1a-5955-5a04-a1f2-effccc9a1fe7', 4, 4, 'ነገር ግን ጊዜው ሲደርስ እኔ እንደ ነገርኋችሁ ታስቡ ዘንድ ይህን ነገርኋችሁ። አስቀድሜ ግን ይህን አልነገርክኋችሁም ነበር፤ ከእናንተ ጋር ነበርሁና።'),
  ('a3c47252-b3ca-539f-a009-ee1ccb0be6f7', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'e04b6b1a-5955-5a04-a1f2-effccc9a1fe7', 5, 5, 'አሁን ግን ወደ ላከኝ ወደ አብ እሄዳለሁ፤ ከእናንተ አንዱ እንኳ፦ ‘ወዴት ትሄዳለህ?’ ብሎ አይጠይቀኝም።'),
  ('4f312048-9634-544e-aa26-4e335de03774', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'e04b6b1a-5955-5a04-a1f2-effccc9a1fe7', 6, 6, 'ነገር ግን ይህን ስለ ነገርኋችሁ በልባችሁ ኀዘን ሞላ።'),
  ('bd49e65b-fa56-50cb-ae5d-6f1c1a9deb39', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 1, 7, '“እኔ በእውነት የሚሆነውን እነግራችኋለሁ፤ እኔ ብሄድ ይሻላችኋል፤ እኔ ካልሄድሁ ጰራቅሊጦስ ወደ እናንተ አይመጣምና፤ እኔ ከሄድሁ ግን እርሱን እልክላችኋለሁ።'),
  ('ead6455f-bd14-5603-ac15-3546d422bb76', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 2, 8, 'እርሱም በመጣ ጊዜ ዓለምን ስለ ኀጢአትና ስለ ጽድቅ፥ ስለ ፍርድም ይዘልፈዋል።'),
  ('32056993-04cc-5e1c-a769-e60af8f07dcd', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 3, 9, 'ስለ ኀጢኣት፥ በእኔ አላመኑምና ነው፤'),
  ('8f21ca1b-6490-56f3-a2cc-28b249a5b162', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 4, 10, 'ስለ ጽድቅ፥ እኔ ወደ አብ እሄዳለሁና፥ እንግዲህ ወዲህም አታዩኝምና ነው።'),
  ('64d84097-5d3b-5107-a3ee-1a0e408ccea0', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 5, 11, 'ስለ ፍርድም፥ የዚህ ዓለም ገዢ ይፈረድበታልና ነው።'),
  ('42065959-e160-5bf8-a391-223e56d3ca7e', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 6, 12, '“የምነግራችሁ ብዙ ነገር ነበረኝ፤ ነገር ግን አሁን ልትሸከሙት አትችሉም።'),
  ('d728656e-5190-57a2-a0b7-961ed1411ff4', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 7, 13, 'ያ የእውነት መንፈስ በመጣ ጊዜ ግን ወደ እውነት ሁሉ ይመራችኋል፤ የሚሰማውን ሁሉ ይናገራል እንጂ እርሱ ከራሱ አይናገርምና፤ የሚመጣውንም ይነግራችኋል።'),
  ('1d5d6909-b80a-589c-ad94-b4d5c6907da3', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 8, 14, 'እርሱም እኔን ያከብረኛል፤ ከእኔ ወስዶ ይነግራችኋልና።'),
  ('7f321102-6c75-5554-a1d4-8d1ca0e2a657', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 9, 15, 'ለአብ ያለው ሁሉ የእኔ ነው፤ ስለዚህም ከእኔ ወስዶ ይነግራችኋል አልኋችሁ።'),
  ('e118ab3c-64b6-5f1d-aa5b-43d00bef559f', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 10, 16, '“ጥቂት ጊዜ አለ፤ አታዩኝምም፤ ደግሞም ጥቂት ጊዜ አለ፤ እንደገናም ታዩኛላችሁ፤ ወደ አብ እሄዳለሁና።”'),
  ('5fe84032-8d96-5f16-a54d-dd0343a7a4da', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 11, 17, 'ደቀ መዛሙርቱም እርስ በርሳቸው፥ “ጥቂት ጊዜ አለ፤ አታዩኝምም፤ ደግሞም ጥቂት ጊዜ አለ፤ እንደገናም ታዩኛላችሁ፥ ወደ አብ እሄዳለሁና የሚለን ይህ ነገር ምንድነው?” ተባባሉ።'),
  ('be1a93bb-2045-5151-a8f9-8456137093e2', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 12, 18, '“ይህ ጥቂት የሚለን ምንድነው? የሚናገረውን አናውቅም” አሉ።'),
  ('3bbefcda-2ebb-5743-a95f-dde5636feb33', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '744ae993-cfdb-5913-ad4d-1464cafe52db', 13, 19, 'ጌታችን ኢየሱስም ሊጠይቁት እንደሚሹ ዐውቆ እንዲህ አላቸው፥ “ጥቂት ጊዜ አለ፤ አታዩኝምም፤ ደግሞም ጥቂት ጊዜ አለ፤ እንደገናም ታዩኛላችሁ” ስለ አልኋችሁ፥ ስለዚህ ነገር እርስ በርሳችሁ ትመራመራላችሁን?'),
  ('b356c536-ef7a-5d10-ae72-53946a474787', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'cd7fe70e-caab-5865-a25d-388df2b21379', 1, 20, '“እውነት እውነት እላችኋለሁ፤ እናንተ ታለቅሳላችሁ፤ ታዝኑማላችሁ፤ ዓለምም ደስ ይለዋል፤ እናንተ ግን ታዝናላችሁ፤ ነገር ግን ኀዘናችሁ ወደ ደስታ ይለወጣል።'),
  ('e3e548c0-0ba2-5206-a2ba-807fc41e4b9c', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'cd7fe70e-caab-5865-a25d-388df2b21379', 2, 21, 'ሴት በምትወልድበት ጊዜ ወራቷ ስለ ደረሰ ታዝናለች፤ ነገር ግን ልጅዋን ከወለደች በኋላ ስለ ደስታዋ ከዚያ ወዲያ ምጥዋን አታስበውም፤ በዓለም ወንድ ልጅን ወልዳለችና።'),
  ('308f3d26-c867-5319-ae29-b9bccabf3325', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'cd7fe70e-caab-5865-a25d-388df2b21379', 3, 22, 'እናንተም ዛሬ ታዝናላችሁ፤ እንደገናም አያችኋለሁ፤ ልባችሁም ደስ ይለዋል፤ ደስታችሁንም የሚወስድባችሁ የለም።'),
  ('50636c7f-6efc-513b-ac47-54383af9aef1', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'cd7fe70e-caab-5865-a25d-388df2b21379', 4, 23, 'ያንጊዜም እኔን የምትለምኑኝ አንዳች የለም፤ እውነት እውነት እላችኋለሁ፤ በስሜ አብን ብትለምኑት ሁሉን ይሰጣችኋል።'),
  ('7800cbab-fb09-5735-a1c5-361e7d134d6b', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', 'cd7fe70e-caab-5865-a25d-388df2b21379', 5, 24, 'እስካሁን ምንም በስሜ አልለመናችሁም፤ ደስታችሁ ፍጹም ይሆን ዘንድ ለምኑ፤ ታገኙማላችሁ።'),
  ('ba871914-95dd-57a8-a3bb-8481fcb37b68', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 1, 25, '“ዛሬስ በምሳሌ ነገርኋችሁ፤ ነገር ግን የአብን ነገር ገልጬ እነግራችኋለሁ እንጂ ለእናንተ በምሳሌ የማልናገርበት ጊዜ ይመጣል።'),
  ('fd6d5ef3-4977-5ee5-a48a-c7634f3f3e06', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 2, 26, 'ያንጊዜ በስሜ ትለምናላችሁ፤ እኔም ስለ እናንተ አብን እለምነዋለህ አልላችሁም፤'),
  ('dbf5c647-6abe-5e02-aa38-cefbcb9fb7ef', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 3, 27, 'እናንተ ስለ ወደዳችሁኝ፤ ከእግዚአብሔርም እንደ ወጣሁ ስለ አመናችሁብኝ እርሱ ራሱ አብ ወድዷችኋልና።'),
  ('d3c8549e-0e6e-5260-a85d-acfffbbfc38c', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 4, 28, 'ከአብ ወጣሁ፤ ወደ ዓለምም መጣሁ፤ ዳግመኛም ዓለምን እተወዋለሁ፤ ወደ አብም እሄዳለሁ።”'),
  ('3c82a8c3-248e-5880-a1ec-6aecf2414c56', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 5, 29, 'ደቀ መዛሙርቱም እንዲህ አሉት፥ “እነሆ፥ ዛሬ ገልጠህ ትናገራለህ፤ ምንም በምሳሌ የተናገርኸው የለም።'),
  ('345e2fda-d99a-578f-a2ae-0d594738f9e5', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 6, 30, 'አሁን አንተ ሁሉን እንደምታውቅ፥ ማንም ሊነግርህ እንደማትሻ ዐወቅን፤ በዚህም ከእግዚአብሔር እንደ ወጣህ እናምናለን።”'),
  ('af5cb98f-814f-5a79-a7b1-055f3d384791', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 7, 31, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “አሁን ታምናላችሁን?'),
  ('f2a3f899-2fb6-5969-a3ec-ac9741c49de4', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 8, 32, 'እያንዳንዳችሁ በየቦታዉ የምትበታተኑበት፥ እኔንም ብቻዬን የምትተዉበት ጊዜ ይደርሳል፤ ደርሶአልም፤ እኔ ግን ብቻዬን አይደለሁም፤ አብ ከእኔ ጋር ነውና።'),
  ('1a8ad7b8-dcbb-57c3-ad54-9589b7c10c2e', 'b575712f-550e-5b34-a2fa-e167dd3e8fb5', '95a33933-3778-5503-a922-4cf2bffb210e', 9, 33, 'በእኔም ሰላምን እንድታገኙ ይህን ነገርኋችሁ፤ በዓለም ግን መከራን ትቀበላላችሁ፤ ነገር ግን ጽኑ፤ እኔ ዓለሙን ድል ነሥቼዋለሁና።”'),
  ('eb46aea7-b053-53f5-ac73-90e6b1917d00', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 1, 1, 'ጌታችን ኢየሱስም ይህን ነገር ተናግሮ ዐይኖቹን ወደ ሰማይ አነሣና እንዲህ አለ፥ “አባት ሆይ፥ ሰዓቱ ደርሶአልና ልጅህ ያከብርህ ዘንድ ልጅህን አክብረው፤'),
  ('079c4d7b-2714-5d13-a35e-bf91ecd3ab5d', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 2, 2, 'ሥጋ በለበሰው ሁሉ ላይ ሥልጣንን እንደ ሰጠኸው መጠን ለሰጠኸው ሁሉ የዘለዓለም ሕይወትን ይሰጣቸው ዘንድ።'),
  ('dfeb15cb-dd44-564e-a98f-d3e6f103c38b', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 3, 3, 'ብቻህን እውነተኛ አምላክ የሆንህ አንተን፥ የላክኸውንም ኢየሱስ ክርስቶስን ያውቁ ዘንድ ይህች የዘለዓለም ሕይወት ናት።'),
  ('4b2a88cb-cf4c-588a-a39f-83debb5339db', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 4, 4, 'እኔ ልሠራው የሰጠኸኝን ሥራ ፈጽሜ በምድር ላይ አከበርሁህ።'),
  ('ad015ba5-dad5-5e38-a229-4a56e139579c', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 5, 5, 'አሁንም አባት ሆይ፥ ዓለም ሳይፈጠር ከአንተ ጋር በነበረኝ ክብር በአንተ ዘንድ አክብረኝ።'),
  ('74548a9b-fb31-5437-aa03-9df12f0e1f88', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 6, 6, '“ከዓለም ለይተህ ለሰጠኸኝ ሰዎች ስምህን ገለጥሁ፤ ያንተ ነበሩ፤ እነርሱንም ለእኔ ሰጥተኸኛል፤ ቃልህንም ጠበቁ።'),
  ('c2042290-5bcc-5584-a30d-39dd5af4a312', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 7, 7, 'የሰጠኸኝም ሁሉ ከአንተ እንደ ሆነ ዛሬ ዐወቁ።'),
  ('92f965d6-4ddd-5e49-a8f6-0bbd5479d70c', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 8, 8, 'የሰጠኽኝን ቃል ሰጥቻቸዋለሁና፤ እነርሱም ተቀብለው ከአንተ እንደ ወጣሁ በእውነት ዐወቁ፤ አንተም እንደ ላክኸኝ አመኑ።'),
  ('d75fa812-9e07-5e9d-ac94-3fcacb1b74fe', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 9, 9, 'እኔ ስለ እነርሱ እለምናለሁ፤ የምለምንህ ስለ ዓለም አይደለም፤ ስለ ሰጠኸኝ ነው እንጂ፤ ያንተ ናቸውና።'),
  ('ff38366a-12b9-50ff-acf5-d43fb5551159', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 10, 10, 'የእኔም የሆነ ሁሉ የአንተ ነው፤ የአንተም የሆነ የእኔ ነው፤ እኔም በእነርሱ ከብሬአለሁ።'),
  ('443c64c9-2c49-56f3-ace8-84a6479feb12', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 11, 11, 'እንግዲህ በዓለም አልኖርም፤ እነርሱ ግን በዓለም ይኖራሉ፤ እኔም ወደ አንተ እመጣለሁ፤ ቅዱስ አባት ሆይ፥ እነዚህን የሰጠኸኝን እንደ እኛ አንድ ይሆኑ ዘንድ በስምህ ጠብቃቸው፤'),
  ('d594dcc3-0df3-5903-ada3-08527957ea84', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 12, 12, 'እኔ በዓለም ከእነርሱ ጋር ሳለሁ ግን የሰጠኸኝን በስምህ እጠብቃቸው ነበር፤ ጠበቅኋቸውም፤ የመጽሐፉም ቃል ይፈጸም ዘንድ ከጥፋት ልጅ በቀር ከእነርሱ አንድ ስንኳን አልጠፋም።'),
  ('b8e24c9a-061e-5407-a738-a3c0f441e47d', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 13, 13, 'አሁን ግን ወደ አንተ እመጣለሁ፤ በእነርሱም ደስታዬ ፍጹም ይሆን ዘንድ ይህን በዓለም እናገራለሁ።'),
  ('aaefd74b-9c73-5a9b-add4-52bedb65b027', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 14, 14, 'እኔ ቃልህን ሰጠኋቸው፤ ዓለም ግን ጠላቸው፤ እኔ ከዓለም እንዳይደለሁ እነርሱ ከዓለም አይደሉምና።'),
  ('bfbf438f-110f-5205-a713-dbf7ad54e118', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 15, 15, 'ከክፉ ነገር እንድትጠብቃቸው ነው እንጂ ከዓለም እንድትለያቸው አልለምንም።'),
  ('6919779f-52d6-507a-ac4c-1e5aeb2256fd', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 16, 16, 'እኔ ከዓለም እንዳይደለሁ ከዓለም አይደሉምና።'),
  ('d94c6a28-8de7-5b90-a6e2-dae9a014a192', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 17, 17, 'በእውነትህ ቀድሳቸው፤ ቃልህ እውነት ነውና።'),
  ('e87781d7-cea8-582d-afab-cbceed1f8287', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 18, 18, 'አንተ እኔን ወደ ዓለም እንደ ላክኸኝ እኔም እነርሱን ወደ ዓለም ላክኋቸው።'),
  ('1e8a4e79-e960-54ad-a42f-7f2eab3b61e9', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 19, 19, 'እነርሱም በእውነት ቅዱሳን ይሆኑ ዘንድ ስለ እነርሱ እኔ ራሴን እቀድሳለሁ።'),
  ('fd2da619-c70e-513c-a1c8-55ea9940115f', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 20, 20, '“የምለምንህም ስለ እነዚህ ብቻ አይደለም፤ በቃላቸው ስለሚያምኑብኝም ነው እንጂ፤'),
  ('1aa5bd7c-43da-575f-aa00-0aa5243cec48', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 21, 21, 'ሁሉም አንድ ይሆኑ ዘንድ፥ አንተ አብ በእኔ እንዳለህ፥ እኔም በአንተ እንዳለሁ፥ እነርሱም እንደ እኛ በእኛ አንድ ይሆኑ ዘንድ፥ አንተም እንደ ላክኸኝ ዓለም ያምን ዘንድ።'),
  ('31485e11-9ea4-5525-ab08-a9652b92d6b3', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 22, 22, 'እኔም የሰጠኸኝን ክብር ሰጠኋቸው፤ እኛ አንድ እንደሆን እነርሱም እንደ እኛ አንድ ይሆኑ ዘንድ።'),
  ('bcf211aa-04b2-5416-a3ff-409b18797a29', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 23, 23, 'እኔ በእነርሱ እኖራለሁ፤ አንተም በእኔ፤ በአንድ ፍጹማን ይሆኑ ዘንድ፤ አንተም እንደ ላክኸኝና እንደ ወደድኸኝ እኔም እነርሱን እንደ ወደድኋቸው።'),
  ('690600ee-75d2-5f04-ab5f-10c7308e738f', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 24, 24, 'አባት ሆይ፥ የሰጠኸኝ እነዚህ እኔ ባለሁበት አብረውኝ ይኖሩ ዘንድና የሰጠኸኝን ክብሬን ያዩ ዘንድ እወድዳለሁ፤ ዓለም ሳይፈጠር ወድደኸኛልና።'),
  ('3e32c582-3aa2-5b14-aa8f-0a3fd5a07a8d', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 25, 25, 'ጻድቅ አባት ሆይ፥ ዓለም አላወቀህም፤ እኔ ግን ዐወቅሁህ፤ እነዚህም አንተ እንደ ላክኸኝ ዐወቁ።'),
  ('877e3ca3-9f1a-512d-af30-97f6809fc134', 'cbb17e43-316d-5ce5-a1b1-7164b0d9b0d3', '4e9ee1e3-fd0a-524c-a3de-ebbfe93ba25d', 26, 26, 'እኔን የወደድህበት ፍቅር በእነርሱ ይኖር ዘንድ፥ እኔም በእነርሱ እኖር ዘንድ ስምህን ነገርኋቸው፤ ደግሞም እነግራቸዋለሁ፤”'),
  ('cd1114a7-d94e-55f6-abaf-5d5b1d2ee227', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 1, 1, 'ጌታችን ኢየሱስም ይህን ተናግሮ አትክልት ወደ አለበት ስፍራ ወደ ቄድሮስ ወንዝ ማዶ ከደቀ መዛሙርቱ ጋር ወጣ፤ ከደቀ መዛሙርቱም ጋር ወደዚያ ገባ።'),
  ('6706ca45-392f-50fa-a3d9-e662a7ff2466', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 2, 2, 'አሳልፎ የሚሰጠው ይሁዳም ያን ስፍራ ያውቀው ነበር፤ ጌታችን ኢየሱስ ከደቀ መዛሙርቱ ጋር ወደዚያ ብዙ ጊዜ ይሄድ ነበርና።'),
  ('a853d959-77a9-56ce-a043-88e2948fe365', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 3, 3, 'ይሁዳም ከካህናት አለቆችና ከፈሪሳውያን ወታደሮችን ተቀበለ፤ ሎሌዎቻቸውንም በረዳትነት ወሰደ፤ ፋኖስና የችቦ መብራት፥ የጦር መሣሪያም ይዞ ወደዚያ ሄደ።'),
  ('a4286a64-f979-56ff-a7fb-faac0763234a', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 4, 4, 'ጌታችን ኢየሱስም የሚደርስበትን ሁሉ ዐውቆ ወደ እነርሱ ወደ ውጭ ወጣና፥ “ማንን ትሻላችሁ?” አላቸው።'),
  ('dc9d919a-3307-5b9e-a73c-159df79ffc6b', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 5, 5, '“የናዝሬቱን ኢየሱስን” ብለው መለሱለት፤ ጌታችን ኢየሱስም፥ “እኔ ነኝ” አላቸው፤ አሳልፎ የሰጠው ይሁዳም በዚያው አብሮአቸው ቆሞ ነበር።'),
  ('eadc5c15-d015-5c50-a859-2bbde68e3707', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 6, 6, 'ጌታችን ኢየሱስም፥ “እኔ ነኝ” ባላቸው ጊዜ፤ ወደ ኋላቸው ተመልሰው በምድር ላይ ወደቁ።'),
  ('80892757-f89a-5957-a213-94b67dfe81f3', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 7, 7, 'ከዚህም በኋላ እንደገና፥ “ማንን ትሻላችሁ?” ብሎ ጠየቃቸው፤ እነርሱም፥ “የናዝሬቱን ኢየሱስን” አሉት።'),
  ('ee222358-61b1-5c9b-a295-664c99a05d90', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 8, 8, 'ጌታችን ኢየሱስም፥ “እኔ ነኝ አልኋችሁ፤ እኔን የምትሹ ከሆነ እነዚህን ተዉአቸው፤ ይሂዱ” አላቸው።'),
  ('3da0f93f-c400-5aca-a79f-c0a8abf12457', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 9, 9, 'ይህም፥ “ከእነዚህ ከሰጠኸኝ አንድ ስንኳ አልጠፋም” ያለው ቃሉ ይፈጸም ዘንድ ነው።'),
  ('a8f8186d-5e5d-50e3-a022-578b39731974', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 10, 10, 'ስምዖን ጴጥሮስም ሾተል ነበረው፤ ሾተሉንም መዝዞ የሊቀ ካህናቱን አገልጋይ መትቶ ቀኝ ጆሮውን ቈረጠው፤ የዚህም አገልጋይ ስም ማልኮስ ይባል ነበር።'),
  ('aecba314-0b1d-5305-a11c-b36d77654f51', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'c1fdfe81-ecb3-5c7c-a92e-104e926c455c', 11, 11, 'ጌታችን ኢየሱስም ጴጥሮስን፥ “ሾተልህን ወደ አፎቷ መልስ፤ አብ የሰጠኝን ጽዋ ሳልጠጣ እተወዋለሁን?” አለው።'),
  ('c0e85d73-f2f4-5aa2-a4af-9a30a0f676d2', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '82f39167-2b99-5060-a473-b7895ccc0705', 1, 12, 'ጭፍሮችና የሺ አለቃው፥ የአይሁድም ሎሌዎች ጌታችን ኢየሱስን ይዘው አሰሩት።'),
  ('cf69f5a8-c62c-5a52-a4f5-ecb6b1bf2273', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '82f39167-2b99-5060-a473-b7895ccc0705', 2, 13, 'አስቀድሞም ወደ ሐና ወሰዱት፤ በዚያች ዓመት የካህናት አለቃ ለነበረው ለቀያፋ አማቱ ነበርና።'),
  ('dc096d21-d441-53bc-a2f5-adf7dcc593de', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '82f39167-2b99-5060-a473-b7895ccc0705', 3, 14, 'ቀያፋም “ስለ ሕዝቡ ሁሉ አንድ ሰው ቢሞት ይሻላል” ብሎ አይሁድን የመከራቸው ነበር።'),
  ('1789c501-0c80-5264-a07c-b1f6591e4251', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'f22383bc-2b82-55d4-acc9-a27f2c59e576', 1, 15, 'ስምዖን ጴጥሮስና ሌላው ደቀ መዝሙርም ጌታችን ኢየሱስን ከሩቅ ተከተሉት፤ ያ ደቀ መዝሙር ግን በሊቀ ካህናቱ ዘንድ የታወቀ ነበር፤ ከጌታችን ኢየሱስ ጋርም ወደ ሊቀ ካህናቱ ግቢ ገባ።'),
  ('5c6d4ab5-12bb-5511-a663-8d379be08c83', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'f22383bc-2b82-55d4-acc9-a27f2c59e576', 2, 16, 'ጴጥሮስ ግን በስተውጭ በበሩ ቆሞ ነበር፤ ያም በሊቀ ካህናቱ ዘንድ ይታወቅ የነበረው ሌላው ደቀ መዝሙር ወጣና ለበረኛዪቱ ነግሮ ጴጥሮስን አስገባው።'),
  ('16d56b9e-fe04-5ec5-a9bc-f468f50f9adf', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'f22383bc-2b82-55d4-acc9-a27f2c59e576', 3, 17, 'በረኛዪቱ አገልጋይም፥ “አንተም ከዚያ ሰው ደቀ መዛሙርት ወገን አይደለህምን?” አለችው፤ እርሱም፥ “አይደለሁም” አላት።'),
  ('a12700b5-6d9c-5690-af29-e6a27ccdbffd', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'f22383bc-2b82-55d4-acc9-a27f2c59e576', 4, 18, 'አገልጋዮችና ሎሌዎችም በዚያ ቆመው እሳት አንድደው ይሞቁ ነበር፤ የዚያች ሌሊት ብርድ ጽኑ ነበርና፤ ጴጥሮስም ከእነርሱ ጋር ቆሞ ይሞቅ ነበረ።'),
  ('4d6eb072-bdd4-5014-acc9-b2fd82750740', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 1, 19, 'ሊቀ ካህናቱም ጌታችን ኢየሱስን፦ ስለ ደቀ መዛሙርቱና ስለ ትምህርቱ ጠየቀው።'),
  ('c1e82af0-fd31-52ec-a7aa-7bfdb19707c4', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 2, 20, 'ጌታችን ኢየሱስም መልሶ እንዲህ አለው፥ “እኔ ለዓለም በግልጥ ተናገርሁ፤ አይሁድ ሁሉ በሚሰበሰቡበት በምኵራብም፥ በቤተ መቅደስም ሁልጊዜ አስተማርሁ፤ በስውርም የተናገርሁት አንዳች ነገር የለም።'),
  ('f3bc4684-c175-5554-aa7c-316dd99743c9', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 3, 21, 'እንግዲህ እኔን ለምን ትጠይቀኛለህ? የተናገርሁትን የሰሙኝን ጠይቃቸው፤ እኔም የተናገርሁትን እነሆ፥ እነርሱ ያውቃሉ።”'),
  ('416426bb-f654-5fb8-adcd-e0cc410eeb3e', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 4, 22, 'ይህንም ባለጊዜ ከቆሙት ሎሌዎች አንዱ፥ “ለሊቀ ካህናቱ እንዲህ ትመልስለታለህን?” ብሎ ጌታችን ኢየሱስን በጥፊ መታው።'),
  ('7d3e4f39-9a0a-503d-a0cf-d6aa7a10864f', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 5, 23, 'ጌታችን ኢየሱስም መልሶ፥ “ክፉ ተናግሬ እንደ ሆንሁ ስለ ክፉ መስክርብኝ፤ መልካም ተናግሬ እንደ ሆንሁ ግን ለምን ትመታኛለህ?” አለው።'),
  ('70318d97-a7a2-588d-a2b0-73abf905d480', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 6, 24, 'ሐናም ጌታችን ኢየሱስን እንደ ታሰረ ወደ ሊቀ ካህናቱ ወደ ቀያፋ ላከው።'),
  ('49838c4e-57dc-5c8d-aedf-4ca2ada84e7e', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 7, 25, 'ስምዖን ጴጥሮስም ቆሞ እሳት ይሞቅ ነበር፤ “አንተስ ከእርሱ ደቀ መዛሙርት ወገን አይደለህምን?” አሉት፤ እርሱም፥ “አይደለሁም” ብሎ ካደ።'),
  ('adecd89b-8859-5219-a782-ee6a5669184d', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 8, 26, 'ጴጥሮስ ጆሮውን ከቈረጠው ሰው ዘመዶች ወገን የሆነ ከሊቀ ካህናቱ አገልጋዮችም አንድ ሰው፥ “እኔ በአትክልት ቦታ ውስጥ ከእርሱ ጋር አይችህ አልነበረምን?” አለው።'),
  ('14b3a842-33a8-5374-a3a8-998542a1a8e9', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', '8696ff8b-48f5-5464-acba-495ab38baf8b', 9, 27, 'ጴጥሮስም ደግሞ ካደ፤ ያንጊዜም ዶሮ ጮኸ።'),
  ('eb9959eb-a3a8-5eb5-ad73-d07072384fb6', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 1, 28, 'ጌታችን ኢየሱስንም ከቀያፋ ወደ ፍርድ አደባባይ ወሰዱት፤ አይሁድ ግን ፈጽሞ ስለ ነጋ የፋሲካውን በግ ሳይበሉ እንዳይረክሱ ወደ ፍርድ አደባባይ አልገቡም።'),
  ('7f61c383-3002-58c9-acd9-90d237fc48a9', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 2, 29, 'ጲላጦስም ወደ እነርሱ ወደ ውጭ ወጥቶ፥ “ይህን ሰው ወደ እኔ ያመጣችሁበት በደሉ ምንድነው?” አላቸው።'),
  ('7dc43996-a677-5c41-a056-d6aa749ba4d7', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 3, 30, 'እነርሱም፥ “ክፉ የሠራ ባይሆንስ ወደ አንተ አሳልፈን ባልሰጠነው ነበር” ብለው መለሱለት።'),
  ('b835f25e-a560-59a5-a647-28a8ebf01eeb', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 4, 31, 'ጲላጦስም፥ “እናንተ ወስዳችሁ እንደ ሕጋችሁ ፍረዱበት” አላቸው፤ አይሁድም፥ “እኛስ ማንንም ልንገድል አልተፈቀደልንም” አሉት።'),
  ('6482b9f0-0f99-5497-af81-c2f366942422', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 5, 32, 'ይህም በምን ዐይነት ሞት ይሞት ዘንድ እንዳለው ሲያመለክት የተናገረው የጌታችን የኢየሱስ ቃል ይፈጸም ዘንድ ነው።'),
  ('2d04cfd3-ea8c-5bec-a9c0-b09d85c34ae4', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 6, 33, 'ጲላጦስም እንደገና ወደ ፍርድ አደባባይ ገብቶ ጌታችን ኢየሱስን ጠራና፥ “የአይሁድ ንጉሥ አንተ ነህን?” አለው።'),
  ('4e888b1f-ffaf-54fa-a6d4-b252651d21b6', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 7, 34, 'ጌታችን ኢየሱስም፥ “ይህን የምትናገር ከራስህ ነውን? ወይስ ስለ እኔ የነገረህ ሌላ አለን?” ብሎ መለሰለት።'),
  ('e6ad46e0-1e85-5cd5-aaf7-f4895ab69835', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 8, 35, 'ጲላጦስም መልሶ፥ “እኔ አይሁዳዊ ነኝን? ለእኔ አሳልፈው የሰጡህ ወገኖችህና ሊቃነ ካህናት አይደሉምን? Aረ ምን አድርገሃል?” አለው።'),
  ('5ce5f881-d1f7-5253-a920-dec94365e4b2', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 9, 36, 'ጌታችን ኢየሱስም፥ “የእኔ መንግሥት ከዚህ ዓለም አይደለችም፤ መንግሥቴስ በዚህ ዓለም ብትሆን ኖሮ ለአይሁድ እንዳልሰጥ አሽከሮች በተዋጉልኝ ነበር፤ አሁንም መንግሥቴ ከዚህ አይደለችም” ብሎ መለሰለት።'),
  ('993f44d9-da29-5cfb-a944-b952fbe0a1b5', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 10, 37, 'ጲላጦስም፥ “እንግዲያ አንተ ንጉሥ ነህን?” አለው፤ ጌታችን ኢየሱስም መልሶ፥ “እኔ ንጉሥ እንደ ሆንሁ አንተ ራስህ ትላለህ፤ እኔ ስለዚህ ተወለድሁ፤ ስለዚህም ለእውነት ልመሰክር ወደ ዓለም መጣሁ፤ ከእውነት የሆነ ሁሉ ቃሌን ይሰማኛል” አለው።'),
  ('b8ef6f1c-daf6-5047-acae-8c76e8e52b6c', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 11, 38, 'ጲላጦስም፥ “እውነት ምንድነው?” አለው፤ ይህንም ተናግሮ ዳግመኛ ወደ አይሁድ ወጣና እንዲህ አላቸው፥ “እኔ አንዲት ስንኳን በደል አላገኘሁበትም።'),
  ('9bcc95bc-ecad-5fe3-ad16-d1342333455d', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 12, 39, 'ነገር ግን በየዓመቱ በፋሲካ በዓል ከእስረኞች አንድ እንድፈታላችሁ ልማድ አላችሁ፤ እንግዲህ የአይሁድን ንጉሥ ልፈታላችሁ ትወዳላችሁን?” አላቸው።'),
  ('6eb9b99d-b14e-5202-aabc-7bd61b2b93e6', 'f81a99e5-6e30-52e2-ad4b-69ec564b9665', 'ddc13521-914f-5796-a698-eeae3a75f82e', 13, 40, 'ዳግመኛም ድምፃቸውን ከፍ አድርገው፥ “በርባንን እንጂ ይህን አይደለም፤” አሉ፤ በርባን ግን ወንበዴ ነበር።'),
  ('4c94b5ee-51f8-5ce3-a664-823b93a92468', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 1, 1, 'ከዚህም በኋላ ጲላጦስ ጌታችን ኢየሱስን ይዞ ገረፈው።'),
  ('741a31ff-0801-5c98-afcc-bd3441b41ff1', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 2, 2, 'ጭፍሮችም የእሾህ አክሊል ጐንጕነው በራሱ ላይ ደፉበት፤ የቀይ ሐር መጐናጸፊያም አለበሱት።'),
  ('f972a436-785e-58e1-adfc-4c6914dc6b24', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 3, 3, 'ወደ እርሱም እየመጡ፥ “የአይሁድ ንጉሥ ሆይ፥ ሰላም ለአንተ ይሁን” ይሉት ነበር፤ በጥፊም ይመቱት ነበር።'),
  ('f143d42d-711c-5174-afc0-5529080c88b0', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 4, 4, 'ጲላጦስም እንደገና ወደ ውጭ ወጣና፥ “እነሆ፥ በእርሱ ላይ አንዲት በደል ስንኳን ያገኘሁበት እንደሌለ ታውቁ ዘንድ ወደ ውጭ አወጣላችኋለሁ” አላቸው።'),
  ('84505f17-6fbd-58c7-ab82-09d9d0c23355', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 5, 5, 'ጌታችን ኢየሱስም የእሾህ አክሊል ደፍቶ፥ የቀይ ሐር መጐናጸፊያም ለብሶ ወደ ውጭ ወጣ፤ ጲላጦስም፥ “እነሆ፥ ሰውዬው” አላቸው።'),
  ('bd57c58a-e9e3-53de-ab8d-163b00ee56bd', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 6, 6, 'ሊቃነ ካህናትና ሎሌዎቻቸውም ባዩት ጊዜ፥ “ስቀለው! ስቀለው!” እያሉ ጮሁ፤ ጲላጦስም፥ “እናንተ ራሳችሁ ውሰዱና ስቀሉት፤ እኔስ በእርሱ ላይ በደል አላገኘሁበትም” አላቸው።'),
  ('30359c2d-84c9-5651-a02e-61228f59b0b2', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 7, 7, 'አይሁድም መልሰው፥ “እኛ ሕግ አለን፤ እንደ ሕጋችንም ሊሞት ይገባል፤ ራሱን የእግዚአብሔር ልጅ አድርጎአልና” አሉት።'),
  ('c70b584c-312d-58c8-a22d-bc010a47ebf2', '698dabb8-98d3-5c38-ab30-190a32183524', '63f81eba-5c80-5f8e-a26c-742f53b05a8e', 8, 8, 'ጲላጦስም ይህን ነገር ሰምቶ እጅግ ፈራ።'),
  ('fc6d504a-26b0-570e-a1cd-96e1e210f8b0', '698dabb8-98d3-5c38-ab30-190a32183524', '89003394-9e6d-5d7e-a783-f4258e1c9e70', 1, 9, 'ደግሞም ወደ ፍርድ አደባባይ ገባና ጌታችን ኢየሱስን፥ “አንተ ከወዴት ነህ?” አለው፤ ጌታችን ኢየሱስ ግን ምንም አልመለሰለትም።'),
  ('cdab0d03-2af4-5973-ab23-87c18aff6bf8', '698dabb8-98d3-5c38-ab30-190a32183524', '89003394-9e6d-5d7e-a783-f4258e1c9e70', 2, 10, 'ጲላጦስም፥ “ለእኔም አትነግረኝምን? ልሰቅልህ ሥልጣን እንደ አለኝ፥ ወይም ልፈታህ ሥልጣን እንዳለኝ፥ አታውቅምን?” አለው።'),
  ('16735936-79a2-5cd6-a3b7-abab643f70a2', '698dabb8-98d3-5c38-ab30-190a32183524', '89003394-9e6d-5d7e-a783-f4258e1c9e70', 3, 11, 'ጌታችን ኢየሱስም፥ “ከሰማይ ካልተሰጠህ በቀር በእኔ ላይ አንዳች ሥልጣን የለህም፤ ስለዚህ ለአንተ አሳልፎ የሰጠኝ ሰው ታላቅ ኀጢኣት አለበት” አለው።'),
  ('dd4e654a-8817-53fd-a2c8-8f46ccaa6117', '698dabb8-98d3-5c38-ab30-190a32183524', '89003394-9e6d-5d7e-a783-f4258e1c9e70', 4, 12, 'ስለዚህም ጲላጦስ ሊፈታው ወድዶ ነበር፤ አይሁድ ግን፥ “ይህን ከፈታኸው የቄሣር ወዳጅ አይደለህም፤ ራሱን ንጉሥ የሚያደርግ ሰው ሁሉ በቄሣር ላይ የሚያምፅ ነውና” ብለው ጮሁ።'),
  ('69fd8639-4a1a-5a0a-a894-a1d271d42526', '698dabb8-98d3-5c38-ab30-190a32183524', 'f05683b0-fdb9-5b78-a6a2-35adde0e1e6c', 1, 13, 'ጲላጦስም ይህን ሰምቶ ጌታችን ኢየሱስን ወደ ውጭ አወጣው፤ በዕብራይስጥም ገበታ ተብሎ በሚጠራው “ጸፍጸፍ” በሚሉት ቦታ ላይ በወንበር ተቀመጠ።'),
  ('61715e87-d415-56a4-abee-bf3b1a9a68a7', '698dabb8-98d3-5c38-ab30-190a32183524', 'f05683b0-fdb9-5b78-a6a2-35adde0e1e6c', 2, 14, 'የፋሲካም የመዘጋጀት ቀን ነበር፤ ጊዜዉም ስድስት ሰዓት ያህል ነበር፤ ጲላጦስም አይሁድን፥ “እነሆ፥ ንጉሣችሁ” አላቸው፤'),
  ('8bc9ec1d-4ec3-5863-ae06-848e2328917e', '698dabb8-98d3-5c38-ab30-190a32183524', 'f05683b0-fdb9-5b78-a6a2-35adde0e1e6c', 3, 15, 'እነርሱ ግን፥ “አስወግደው! ስቀለው!” እያሉ ጮሁ። ጲላጦስም፥ “ንጉሣችሁን ልስቀለውን?” አላቸው፤ ሊቃነ ካህናቱም፥ “ከቄሣር በቀር ሌላ ንጉሥ የለንም” ብለው መለሱ።'),
  ('cf27a117-da27-5019-acfe-fb2fc7dceaeb', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 1, 16, 'ከዚህ በኋላ ሊሰቅሉት አሳልፎ ሰጣቸው፤ ጌታችን ኢየሱስንም ተቀብለው ወሰዱት።'),
  ('e9c24a60-ac26-59a2-ac65-12c1da48636d', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 2, 17, 'መስቀሉንም ተሸክሞ በዕብራይስጥ ጎልጎታ ወደ ተባለው ቀራንዮ ወደሚባል ቦታ ወጣ።'),
  ('ccefcf51-c4d7-5d76-a309-259133320dca', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 3, 18, 'በዚያም ሰቀሉት፤ ከእርሱም ጋር አንዱን በቀኝ፥ አንዱንም በግራ አድርገው ሌሎች ሁለት ወንበዴዎችን ሰቀሉ፤ ኢየሱስንም በመካከላቸው ሰቀሉ።'),
  ('c34036fc-7f8e-5ee7-a70c-d39ad568b1aa', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 4, 19, 'ጲላጦስም ጽሕፈት ጽፎ በመስቀሉ ላይ አኖረ፤ ጽሕፈቱም፥ “የአይሁድ ንጉሥ የናዝሬቱ ኢየሱስ” የሚል ነበር።'),
  ('3ef9bc25-15ad-5cac-a420-b9c82893ceef', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 5, 20, 'ከአይሁድም ይህቺን ጽሕፈት ያነበብዋት ብዙዎች ነበሩ፤ ጌታችን ኢየሱስን የሰቀሉበት ቦታ ለከተማ ቅርብ ነበርና፤ ጽሕፈቱም የተጻፈው በዕብራይስጥ፥ በሮማይስጥና በግሪክ ነበር።'),
  ('a5554421-70f1-5663-a17c-75bd2d6e5b04', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 6, 21, 'ሊቃነ ካህናትም ጲላጦስን አሉት፥ “እርሱ ራሱ ‘እኔ የአይሁድ ንጉሥ ነኝ’ እንዳለ እንጂ የአይሁድ ንጉሥ ብለህ አትጻፍ።”'),
  ('f79c1147-c3c9-5f65-a153-e0b75e2dd1fd', '698dabb8-98d3-5c38-ab30-190a32183524', '80bde661-d52f-5d86-aa6e-a920a282bef9', 7, 22, 'ጲላጦስም፥ “የጻፍሁትን ጻፍሁ” ብሎ መለሰላቸው።'),
  ('06d78c80-2daf-54db-a48c-effa1e89cad0', '698dabb8-98d3-5c38-ab30-190a32183524', '7e0ce396-a40b-50a4-a520-73b3c5ff9b4a', 1, 23, 'ጭፍሮችም ጌታችን ኢየሱስን በሰቀሉት ጊዜ ልብሶቹን ወስደው ከጭፍሮቹ ለእያንዳንዱ አራት ክፍል አድርገው መደቡት፤ ቀሚሱንም ወሰዱ፤ ቀሚሱም ከላይ ጀምሮ የተሠራ ሥረወጥ እንጂ የተሰፋ አልነበረም።'),
  ('7dec6948-9471-5884-a937-2ab77a7021ec', '698dabb8-98d3-5c38-ab30-190a32183524', '7e0ce396-a40b-50a4-a520-73b3c5ff9b4a', 2, 24, 'እርስ በርሳቸውም፥ “ዕጣ እንጣጣልና ለደረሰ ይድረሰው እንጂ አንቅደደው ተባባሉ፤” ይህም “ልብሶችን ለራሳቸው ተካፈሉ፤ በቀሚሴም ላይ ዕጣ ተጣጣሉ” ያለው የመጽሐፍ ቃል ይፈጸም ዘንድ ነው፤ ጭፍሮችም እንዲሁ አደረጉ።'),
  ('839867f4-1e02-5f57-af5c-8b0860bf6be8', '698dabb8-98d3-5c38-ab30-190a32183524', 'f9f0a4a7-6c31-58da-a132-46342d337131', 1, 25, 'በጌታችን በኢየሱስ መስቀል አጠገብም እናቱ፥ የእናቱም እኅት፥ የቀለዮጳም ሚስት ማርያም፥ መግደላዊት ማርያምም ቆመው ነበር።'),
  ('e1e2d224-3d95-545b-a266-ba737775ff0a', '698dabb8-98d3-5c38-ab30-190a32183524', 'f9f0a4a7-6c31-58da-a132-46342d337131', 2, 26, 'ጌታችን ኢየሱስም እናቱንና የሚወደውን ደቀ መዝሙሩን ቆመው ባያቸው ጊዜ እናቱን፥ “አንች ሆይ፥ እነሆ፥ ልጅሽ” አላት።'),
  ('f350ae1e-3843-568f-aff0-71ffa514d27c', '698dabb8-98d3-5c38-ab30-190a32183524', 'f9f0a4a7-6c31-58da-a132-46342d337131', 3, 27, 'ከዚህም በኋላ ደቀ መዝሙሩን፥ “እናትህ እነኋት” አለው፤ ከዚያችም ሰዓት ጀምሮ ደቀ መዝሙሩ ተቀብሎ ወደ ቤቱ ወሰዳት።'),
  ('521c0c9c-9648-5e52-ae69-6f916ea840d2', '698dabb8-98d3-5c38-ab30-190a32183524', '4abdcd37-f6ca-5f50-a30e-add7f4b7de3f', 1, 28, 'ከዚህም በኋላ ጌታችን ኢየሱስ ሁሉ እንደ ተፈጸመ ባየ ጊዜ የመጽሐፉ ቃል ይፈጸም ዘንድ “ተጠማሁ” አለ።'),
  ('0100f45a-0740-5223-ab21-22ce2b6a7a40', '698dabb8-98d3-5c38-ab30-190a32183524', '4abdcd37-f6ca-5f50-a30e-add7f4b7de3f', 2, 29, 'በዚያም ሆምጣጤ የመላበት ማሰሮ ነበር፤ እነርሱም ሆምጣጤውን በሰፍነግ ሞልተው በስምዛ ዘንግ ከአፉ አገናኝተው ጨመቁት።'),
  ('e5557cf0-c5ab-5e35-ae7d-ba2fc33048d1', '698dabb8-98d3-5c38-ab30-190a32183524', '4abdcd37-f6ca-5f50-a30e-add7f4b7de3f', 3, 30, 'ጌታችን ኢየሱስም ሆምጣጤውን ቀምሶ፥ “ሁሉ ተፈጸመ” አለ፤ ራሱንም አዘንብሎ ነፍሱን ሰጠ።'),
  ('759ec429-94a4-5162-a6b2-bf8697d7bf19', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 1, 31, 'አይሁድ ግን የመዘጋጀት ቀን ነበርና፥ የዚያች ሰንበትም ቀን ታላቅ ናትና “ሥጋቸው በሰንበት በመስቀል ላይ አይደር” አሉ፤ ጭን ጭናቸውንም ሰብረው ያወርዷቸው ዘንድ ጲላጦስን ለመኑት።'),
  ('21e5091d-157d-5830-abed-c50dfb685eee', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 2, 32, 'ጭፍሮችም መጥተው ከእርሱ ጋር የተሰቀሉትን የአንደኛውንና የሁለተኛውን ጭኖች ሰበሩ።'),
  ('39a23a7b-d258-5e48-a56c-0a5ad718d023', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 3, 33, 'ወደ ጌታችን ኢየሱስም ሄደው ፈጽሞ እንደ ሞተ ባዩ ጊዜ ጭኑን አልሰበሩም።'),
  ('3a25648f-ba78-5d44-aa93-6257f367fe3f', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 4, 34, 'ነገር ግን ከጭፍሮቹ አንዱ የቀኝ ጎኑን በጦር ወጋው፤ ያንጊዜም ከእርሱ ደምና ውኃ ወጣ።'),
  ('3c6a987b-d97c-5084-aa72-a293dc8306d6', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 5, 35, 'ያየውም መሰከረ፤ ምስክርነቱም እውነት ነው፤ እርሱም እናንተ ልታምኑ እውነት እንደሚናገር ያውቃል።'),
  ('60c97cce-e939-5787-a7df-4671ed3a26a6', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 6, 36, 'ይህ ሁሉ የሆነው “ከእርሱ ዐፅሙን አትስበሩ” ያለው የመጽሐፍ ቃል ይፈጸም ዘንድ ነው።'),
  ('fdeb1ba6-de9e-5680-ad10-c379620b8c26', '698dabb8-98d3-5c38-ab30-190a32183524', 'c8ec3637-b2b9-5bfb-aafc-285f830e559c', 7, 37, 'ሌላዉም መጽሐፍ ደግሞ“ የወጉትን ያዩታል” ይላል።'),
  ('b7c5457f-6b13-599f-a117-c85c2c48a57d', '698dabb8-98d3-5c38-ab30-190a32183524', '52b4ffcf-34d5-532a-a3ec-b6daf7ef6d84', 1, 38, 'ከዚህም በኋላ አይሁድን ስለፈራ በስውር የጌታችን የኢየሱስ ደቀ መዝሙር የነበረው የአርማትያስ ሰው ዮሴፍ የጌታችን የኢየሱስን ሥጋ ይወስድ ዘንድ ጲላጦስን ለመነው፤ ጲላጦስም ፈቀደለት። እርሱም ሄዶ የጌታችን የኢየሱስን ሥጋ ወሰደ።'),
  ('fa4ff439-4229-542a-a2fc-f4e795815cd8', '698dabb8-98d3-5c38-ab30-190a32183524', '52b4ffcf-34d5-532a-a3ec-b6daf7ef6d84', 2, 39, 'ቀድሞ በሌሊት ወደ ጌታችን ኢየሱስ ሄዶ የነበረው ኒቆዲሞስም መጣ፤ ቀብተውም የሚቀብሩበትን መቶ ወቄት የከርቤና የሬት ቅልቅል ሽቶ አመጣ።'),
  ('e0a3a686-d4d4-5dc6-ac95-2b0a84ad4886', '698dabb8-98d3-5c38-ab30-190a32183524', '52b4ffcf-34d5-532a-a3ec-b6daf7ef6d84', 3, 40, 'እንደ አይሁድ አገናነዝ ሥርዐትም የጌታችን የኢየሱስን ሥጋ ወስደው ከሽቱ ጋር በበፍታ ገነዙት።'),
  ('074850f3-4d0f-5328-ac8c-fe28739caa77', '698dabb8-98d3-5c38-ab30-190a32183524', '52b4ffcf-34d5-532a-a3ec-b6daf7ef6d84', 4, 41, 'በዚያም በተሰቀለበት ቦታ የአትክልት ስፍራ ነበር፤ በዚያ የአትክልት ስፍራ ውስጥም በውስጡ ሰው ያልተቀበረበት አዲስ መቃብር ነበር።'),
  ('78d34d08-f549-5fc8-a1d3-cc9787865f87', '698dabb8-98d3-5c38-ab30-190a32183524', '52b4ffcf-34d5-532a-a3ec-b6daf7ef6d84', 5, 42, 'ጌታችን ኢየሱስንም በዚያ ቀበሩት፤ ለአይሁድ የመሰናዳት ቀን ነበርና፤ መቃብሩም ለሰቀሉበት ቦታ ቅርብ ነበር።'),
  ('94ee659e-6255-511a-a1c0-24a47b60110a', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 1, 1, 'ከሳምንቱም በመጀመሪያዉ ቀን ማርያም መግደላዊት በማለዳ ገና ጨለማ ሳለ ወደ መቃብር መጣች፤ ድንጋዩንም ከመቃብሩ አፍ ተነሥቶ አገኘችው።'),
  ('6073ffee-4572-57bc-af6a-7d11d180a304', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 2, 2, 'ፈጥናም ወደ ስምዖን ጴጥሮስና ጌታችን ኢየሱስ ይወደው ወደ ነበረው ወደዚያ ወደ ሌላዉ ደቀ መዝሙር መጥታ፥ “ጌታዬን ከመቃብር ወስደውታል፤ ወዴትም እንደ ወሰዱት አላውቅም” አለቻቸው።'),
  ('f7e0e18e-83f7-5f0f-adbb-dab6acd01204', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 3, 3, 'ጴጥሮስና ያ ሌላዉ ደቀ መዝሙርም ወጥተው ወደ መቃብሩ ሄዱ።'),
  ('a547d07d-0875-577a-a687-7756770666cc', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 4, 4, 'ሁለቱም በአንድነት ሲሮጡ ያ ሌላዉ ደቀ መዝሙር ጴጥሮስን ቀድሞት ወደ መቃብሩ ደረሰ።'),
  ('9e3d1e7a-615f-5386-a482-d05427c11f13', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 5, 5, 'ጐንበስ ብሎም ሲመለከት በፍታዉን ተቀምጦ አየ፤ ነገር ግን ወደ ውስጥ አልገባም።'),
  ('b10372f9-29b3-55bc-aa44-1061bc93734e', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 6, 6, 'ስምዖን ጴጥሮስም ተከትሎት ደረሰና ወደ መቃብሩ ገባ፤'),
  ('56c6a0ab-e8e8-5baf-acc7-ad8a0619751a', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 7, 7, 'በፍታዉንም በአንድ ወገን ተቀምጦ አየ፤ በራሱ ላይ የነበረው መጠምጠሚያም ሳይቃወስ ለብቻው ተጠቅልሎ አየ፤ ከበፍታዉ ጋርም አልነበረም።'),
  ('0d1f54e6-31b5-5dc8-a916-5f7b462cbf61', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 8, 8, 'ከዚህም በኋላ አስቀድሞ ወደ መቃብሩ የደረሰው ሌላዉ ደቀ መዝሙር ገባ፤ አይቶም አመነ፤'),
  ('5f53aa29-9b92-567a-a9c1-f9b9cfea66fc', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 9, 9, 'ከሙታን ተለይቶ ይነሣ ዘንድ እንደ አለው በመጻሕፍት የተጻፈውን ገና አላወቁም ነበርና።'),
  ('4f2bb72f-2255-5292-a4ec-4faf1991b754', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '9b8822de-3636-5f15-a67b-a139f652524c', 10, 10, 'ከዚህም በኋላ ደቀ መዛሙርቱ ተመልሰው ወደ ቤታቸው ገቡ።'),
  ('5d819fa2-5976-5160-a0fa-39b637ca16b3', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 1, 11, 'ማርያም ግን ከመቃብሩ በስተውጭ እያለቀሰች ቆማ ነበረ፤ እያለቀሰችም ወደ መቃብሩ ጐንበስ ብላ ተመለከተች።'),
  ('a1a5fc2d-ac1f-5669-a60d-ec52f1f2ba96', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 2, 12, 'ሁለት መላእክትንም ነጭ ልብስ ለብሰው የጌታችን የኢየሱስ ሥጋ በነበረበት ቦታ አንዱ በራስጌ፥ አንዱም በግርጌ ተቀምጠው አየች።'),
  ('b18c038f-e709-59ca-a7c0-8d4c301c3902', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 3, 13, 'እነዚያ መላእክትም፥ “አንቺ ሴት፥ ምን ያስለቅስሻል?” አሉአት፤ እርስዋም፥ “ጌታዬን ከመቃብር ውስጥ ወስደውታል፤ ወዴትም እንደ ወሰዱት አላውቅም” አለቻቸው።'),
  ('022de6b7-2910-5b94-a346-b338122ec6bb', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 4, 14, 'ይህንም ተናግራ ወደ ኋላዋ መለስ ስትል ጌታችን ኢየሱስን ቆሞ አየችው፤ ጌታችን ኢየሱስም እንደ ሆነ አላወቀችም።'),
  ('edfa70aa-fa04-5ba9-a634-6fa6f58d1a28', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 5, 15, 'ጌታችን ኢየሱስም፥ “አንቺ ሴት፥ ምን ያስለቅስሻል? ማንንስ ትሺያለሽ?” አላት፤ እርስዋ ግን የአትክልት ቦታ ጠባቂ መስሎአት፥ “ጌታዬ፥ አንተ ወስደኸው እንደ ሆነ ሄጄ ወደ እኔ እንዳመጣውና ሽቱ እንድቀባው ወዴት እንደ አኖርኸው ንገረኝ” አለችው።'),
  ('a1ee99cd-06a4-5c05-ada1-b53c9fb5abdf', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 6, 16, 'ጌታችን ኢየሱስም፥ “ማርያም!” አላት፤ እርስዋም መለስ ብላ በዕብራይስጥ ቋንቋ፥ “ረቡኒ!” አለችው፤ ትርጓሜዉም “መምህር” ማለት ነው።'),
  ('c0c41e7f-1b62-5ab7-a2c1-526268d0e469', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 7, 17, 'ጌታችን ኢየሱስም፥ “አትንኪኝ፤ ገና ወደ አባቴ አላረግሁምና፤ ነገር ግን ወደ ወንድሞች ሂጂና፦ ወደ አባቴ፥ ወደ አባታችሁ ወደ አምላኬ፥ ወደ አምላካችሁም አርጋለሁ አለ ብለሽ ንገሪአቸው” አላት።'),
  ('20ed3aef-cee9-5905-a2c0-2153a98a9232', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '2ac9f4a9-ea4f-5f6d-acb1-975e0fa0af9d', 8, 18, 'ማርያም መግደላዊትም ሄደች፤ ጌታን እንደ አየች፥ ይህንም እንዳላት ለደቀ መዛሙርቱ ነገረቻቸው።'),
  ('3bffcee7-ec23-54b6-a54b-c9038b362343', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '34733372-7a0f-5608-a581-0e36aac0cb2a', 1, 19, 'ያም ከሳምንቱ የመጀመሪያው ቀን በመሸ ጊዜ ደቀ መዛሙርቱ አይሁድን ስለ ፈሩ ተሰብስበው የነበሩበት ቤት ደጁ ተቈልፎ ሳለ ጌታችን ኢየሱስ መጥቶ በመካከላቸው ቆመና፥ “ሰላም ለእናንተ ይሁን” አላቸው።'),
  ('add46b71-0a3d-5c3d-afff-e8a9c524e0f5', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '34733372-7a0f-5608-a581-0e36aac0cb2a', 2, 20, 'ይህንም ብሎ እጆቹንና ጎኑን አሳያቸው፤ ደቀ መዛሙርቱም ጌታችንን ባዩት ጊዜ ደስ አላቸው።'),
  ('eda9841e-e17b-5680-af3f-d7fb5af3d7bd', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '34733372-7a0f-5608-a581-0e36aac0cb2a', 3, 21, 'ጌታችን ኢየሱስም ዳግመኛ እንዲህ አላቸው፥ “ሰላም ለእናንተ ይሁን፤ አብ እኔን እንደ ላከኝ እንዲሁ እኔ እናንተን እልካችኋለሁ።”'),
  ('f593deeb-29c5-5a31-a0c3-f3ba49b10544', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '34733372-7a0f-5608-a581-0e36aac0cb2a', 4, 22, 'ይህንም ብሎ እፍ አለባቸው፤ እንዲህም አላቸው፥ “መንፈስ ቅዱስን ተቀበሉ።'),
  ('fc210dfe-57b5-5586-ae48-784abb0e2cc5', '4e599f6a-7739-5e93-ac64-a8ad7024c165', '34733372-7a0f-5608-a581-0e36aac0cb2a', 5, 23, 'ኀጢኣታቸውን ይቅር ያላችሁላቸው ይሰረይላቸዋል፤ ይቅር ያላላችኋቸው ግን አይሰረይላቸውም።”'),
  ('4a7e82a6-7374-5566-a19e-80e7e87d7c48', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 1, 24, 'ጌታችን ኢየሱስ በመጣ ጊዜ ዲዲሞስ የሚሉት ከዐሥራ ሁለቱ ደቀ መዛሙርት አንዱ ቶማስ ከደቀ መዛሙርቱ ጋር አልነበረም።'),
  ('bb569f35-617a-5f1b-a1b3-043f73eb1385', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 2, 25, 'ሌሎች ደቀ መዛሙርትም፥ “ጌታችንን አየነው” አሉት፤ እርሱ ግን፥ “የችንካሩን ምልክት በእጁ ካላየሁ፥ ጣቴንም ወደ ተቸነከረበት ካልጨመርሁ፥ እጄንም ወደ ጎኑ ካላገባሁ አላምንም” አላቸው።'),
  ('cbf38c51-ec27-5ddc-a59c-ab77c7e24948', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 3, 26, 'ከስምንት ቀን በኋላም ዳግመኛ ደቀ መዛሙርቱ በውስጡ ሳሉ፥ ቶማስም አብሮአቸው ሳለ በሩ እንደ ተዘጋ ጌታችን ኢየሱስ መጣ፤ በመካከላቸውም ቆመና፥ “ሰላም ለእናንተ ይሁን” አላቸው።'),
  ('b7ec6413-d0db-5345-a985-3094318014fa', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 4, 27, 'ከዚህም በኋላ ቶማስን፥ “ጣትህን ወዲህ አምጣና እጆችን እይ፤ እጅህንም አምጣና ወደ ጎኔ አግባ፤ እመን እንጂ ተጠራጣሪ አትሁን” አለው።'),
  ('b69ebbec-6473-5538-a3b9-ae4086ae46a3', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 5, 28, 'ቶማስም፥ “ጌታዬ አምላኬም” ብሎ መለሰ።'),
  ('94f9b051-804d-59eb-afa6-e1ad5c36b018', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 6, 29, 'ጌታችን ኢየሱስም፥ “ስለ አየኸኝ አመንህን? ብፁዓንስ ሳያዩ የሚያምኑ ናቸው” አለው።'),
  ('dac35412-b679-5f67-ae6d-bea70e8ff769', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 7, 30, 'ጌታችን ኢየሱስም በዚህ መጽሐፍ ያልተጻፈ ብዙ ሌላ ተአምራት በደቀ መዛሙርቱ ፊት አደረገ።'),
  ('43f74d39-9ba8-59af-abb8-ff8105e9f57e', '4e599f6a-7739-5e93-ac64-a8ad7024c165', 'b8ea8d9f-84d6-58e3-ab67-f6437cd47b84', 8, 31, 'ነገር ግን ይህ የተጻፈ ኢየሱስ እርሱ ክርስቶስ የእግዚአብሔር ልጅ እንደ ሆነ እናንተ ታምኑ ዘንድ፥ አምናችሁም በስሙ የዘለዓለም ሕይወትን ታገኙ ዘንድ ነው።'),
  ('9d28118c-3358-51ed-a6fa-bd47dfe649d7', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 1, 1, 'ከዚህም በኋላ ጌታችን ኢየሱስ በጥብርያዶስ ባሕር አጠገብ ለደቀ መዛሙርቱ እንደገና ተገለጠላቸው፤ እንዲህም ተገለጠላቸው።'),
  ('db0b478c-af0d-5370-a676-3f6e89bd0238', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 2, 2, 'ስምዖን ጴጥሮስ፥ ዲዲሞስ የሚሉት ቶማስ፥ ከገሊላ ቃና የሆነው ናትናኤል፥ የዘብዴዎስ ልጆችና ሌሎችም ከደቀ መዛሙርቱ ሁለት አብረው ነበሩ።'),
  ('0241c8e0-d92a-577e-ad31-89b6fc710415', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 3, 3, 'ስምዖን ጴጥሮስ፥ “እኔ ዓሣ ላጠምድ እሄዳለሁ” አላቸው፤ እነርሱም፥ “እኛም አብረንህ እንመጣለን” አሉት፤ ሄደውም ወደ ታንኳ ገቡ፤ ግን በዚያች ሌሊት የያዙት ምንም የለም።'),
  ('548ded9a-b9bb-5da2-a6d1-0d73b28711fc', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 4, 4, 'በነጋ ጊዜም ጌታችን ኢየሱስ በባሕሩ ዳር ቆሞ ነበር፤ ደቀ መዛሙርቱም አዩት፤ ግን ጌታችን ኢየሱስ እንደ ሆነ አላወቁም።'),
  ('8c0abdd9-3a8a-5a4b-adbf-ac1a11013d1e', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 5, 5, 'ጌታችን ኢየሱስም፥ “ልጆች ሆይ አንዳች የሚበላ ነገር አላችሁን?” አላቸው፤ እነርሱም፥ “የለም” አሉት።'),
  ('7a6b3956-9e25-5006-a083-361b984333c8', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 6, 6, 'ጌታችን ኢየሱስም፥ “መረባችሁን በታንኳዪቱ በስተቀኝ በኩል ጣሉ፤ ታገኛላችሁም” አላቸው፤ መረባቸውንም በጣሉ ጊዜ ከተያዘው ዓሣ ብዛት የተነሣ ስቦ ማውጣት ተሳናቸው።'),
  ('31ca8332-ebb8-5c6d-a2a5-bd27b02b1626', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 7, 7, 'ጌታችን ኢየሱስ ይወደው የነበረ ያ ደቀ መዝሙርም ለጴጥሮስ፥ “ጌታችን ነው እኮ” አለው፤ ስምዖን ጴጥሮስም ጌታችን እንደ ሆነ በሰማ ጊዜ የሚለብሰውን ልብስ አንሥቶ በወገቡ ታጠቀ፤ ራቁቱን ነበርና ወደ ባሕር ተወረወረ።'),
  ('f3c990eb-a199-5158-add0-1beadf77b5bc', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 8, 8, 'ሌሎች ደቀ መዛሙርት ግን በታንኳ መጡ፤ ከሁለት መቶ ክንድ ያህል በቀር ከምድር አልራቁም ነበርና፤ ዓሣ የመላባቸውን መረቦቻቸውንም እየሳቡ ሄዱ።'),
  ('552c3474-59e5-5c38-ab42-cccbb4e0c521', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 9, 9, 'ወደ ምድርም በወረዱ ጊዜ ፍሙ መርቶ፥ ዓሣም በላዩ ሆኖ፥ እንጀራም ተሠርቶ አገኙ።'),
  ('4ae219b1-2128-5df3-ab7a-1b98690ef1cc', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 10, 10, 'ጌታችን ኢየሱስም፥ “አሁን ከያዛችኋቸው ዓሣዎች አምጡ” አላቸው።'),
  ('70f31fc8-c00a-53b1-a416-f4c28b837ebf', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 11, 11, 'ስምዖን ጴጥሮስም ወደ ታንኳ ገብቶ መቶ አምሳ ሦስት ታላላቅ ዓሣዎችን መልቶ የነበረውን መረብ ወደ ምድር ሳበ፤ ብዛቱም ይህን ያህል ሲሆን መረቡ አልተቀደደም።'),
  ('b72fd849-edce-55b2-acdf-fbbc4bc00f36', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 12, 12, 'ጌታችን ኢየሱስም፥ “ኑ፥ ምሳ ብሉ” አላቸው፤ ከደቀ መዛሙርቱም አንተ ማነህ? ብሎ ሊጠይቀው የደፈረ የለም፤ ጌታችን እንደ ሆነ ዐውቀዋልና።'),
  ('c992775d-d981-5439-a26c-0125c82c494e', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 13, 13, 'ጌታችን ኢየሱስም መጣና ኅብስቱን አንሥቶ ሰጣቸው፤ ከዓሣውም እንዲሁ።'),
  ('30aa416c-bdec-58ff-a036-261d667b5535', '1fae078d-294a-5810-a571-123f59ee9ba2', '2a353018-6671-5110-a0b6-8ad66f7c7dad', 14, 14, 'ጌታችን ኢየሱስም ከሙታን ተለይቶ ከተነሣ በኋላ ለደቀ መዛሙርቱ ሲገለጥላቸው ይህ ሦስተኛ ጊዜዉ ነበር።'),
  ('ea8280c0-4e2b-53f4-aefb-78ab311f8629', '1fae078d-294a-5810-a571-123f59ee9ba2', 'cdbea5c4-23af-534a-abde-b63762909e64', 1, 15, 'ምሳም ከበሉ በኋላ ጌታችን ኢየሱስ፦ ስምዖን ጴጥሮስን፥ “የዮና ልጅ ስምዖን ሆይ፥ ከእነዚህ ይልቅ ትወደኛለህን?” አለው፤ እርሱም፥ “አዎን፥ ጌታዬ ሆይ፥ እኔ እንደምወድህ አንተ ታውቃለህ” አለው፤ ጌታችን ኢየሱስም፥ “በጎችን ጠብቅ” አለው።'),
  ('24ae82bc-2b34-5c5b-ac3e-53a54f3d3ae8', '1fae078d-294a-5810-a571-123f59ee9ba2', 'cdbea5c4-23af-534a-abde-b63762909e64', 2, 16, 'ዳግመኛም፥ “የዮና ልጅ ስምዖን ሆይ፥ ትወደኛለህን?” አለው፤ እርሱም፥ “አዎን፥ ጌታዬ ሆይ፥ እኔ እንደምወድህ አንተ ታውቃለህ” አለው፤ “ጠቦቶችን አሰማራ” አለው።'),
  ('ec837d2f-ea67-56d5-ac60-a4beb44bae35', '1fae078d-294a-5810-a571-123f59ee9ba2', 'cdbea5c4-23af-534a-abde-b63762909e64', 3, 17, 'ሦስተኛ ጊዜም፥ “የዮና ልጅ ስምዖን ሆይ፥ ትወደኛለህን?” አለው፤ ጴጥሮስም ሦስት ጊዜ ትወደኛለህን? ስላለው ተከዘ፤ “ጌታዬ ሆይ፥ አንተ ሁሉን ታውቃለህ፤ እኔም እንደምወድህ አንተ ታውቃለህ” አለው፤ “እንኪያስ ግልገሎችን ጠብቅ” አለው።'),
  ('c8fb1329-7251-5c4a-a8a7-5c6a9c5acb2f', '1fae078d-294a-5810-a571-123f59ee9ba2', 'cdbea5c4-23af-534a-abde-b63762909e64', 4, 18, '“እውነት እውነት እልሃለሁ፤ አንተ ጐልማሳ ሳለህ በገዛ እጅህ ወገብህን ታጥቀህ ወደ ወደድኸው ትሄድ ነበር፤ በሸመገልህ ጊዜ ግን እጆችህን ትዘረጋለህ፤ ወገብህንም ሌላ ያስታጥቅሃል፤ ወደማትወደውም ይወስድሃል።”'),
  ('0d71bc83-7a9b-5759-afd9-0688919ed40c', '1fae078d-294a-5810-a571-123f59ee9ba2', 'cdbea5c4-23af-534a-abde-b63762909e64', 5, 19, 'በምን ሞት እግዚአብሔርን ያከብር ዘንድ እንዳለው ሲያመለክት ይህን ተናገረ፤ ይህንም ብሎ ተከተለኝ አለው።'),
  ('fef2391e-121d-55b7-aa1a-772ff9f87f4a', '1fae078d-294a-5810-a571-123f59ee9ba2', '49e9abd1-535a-54ad-ad59-88d781337037', 1, 20, 'ጴጥሮስም መለስ ብሎ ጌታችን ኢየሱስ ይወደው የነበረውን ያን ደቀ መዝሙር ሲከተለው አየ፤ እርሱም ራት ሲበሉ በጌታችን በኢየሱስ አጠገብ የነበረውና “ጌታ ሆይ፥ አሳልፎ የሚሰጥህ ማነው?” ያለው ነው።'),
  ('07fd7302-2ad4-5597-a2d3-c7ba4a452ccf', '1fae078d-294a-5810-a571-123f59ee9ba2', '49e9abd1-535a-54ad-ad59-88d781337037', 2, 21, 'ጴጥሮስም እርሱን አይቶ፥ “ጌታ ሆይ፥ ይህስ እንዴት ይሆናል?” አለው።'),
  ('9e16bf60-7f07-5c28-aa60-9cd844044209', '1fae078d-294a-5810-a571-123f59ee9ba2', '49e9abd1-535a-54ad-ad59-88d781337037', 3, 22, 'ጌታችን ኢየሱስም፥ “እስክመጣ ይኖር ዘንድ ብወድድስ አንተን ምን አግዶህ፤ አንተ ግን ተከተለኝ” አለው።'),
  ('edf00986-5789-5e3f-a836-068120f5273f', '1fae078d-294a-5810-a571-123f59ee9ba2', '49e9abd1-535a-54ad-ad59-88d781337037', 4, 23, 'ያም ደቀ መዝሙር እንደማይሞት ይህ ነገር በወንድሞች ዘንድ ተነገረ፤ ጌታችን ኢየሱስ ግን፥ “እስክመጣ ድረስ ይኖር ዘንድ ብወድድስ አንተን ምን አግዶህ” አለ እንጂ አይሞትም አላለውም።'),
  ('4dd49f02-9acf-5523-aef1-2667934ccb69', '1fae078d-294a-5810-a571-123f59ee9ba2', '49e9abd1-535a-54ad-ad59-88d781337037', 5, 24, 'ስለዚህ ነገር ምስክር የሆነ፥ ስለ እርሱም ይህን የጻፈ ይህ ደቀ መዝሙር ነው፤ ምስክርነቱም እውነት እንደ ሆነ እኛ እናውቃለን።'),
  ('b6597b9f-6952-5fa0-a0da-75be102fa91b', '1fae078d-294a-5810-a571-123f59ee9ba2', '49e9abd1-535a-54ad-ad59-88d781337037', 6, 25, 'ጌታችን ኢየሱስ የሠራቸው ሌሎች ብዙ ሥራዎች አሉ፤ ሁሉ እያንዳንዱ ቢጻፍ ግን የተጻፉትን መጻሕፍት ዓለም ስንኳን ባልቻላቸውም ነበር።'),
  ('a287a375-ab00-560a-a313-b83ee2492250', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '7bc83076-2afc-5526-aa4f-af013bd5f96d', 1, 1, 'ቴዎፍሎስ ሆይ፥ ጌታችን ኢየሱስ ክርስቶስ ሊያደርገውና ሊያስተምረው የጀመረውን ሥራ ሁሉ አስቀድሜ በመጽሐፍ ጽፌልሃለሁ።'),
  ('26c78cde-a546-5506-a84a-c4165631cdc2', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '7bc83076-2afc-5526-aa4f-af013bd5f96d', 2, 2, 'በመንፈስ ቅዱስ የመረጣቸው ሐዋርያትን አዝዞ እስከ ዐረገባት ቀን ድረስ ያለውን ጽፌልሃለሁ።'),
  ('2ed64069-588b-5208-a3d4-5ee5f41d3e41', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '7bc83076-2afc-5526-aa4f-af013bd5f96d', 3, 3, 'ሕማማትን ከተቀበለ በኋላ ብዙ ተአምራት በማሳየት አርባ ቀን ሙሉ እየተገለጠላቸው፥ ስለ እግዚአብሔር መንግሥትም እየነገራቸውና እያስተማራቸው ሕያው ሆኖ ራሱንገለጠላቸው።'),
  ('c7470a0e-febc-5c6c-a063-96bca7d4b104', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1d2f5c8b-b018-54a9-a033-ee779fa0c1cb', 1, 4, 'ከእነርሱም ጋር አብሮ ሳለ፥ “ከእኔ የሰማችሁትን የአብን ተስፋ ጠብቁ” ብሎ ከኢየሩሳሌም እንዳይወጡ አዘዛቸው።'),
  ('d4e4a646-77a2-551e-a9d6-0ab2abf5f601', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1d2f5c8b-b018-54a9-a033-ee779fa0c1cb', 2, 5, '“ዮሐንስ በውኃ አጠመቀ፤ እናንተ ግን እስከ ቅርብ ቀን ድረስ በመንፈስ ቅዱስ ትጠመቃላችሁ” አላቸው።'),
  ('ea06373a-9744-5dd1-a6b6-4f634692d575', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1d2f5c8b-b018-54a9-a033-ee779fa0c1cb', 3, 6, 'እነርሱም ተሰብስበው ሳሉ፥ “ጌታ ሆይ፥ በዚህ ወራት ለእስራኤል ልጆች መንግሥትን ትመልሳለህን?” ብለው ጠየቁት።'),
  ('0732fdec-9e24-520f-a14a-ba2a763d4e81', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1d2f5c8b-b018-54a9-a033-ee779fa0c1cb', 4, 7, 'እርሱም መልሶ እንዲህ አላቸው፥ “አብ በገዛ ሥልጣኑ የወሰነውን ቀኑንና ዘመኑን ልታውቁ አልተፈቀደላችሁም።'),
  ('d64f6b40-5dee-5aed-a4e0-3484d5bd41cf', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1d2f5c8b-b018-54a9-a033-ee779fa0c1cb', 5, 8, 'ነገር ግን መንፈስ ቅዱስ በእናንተ ላይ በወረደ ጊዜ ኀይልን ትቀበላላችሁ፤ በኢየሩሳሌምና በይሁዳ ሁሉ፥ በሰማርያና እስከ ምድር ዳርቻ ድረስም ምስክሮች ትሆኑኛላችሁ።”'),
  ('6ba379bd-ec4e-5813-a68b-355d357442bd', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '39aa413f-ceb8-563a-a1c2-efb72919fe3e', 1, 9, 'ይህንም እየነገራቸው ከፍ ከፍ አለ፤ ደመናም ተቀበለችው፤ እነርሱም ወደ እርሱ እያዩ ወደ ሰማይ ዐረገ፤ ከዐይናቸውም ተሰወረ።'),
  ('47cc0859-2c13-56e1-afb8-6d2f0466a7e5', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '39aa413f-ceb8-563a-a1c2-efb72919fe3e', 2, 10, 'እነርሱም ወደ ሰማይ አተኵረው ሲመለከቱ እነሆ፥ ሁለት ሰዎች ነጫጭ ልብስ ለብሰው በአጠገባቸው ቆመው ታዩአቸው።'),
  ('c537e0da-72e1-514c-a8ed-f4deacae2f6f', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '39aa413f-ceb8-563a-a1c2-efb72919fe3e', 3, 11, 'እነርሱም፥ “እናንተ የገሊላ ሰዎች ሆይ፥ ወደ ሰማይ እየአያችሁ ለምን ቆማችኋል? ይህ ከእናንተ ወደ ሰማይ ያረገው ኢየሱስ፥ ከእናንተ ወደ ሰማይ ሲያርግ እንዳያችሁት እንዲሁ ዳግመኛ ይመጣል” አሏቸው።'),
  ('6ba8a6ff-e404-512c-ad52-42d63d199ec2', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '39aa413f-ceb8-563a-a1c2-efb72919fe3e', 4, 12, 'ከዚህም በኋላ ደብረ ዘይት ከሚባለው ተራራ ወደ ኢየሩሳሌም ተመለሱ፤ እርሱም ለኢየሩሳሌም የሰንበት መንገድ ያህል የራቀ ነው።'),
  ('344de4ef-1eb7-54c3-ad8c-c8610fe3d26b', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '39aa413f-ceb8-563a-a1c2-efb72919fe3e', 5, 13, 'ወደ ማደሪያቸውም በደረሱ ጊዜ ጴጥሮስ፥ ዮሐንስ፥ ያዕቆብ፥ እንድርያስ፥ ፊልጶስ፥ ቶማስ፥ ማቴዎስ፥ በርተሎሜዎስ፥ የእልፍዮስ ልጅ ያዕቆብ፥ ቀናተኛው ስምዖን፥ የያዕቆብ ልጅ ይሁዳም ወደሚኖሩበት ሰገነት ወጡ።'),
  ('94145025-a159-5596-afb9-cd5ebe9e6771', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '39aa413f-ceb8-563a-a1c2-efb72919fe3e', 6, 14, 'እነዚህ ሁሉ ከሴቶችና ከጌታችን ከኢየሱስ እናት ከማርያም፥ ከወንድሞቹም ጋር በአንድነት ለጸሎት ይተጉ ነበር።'),
  ('18f53bf9-c50f-5702-a18c-e81d801fae50', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 1, 15, 'ያንጊዜም ጴጥሮስ ተነሣና በወንድሞቹ መካከል ቆመ፤ መቶ ሃያ ያህል ሰዎችም በዚያ ሳሉ እንዲህ አላቸው።'),
  ('8d6ed701-aa53-5568-a072-7c0d119029bd', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 2, 16, '“እናንተ ሰዎች ወንድሞቻችን ሆይ፥ ስሙ፤ ጌታችን ኢየሱስን ለያዙት መሪ ስለ ሆናቸው ስለ ይሁዳ መንፈስ ቅዱስ አስቀድሞ በዳዊት አፍ የተናገረው የመጽሐፍ ቃል ይፈጸም ዘንድ ይገባል።'),
  ('6eec13c8-b9c7-5553-a5cf-e52bea6b8003', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 3, 17, 'እርሱም ከእኛ ጋር ተቈጥሮ ነበር፤ ለዚህም አገልግሎት ታድሎ ነበር።'),
  ('fa786dce-a700-55a5-a270-7b24a1ebcf43', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 4, 18, 'ከዚህም በኋላ ይህ ሰው በዐመፅ ዋጋዉ መሬት ገዛ፤ በምድር ላይም በግንባሩ ወደቀና ከመካከሉ ተሰነጠቀ፤ አንጀቱም ሁሉ ተዘረገፈ።'),
  ('780992b1-9974-5d7f-a855-38a94780b82e', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 5, 19, 'በኢየሩሳሌምም በሚኖሩት ሁሉ ዜናዉ ተሰማ፤ ያም መሬት በቋንቋቸው አኬልዳማ ተብሎ ተጠራ፤ ይኸውም የደም መሬት ማለት ነው።'),
  ('87ff8309-e5f5-5ac6-aa28-329e03f99a21', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 6, 20, 'በመዝሙር መጽሐፍ ‘መኖሪያዉ ምድረ በዳ ትሁን፤ በውስጧም የሚኖር አይኑር፤ ሹመቱንም ሌላ ይውሰድ’ ተብሎ ተጽፎአልና።'),
  ('864fbcb6-0cc5-56e3-ae17-6cfc656fcc51', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 7, 21, 'እንግዲህ ከዮሐንስ ጥምቀት ጀምሮ ከእኛ ዘንድ እስካረገበት ቀን ድረስ፥'),
  ('00d0521f-ed59-5d75-a7d4-c89542051bfc', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 8, 22, 'ጌታችን ኢየሱስ ክርስቶስ በእኛ መካከል በገባበትና በወጣበት ዘመን ሁሉ ከእኛ ጋር አብረው ከነበሩት ከእነዚህ ሰዎች አንዱ ከእኛ ጋር የትንሣኤዉ ምስክር ይሆን ዘንድ ይገባል።”'),
  ('a9b792c9-b7c5-5fe9-a54f-66ac2e3f8b2b', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 9, 23, 'ኢዮስጦስ የሚሉትን በርናባስ የተባለውን ዮሴፍንና ማትያስን ሁለቱን ሰዎች አቆሙ።'),
  ('72473321-c06e-56f2-ad72-e0ef0b226e40', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 10, 24, 'እንዲህም ብለው ጸለዩ፥ “አቤቱ፥ ልብን ሁሉ የምታውቅ አንተ፥ ከእነዚህ ከሁለቱ የመረጥኸውን አንዱን ግለጥ።'),
  ('64e5886a-1c18-5c3a-a90f-b8bd75549b5a', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 11, 25, 'ይሁዳ ወደ ሀገሩ ይሄድ ዘንድ የተዋትን ይህቺን የአገልግሎትና የሐዋርያነትን ቦታ የሚቀበላትን ግለጥ።”'),
  ('0c000541-a5b5-5c32-ae48-f36e1d01ee96', '4b6b64e6-d5ab-5bf7-a79b-3f68583d63ea', '1ffdc8c3-034c-57ef-ae5c-e2901197fc58', 12, 26, 'ዕጣም አጣጣሏቸው፤ ዕጣዉም በማትያስ ላይ ወጣ፤ ከዐሥራ አንዱ ሐዋርያት ጋራም ተቈጠረ።'),
  ('e7ca72b6-2df7-527b-aa48-cc8e8b4b2a41', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 1, 1, 'ኀምሳው ቀንም በተፈጸመ ጊዜ፥ ሁሉም በአንድነት በአንድ ቦታ ተሰብስበው ነበር።'),
  ('4e69ea7d-d176-575f-a212-ea700da095fd', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 2, 2, 'ድንገትም እንደ ዐውሎ ነፋስ ድምፅ ያለ ከሰማይ ድምፅ መጣ፤ የነበሩበትንም ቤት ሞላው።'),
  ('a1a4d6ea-9b11-50f5-adca-9fc4480df2b2', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 3, 3, 'እንደ እሳት የተከፋፈሉ የእሳት ላንቃዎችም ታዩአቸው፤ በሁሉም ላይ ተቀመጡባቸው።'),
  ('ad0a835c-641d-5bfb-a222-d29ac5a0a9fd', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 4, 4, 'ሁሉም መንፈስ ቅዱስን ተሞሉ፤ ይናገሩ ዘንድ መንፈስ ቅዱስ እንደ አደላቸው መጠንም እየራሳቸው በሀገሩ ሁሉ ቋንቋ ይናገሩ ጀመሩ።'),
  ('ef7ecc72-559b-5cc2-a24d-db6761691692', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 5, 5, 'ከሰማይ በታች ካሉ አሕዛብ ሁሉ በኢየሩሳሌም የሚኖሩ ደጋግ የአይሁድ ሰዎች ነበሩ።'),
  ('ce2fec68-ec52-5fae-a3f4-6df7ed636ba7', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 6, 6, 'ይህንም ቃል ሲናገሩ ሰምተው ሁሉም ደንግጠው ተሰበሰቡ፤ ሁሉም በየሀገራቸው ቋንቋ ሲናገሩ ሰምተዋቸዋልና የሚሉትን አጡ።'),
  ('362df6f2-7fb4-5b22-a7f5-afefe73b08d1', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 7, 7, 'ተገረሙ፤ አደነቁም፥ እንዲህም አሉ፥ “እነዚህ የሚናገሩት ሁሉ የገሊላ ሰዎች አይደሉምን?'),
  ('3886aed0-db7a-5e18-a8e0-2496eaf45f94', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 8, 8, 'እንግዲህ በየሀገራችን ቋንቋ ሲናገሩ እንዴት እንሰማቸዋለን?'),
  ('58928949-b64e-50da-aa3e-fe06e32822ea', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 9, 9, 'እኛ በተወለድንበት በጳርቴ፥ በሜድ፥ በኢላሜጤ፥ በሁለቱ ወንዞች መካከል፥ በይሁዳ፥ በቀጰዶቅያ፥ በጳንጦስና በእስያ፥'),
  ('c2fc8c17-ac87-54f1-a4f4-0916e4210697', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 10, 10, 'በፍርግያ፥ በጵንፍልያ፥ በግብፅ፥ በሊብያ አውራጃ፥ በቀርኔን የምንኖር፥ ከሮሜም የመጣን አይሁድ፥ መጻተኞችም፥'),
  ('1ab60121-70a5-54c6-aba8-21f50cebc76a', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 11, 11, 'ከቀርጤስና ከዐረብም የመጣን፥ እነሆ፥ የእግዚአብሔርን ጌትነት በየሀገራችን ቋንቋ ሲናገሩ እንሰማቸዋለን።”'),
  ('da698735-6650-519f-ad97-93ef1f15ad91', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 12, 12, 'ሁሉም ተገረሙ፤ የሚሉትንም አጡ፥ እርስ በርሳቸውም፥ “እንጃ! ይህ ነገር ምን ይሆን?” ተባባሉ።'),
  ('d6b4db45-b29f-58de-a7c5-3d64002f850b', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'a0f296c8-7146-510e-a99c-42ff168c02ed', 13, 13, 'እኩሌቶቹ ግን “እነዚህስ ጉሽ ጠጅ ጠግበው ሰክረዋል” ብለው ሳቁባቸው።'),
  ('91732e53-d9df-5c5d-aa54-5b0feadc5cb2', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 1, 14, 'ጴጥሮስም ከዐሥራ አንዱ ጋር ቆሞ ድምፁን ከፍ አድርጎ እንዲህ አለ፥ “እናንተ የአይሁድ ሰዎች፥ በኢየሩሳሌምም የምትኖሩ ሁሉ፥ ይህን ዕወቁ፤ ቃሌንም ስሙ።'),
  ('916ce3b8-1273-5ba7-a1bd-9de10e7c31ac', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 2, 15, 'ለእናንተ እንደ መሰላችሁ እነዚህ የሰከሩ አይደሉም፤ ከቀኑ ገና ሦስተኛ ሰዓት ነውና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9f3ed9f8-23f6-515a-ac73-bfaaba78c525', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 3, 16, 'ነገር ግን ይህ በነቢዩ በኢዩኤል የተባለው ነው።'),
  ('bf570b3b-31bb-5837-a9af-80678f088712', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 4, 17, 'በኋለኛዪቱ ቀን እንዲህ ይሆናል ይላል እግዚአብሔር፦ ሥጋን በለበሰ ሁሉ ላይ ከመንፈሴ አፈስሳለሁ፤ ወንዶች ልጆቻችሁና ሴቶች ልጆቻችሁ ትንቢት ይናገራሉ፤ ጐልማሶቻችሁ ራእይን ያያሉ፤ ሽማግሌዎቻችሁም ሕልምን ያልማሉ።'),
  ('39abf83c-26c1-5cc1-adb7-cba32f53a746', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 5, 18, 'በወንዶችና በሴቶች ባሮች ላይም ያንጊዜ መንፈሴን አፈስሳለሁ፤ ትንቢትም ይናገራሉ።'),
  ('e338ae39-0a1b-5ac1-ac87-766d022bf66e', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 6, 19, 'በላይ በሰማይ ተአምራትን፥ በታች በምድርም ምልክቶችን፥ ደምን እሳትንና ጢስንም እሰጣለሁ።'),
  ('021fcc11-2251-570e-a7f4-653586d7314e', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 7, 20, 'የምትገለጠው ታላቅዋ የእግዚአብሔር ቀን ሳትመጣ ፀሐይ ወደ ጨለማ፥ ጨረቃም ወደ ደም ይለወጣል።'),
  ('90520449-a410-508b-a811-e14fed4fa034', '45d61b37-a607-5cb0-af7f-de6486f92eb0', 'bf308927-9322-5430-a1c5-108b198af623', 8, 21, 'የእግዚአብሔርንም ስም የሚጠራ ሁሉ ይድናል።'),
  ('7e9c6ab4-92a2-55aa-ad07-6c25eec05ea9', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 1, 22, '“እናንተ የእስራኤል ሰዎች ሆይ፥ ይህን ነገር ስሙ፤ እንደምታውቁት በመካከላችሁ እግዚአብሔር በእጁ ባደረገው በከሃሊነቱ በተአምራቱና በድንቅ ሥራዎቹ እግዚአብሔር የገለጠላችሁን ሰው የናዝሬቱን ኢየሱስን ስሙ።'),
  ('1a3003d7-d433-5fe2-a149-7a296e7dd97c', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 2, 23, 'እርሱንም በተወሰነው በእግዚአብሔር ምክርና በቀደመው ዕውቀቱ እናንተ አሳልፋችሁ በኃጥኣን እጅ ሰጣችሁት፤ ሰቅላችሁም ገደላችሁት።'),
  ('2ac070c1-ac86-58ea-a146-6c6e7798bef9', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 3, 24, 'እግዚአብሔር ግን የሞትን ማሰሪያ ፈቶ ከሙታን ለይቶ አስነሣው፤ ሞት እርሱን ሊይዘው አይችልምና።'),
  ('da0c308c-c8f3-5492-aeba-696817aa7917', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 4, 25, 'ዳዊትም ስለ እርሱ እንዲህ አለ፦ እግዚአብሔርን ሁልጊዜ በፊቴ አየዋለሁ፤ እንዳልታወክ በቀኜ ነውና።'),
  ('79bfcac3-8602-5995-ac17-bc5235a2fca8', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 5, 26, 'ስለዚህ ልቤን ደስ አለው፤ አንደበቴም ሐሤት አደረገ፤ ሥጋዬም ደግሞ በተስፋው አደረ።'),
  ('c02f0d49-d44c-5a56-a7f2-c78fdf900629', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 6, 27, 'ነፍሴን በሲኦል አትተዋትምና፥ ጻድቅህንም ጥፋትን ያይ ዘንድ አትሰጠውምና።'),
  ('1b1a2197-c152-569f-a0ea-34576a97ee28', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 7, 28, 'የሕይወትን መንገድ አሳየኸኝ፤ ከፊትህ ጋራ ደስታን አጠገብኸኝ።'),
  ('3feb6442-4954-5951-a44e-bdf3342e5b04', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 8, 29, '“እናንተ ወንድሞች ሆይ፥ ስለ አባቶች አለቃ ስለ ዳዊት ነገር እንደ ሞተ እንደ ተቀበረም፥ መቃብሩም እስከ ዛሬ ድረስ በእኛ ዘንድ እንደ አለ ገልጬ እንድነግራችሁ ትፈቅዱልኛላችሁን?'),
  ('d8b7f491-5cde-5a13-a659-8bc96b084bcc', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 9, 30, 'ነቢይ ስለ ነበረ፥ ከአብራኩም የተገኘውን በዙፋኑ እንዲያነግሥለት እግዚአብሔር መሐላን እንደ ማለለት ስለ ዐወቀ፥'),
  ('26efa1e5-f973-5e91-a89b-9502f2a6db59', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 10, 31, 'ክርስቶስ ከሙታን ተለይቶ እንደሚነሣ፥ ሥጋዉም በመቃብር እንደማይቀር፥ ጥፋትንም እንደማያይ አስቀድሞ ዐውቆ ተናገረ።'),
  ('d8d4ec02-93ff-5e25-af17-c49715569d51', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 11, 32, 'እርሱን ኢየሱስን እግዚአብሔር አስነሣው፤ ለዚህም እኛ ሁላችን ምስክሮቹ ነን።'),
  ('828496f8-e0d2-5342-ac7c-d3e788612a11', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 12, 33, 'አሁን ግን በእግዚአብሔር ቀኝ ከፍ ከፍ ብሎና የመንፈስ ቅዱስን ተስፋ ከአብ ገንዘብ አድርጎ ይህን ዛሬ የምታዩትንና የምትሰሙትን አፈሰሰው።'),
  ('fe062776-9b36-56a1-a045-9bf9b1930b02', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 13, 34, 'ዳዊት ወደ ሰማይ አልወጣም፥ ነገር ግን እርሱ አለ፦ ጌታ ጌታዬን አለው፦ በቀኜ ተቀመጥ።'),
  ('9ae6c47c-2a25-563f-a01f-e2b71beed325', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 14, 35, 'ጠላቶችህን ከእግርህ ጫማ በታች እስክጥላቸው ድረስ።'),
  ('e5658195-3632-5248-a1bd-aaa0a8ae4907', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 15, 36, 'እንግዲህ የእስራኤል ወገኖች ሁሉ እናንተ የሰቀላችሁትን ኢየሱስን እግዚአብሔር ጌታም መሢሕም እንዳደረገው በርግጥ ይወቁ።”'),
  ('2e946a0d-f4f6-5582-a3db-ebc2ad11676f', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 16, 37, 'ይህንም በሰሙ ጊዜ ልባቸው ተከፈተ፤ ጴጥሮስንና ወንድሞቹ ሐዋርያትንም፥ “ወንድሞቻችን ሆይ፥ ምን እናድርግ?” አሏቸው።'),
  ('1df337b8-c37c-5a25-a8b1-7768aab24730', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 17, 38, 'ጴጥሮስም እንዲህ አላቸው፥ “ንስሓ ግቡ፤ ሁላችሁም በኢየሱስ ክርስቶስ ስም ተጠመቁ፤ ኀጢአታችሁም ይሰረይላችኋል፤ የመንፈስ ቅዱስንም ጸጋ ትቀበላላችሁ።'),
  ('1c234e6d-9ea7-54e2-ac86-4d00e888f5c8', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 18, 39, 'ተስፋዉ ለእናንተና ለልጆቻችሁ፥ እግዚአብሔር አምላካችንም ለሚጠራቸው ርቀው ለነበሩ ሁሉ ነውና።”'),
  ('4a52d4d4-142e-5a7e-ae9c-6a442c6d79a4', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '928d7f33-1c07-5c35-a877-157ced3b5464', 19, 40, 'ሌላም ብዙ ነገር ነገራቸው፤ “ከዚህ ከክፉ ዓለምም ነፍሳችሁን አድኑ” ብሎ መከራቸው።'),
  ('f1c308a2-313d-5102-abca-1140f25b27f4', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 1, 41, 'ቃሉንም ተቀብለው ተጠመቁ፤ በዚችም ዕለት ሦስት ሺህ ያህል ሰዎች ተጨመሩ።'),
  ('05e986d8-e9e1-5d8c-ad33-5685fc866239', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 2, 42, 'በሐዋርያት ትምህርትና በአንድነት ማዕድን በመባረክ፥ በጸሎትም ጸንተው ይኖሩ ነበር።'),
  ('e1359837-73b9-5d98-ac4f-28c39f7423ab', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 3, 43, 'ሰው ሁሉ ፈራቸው፤ በሐዋርያትም እጅ ብዙ ተአምራትና ድንቅ ሥራ ይደረግ ነበር።'),
  ('4e4b461b-2d3a-5e77-aea7-553c5d866ee7', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 4, 44, 'ያመኑትም ሁሉ በአንድነት ይኖሩ ነበር፤ ገንዘባቸውም ሁሉ በአንድነት ነበር።'),
  ('ad80d019-d3af-5e71-abc2-03f4f8addb30', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 5, 45, 'መሬታቸውንና ጥሪታቸውንም እየሸጡ ለእያንዳንዱ እንደሚያሻው ይሰጡ ነበር።'),
  ('441cf9be-4be4-5e4c-ac89-007c15a8639d', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 6, 46, 'ሁልጊዜም አንድ ልብ ሆነው በቤተ መቅደስ ያገለግሉ ነበር፤ በቤትም ኅብስትን ይቈርሱ ነበር፤ በደስታና በልብ ቅንንነትም ምግባቸውን ይመገቡ ነበር።'),
  ('d8a1c0bf-e84d-54cc-a9e1-b78bd0e9509a', '45d61b37-a607-5cb0-af7f-de6486f92eb0', '52d86b44-f4ca-59e3-a549-dceb363f28ff', 7, 47, 'እግዚአብሔርንም ያመሰግኑ ነበር፤ በሕዝቡም ሁሉ ዘንድ መወደድ ነበራቸው፤ እግዚአብሔርም የሚድኑትን ዕለት ዕለት በእነርሱ ላይ ይጨምር ነበር።'),
  ('53ede3c1-c165-53cc-a540-5cd8d66a75f6', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 1, 1, 'ጴጥሮስና ዮሐንስም በዘጠኝ ሰዓት ለጸሎት በአንድነት ወደ ቤተ መቅደስ ወጡ።'),
  ('0c1b5c10-9eb1-58b9-aa69-3aa6c314e5e7', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 2, 2, 'ከእናቱ ማኅፀንም ጀምሮ እግሩ ሽባ ሆኖ የተወለደ አንድ ሰው ነበር፤ ወደ መቅደስም ከሚገቡት ምጽዋት ይለምን ዘንድ ሁልጊዜ እየተሸከሙ መልካም በሚልዋት በመቅደስ ደጃፍ ያስቀምጡት ነበር።'),
  ('c3be4ee3-2746-5520-a48f-079cdaed6692', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 3, 3, 'ጴጥሮስንና ዮሐንስንም ወደ መቅደስ ሲገቡ አይቶ ምጽዋት ይሰጡት ዘንድ ለመናቸው።'),
  ('646da0df-b2c4-5f3e-aa76-d2c54571fe68', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 4, 4, 'ጴጥሮስም ከዮሐንስ ጋር ትኩር ብሎ ተመለከተው፥ “ወደ እኛ ተመልከት” አለው፤'),
  ('0e123ec9-095d-53e9-a228-e1838db09f17', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 5, 5, 'ወደ እነርሱም ተመለከተ፤ ምጽዋት እንደሚሰጡትም ተስፋ አድርጎ ነበር።'),
  ('753aebc1-5070-5382-af56-c251afbb46ec', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 6, 6, 'ጴጥሮስም፥ “ወርቅና ብር የለኝም፤ ያለኝን ግን እሰጥሃለሁ፤ እነሆ፥ በናዝሬቱ በኢየሱስ ክርስቶስ ስም ተነሥተህ ሂድ” አለው።'),
  ('4c2e6d25-db08-571f-af42-7d0e6d1f0690', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 7, 7, 'በቀኝ እጁም ይዞ አስነሣው፤ ያንጊዜም እግሩና ቍርጭምጭምቱ ጸና።'),
  ('6772c64f-ff3d-59ca-a69d-764dfed72d04', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 8, 8, 'ዘሎም ቆመ፤ እየሮጠና እየተራመደም ሄደ፤ እግዚአብሔርንም እያመሰገነ ከእነርሱ ጋር ወደ ቤተ መቅደስ ገባ።'),
  ('08fd0306-9b0b-5d1e-a7c6-1a42673e91e3', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 9, 9, 'ሕዝቡም ሁሉ እግዚአብሔርን እያመሰገነ ሲመላለስ አዩት።'),
  ('b583e163-1433-53ee-a6b7-00e9fab01e95', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 10, 10, 'እርሱም መልካም በምትባለው በመቅደስ ደጃፍ ተቀምጦ ምጽዋት ይለምን የነበረው እንደ ሆነ ዐወቁት፤ በእርሱም ከሆነው የተነሣ መገረምና መደነቅ ሞላባቸው።'),
  ('da2bbbca-3b5a-55dd-abc5-d5bf8589d84e', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', '98865934-a42f-556c-abb4-ce676c7589e2', 11, 11, 'ጴጥሮስና ዮሐንስም ይዘውት ወደ መቅደስ ሲገቡ ሕዝቡ ሁሉ ደንግጠው ወደ ሰሎሞን መመላለሻ ወደ እነርሱ ሮጡ።'),
  ('376cb049-b629-591b-a8c8-05a3084238c8', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 1, 12, 'ጴጥሮስም ሕዝቡን ባያቸው ጊዜ እንዲህ አላቸው፥ “እናንት የእስራኤል ሰዎች ሆይ፥ ይህን ለምን ታደንቃላችሁ? እኛንስ በኀይላችንና በጽድቃችን ይህን ሰው በእግሩ እንዲሄድ እንዳደረግነው አስመስላችሁ ለምን ታዩናላችሁ?'),
  ('78f12aeb-483f-5a1c-ace2-8f0cbee0879f', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 2, 13, 'የአብርሃም አምላክ የይስሐቅ አምላክ፥ የያዕቆብ አምላክ፥ የአባቶቻችንም አምላክ፥ እናንተ አሳልፋችሁ የሰጣችሁትን፥ እርሱም ሊተወው ወዶ ሳለ በጲላጦስ ፊት የካዳችሁትን ልጁን ኢየሱስን ገለጠው።'),
  ('172e2c5a-2f61-53d8-acf6-34aae512edf6', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 3, 14, 'እናንተ ግን ቅዱሱንና ጻድቁን ካዳችሁት፤ ነፍሰ ገዳዩን ሰውም እንዲያድንላችሁ ለመናችሁ።'),
  ('54ce001f-efc8-574c-a760-e2620575e643', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 4, 15, 'የሕይወትን ባለቤት ግን ገደላችሁት፤ እግዚአብሔርም ከሙታን ለይቶ አስነሣው፤ ለዚህም እኛ ምስክሮቹ ነን።'),
  ('4ce1e989-6dbc-50d0-a998-d04245e356af', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 5, 16, 'ስሙን በማመን ይህን የምታዩትንና የምታውቁትን የእርሱ ስም አጸናው፤ እርሱንም በማመን በፊታችሁ ይህን ሕይወት ሰጠው።'),
  ('4542be96-92e8-5078-a7a8-da82dde7ddd8', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 6, 17, '“አሁንም ወንድሞች ሆይ፥ አለቆቻችሁ እንዳደረጉ ይህን ባለማወቅ እንዳደረጋችሁት አውቃለሁ።'),
  ('79f90f4b-b87c-50b2-a441-4aa5661766a4', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 7, 18, 'እግዚአብሔር ግን ክርስቶስ መከራን እንዲቀበል በነቢያት ሁሉ አፍ አስቀድሞ እንደ ተናገረ እንዲሁ ፈጸመ።'),
  ('8647aca6-cb3f-524a-a195-53e018f69fdd', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 8, 19, 'እንግዲህ ኀጢአታችሁ ይሰረይላችሁ ዘንድ ንስሓ ግቡ፥ ተመለሱም።'),
  ('b7010c5e-003d-5bc0-a8b3-5f554ecf92b5', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 9, 20, 'ከእግዚአብሔር ዘንድም የይቅርታ ዘመን ይመጣል። አስቀድሞ የመረጠውንም ኢየሱስ ክርስቶስን ይልክላችኋል።'),
  ('e6c64156-c5cc-5b2a-a33d-746469cd0772', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 10, 21, 'እግዚአብሔርም ከጥንት ጀምሮ በቅዱሳን ነቢያቱ አፍ እስከ ተናገረው የመደራጀት ዘመን ድረስ ሰማይ ይቀበለው ዘንድ ይገባል።'),
  ('c7a656a3-fbbb-5836-a40d-bae677705c77', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 11, 22, 'ሙሴም አባቶቻችንን እንዲህ ብሎአቸዋል፦ እግዚአብሔር አምላካችን ከወንድሞቻችሁ እንደ እኔ ያለ ነቢይ ያስነሣላችኋል፤ የሚነግራችሁን ሁሉ ስሙት።'),
  ('3f4255d4-525a-577d-a764-72deae9442f3', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 12, 23, 'ያን ነቢይ የማትሰማው ነፍስም ሁሉ ከወገኖችዋ ተለይታ ትጥፋ።'),
  ('e237ac44-649f-55ae-a96d-0da476301274', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 13, 24, 'ከሳሙኤል ጀምሮ ከእርሱም በኋላ የተነሡ ነቢያት ሁሉ ስለ እነዚህ ቀኖች ተናግረዋል፤ አስተምረዋልም።'),
  ('076702c3-588b-53c3-a5bd-65fba65b7848', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 14, 25, 'እናንተም የነቢያት ልጆች ናችሁ፤ እግዚአብሔር ለአባቶቻችን በሠራው ሥርዐትም የተወለዳችሁ ናችሁ፤ ለአብርሃም፦ ‘በዘርህ የምድር አሕዛብ ሁሉ ይባረካሉ’ ብሎታልና።'),
  ('4a48b64c-b52e-515e-a4e9-6c1c3e818efc', 'c693bf02-0ea5-5c63-a835-c96264e50e9f', 'ca041827-aafd-5f58-ada2-9128c521263f', 15, 26, 'እግዚአብሔርም አስቀድሞ ልጁን አስነሣላችሁ፤ ሁላችሁም ከክፋታችሁ እንድትመለሱ ይባርካችሁ ዘንድ ላከው።”'),
  ('4823eb19-af22-5207-ad86-99cb4e217b25', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 1, 1, 'ሕዝቡንም ሲያስተምሩ ሊቃነ ካህናትና የቤተ መቅደስ ሹም፥ ሰዱቃውያንም መጡ።'),
  ('a70c932a-7cf5-525d-a9ee-29f8712b5dab', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 2, 2, 'ሕዝቡን ስለ አስተማሩና በኢየሱስም የሙታንን ትንሣኤ ስለ ሰበኩ በእነርሱ ተናደዱ።'),
  ('1c99c159-3ed8-5f6b-aa38-93ec7183427c', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 3, 3, 'እጃቸውንም ዘርግተው ያዙአቸው፤ ጊዜዉም ፈጽሞ መሽቶ ነበርና እስከ ማግሥቱ ድረስ በወኅኒ ቤት አገቡአቸው።'),
  ('5a2acd5e-8f25-586b-ae72-fa7d1323626f', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 4, 4, 'ቃሉንም ሰምተው ያመኑ ብዙ ሰዎች ናቸው፤ ያመኑት ወንዶች ቍጥርም አምስት ሺህ ያህል ሆነ።'),
  ('0ebc8b35-5971-5a75-a587-0b78a1b07feb', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 5, 5, 'በማግሥቱም አለቆቻቸውና ሽማግሎች፥ ጻፎችም በኢየሩሳሌም ተሰበሰቡ።'),
  ('b373b4ee-65ae-5e7f-a52f-fb89ac35943d', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 6, 6, 'ሊቀ ካህናቱ ሐና፥ ቀያፋም፥ ዮሐንስና እለእስክንድሮስም፥ የሊቀ ካህናቱም ወገን ሁሉ ከእነርሱ ጋር ነበሩ።'),
  ('d05b39df-c855-5509-ace5-79b4e43e4847', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 7, 7, 'በአደባባይም አቆሙና፥ “እናንተ ይህን በማን ስምና በማን ኀይል አደረጋችሁት?” ብለው መረመሩአቸው።'),
  ('5fa45ca6-9ff4-56fa-a68f-bab755a3863e', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 8, 8, 'ያንጊዜም በጴጥሮስ መንፈስ ቅዱስ ሞላበትና እንዲህ አላቸው፥ “እናንተ የሕዝብ አለቆችና ሽማግሌዎች ሆይ፥ ስሙ፤'),
  ('8aa350d9-dfb8-5630-ad71-bb75bf43c73b', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 9, 9, 'ዛሬ ለበሽተኛው በተደረገው ረድኤት ምክንያት በእናንተ ዘንድ እኛ የሚፈረድብን ከሆነ እንግዲያ ይህ ሰው በምን ዳነ?'),
  ('99c2269b-276f-5068-a625-528ea819d94d', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 10, 10, 'እንግዲህ እናንተ ሁላችሁ፥ የእስራኤልም ወገን ሁሉ፥ እናንተ በሰቀላችሁት፥ እግዚአብሔርም ከሙታን ለይቶ በአስነሣው በናዝሬቱ በኢየሱስ ክርስቶስ ስም ይህ ሰው እንደ ዳነና በፊታችሁም እንደ ቆመ በርግጥ ዕወቁ።'),
  ('b4088761-e85a-51d5-a0ea-1df8dcc59a26', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 11, 11, 'ይህ እናንተ ግንበኞች የናቃችሁት ድንጋይ ነውና፤ እርሱም የማዕዘን ራስ ሆነ።'),
  ('f5dccc36-e3ee-51fa-ae79-c9cdfae60813', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 12, 12, 'መዳንም በሌላ በማንም የለም፤ ከሰማይ በታች እንድንበት ዘንድ የሚገባን ለሰው የተሰጠ ሌላ ስም ከቶ የለምና።”'),
  ('56816ac6-933b-567f-a047-c40c0b877767', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 13, 13, 'ጴጥሮስና ዮሐንስም ግልጥ አድርገው ሲናገሩ ባዩአቸው ጊዜ፥ ያልተማሩና መጽሐፍን የማያውቁ ሰዎች እንደ ሆኑ ዐውቀው አደነቁ፤ ሁልጊዜም ከኢየሱስ ጋር እንደ ነበሩ ዐወቁ።'),
  ('e4216972-db58-59cf-a44a-ef80fc5c664c', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 14, 14, 'ያን የዳነውን ሰውም ከእነርሱ ጋር ቆሞ በአዩት ጊዜ የሚሉትን አጡ።'),
  ('aaf019ed-6412-57d5-aa29-ccd048dee272', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 15, 15, 'ከሸንጎውም ጥቂት ፈቀቅ አደረጉአቸውና እርስ በርሳቸው ተነጋገሩ።'),
  ('b7fb8d9b-2a41-510b-a282-b194da482f38', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 16, 16, 'እንዲህም አሉ፥ “እነዚህን ሰዎች ምን እናድርጋቸው? እነሆ፥ በእነርሱ የሚደረገው ተአምር በኢየሩሳሌም በሚኖሩት ሁሉ ዘንድ ታወቀ፤ ግልጥም ሆነ፤ ልንሰውረውም አንችልም።'),
  ('59866155-c519-5df8-a082-b1ff4a78c767', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 17, 17, 'ነገር ግን በሕዝቡ ዘንድ እጅግ እንዳይስፋፋ ዳግመኛ በኢየሱስ ስም ሰውን እንዳያስተምሩ አጠንክረን እንገሥጻቸው።”'),
  ('e070b151-b44c-590a-a516-c86df5fd9176', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 18, 18, 'ጠርተውም፦“ በኢየሱስ ስም ፈጽሞ አትናገሩ አታስተምሩም” ብለው አዘዙአቸው።'),
  ('23ffecb7-6892-52c5-af3f-0214287a183b', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 19, 19, 'ጴጥሮስና ዮሐንስም እንዲህ ብለው መለሱላቸው፥ “እግዚአብሔርን ያይደለ እናንተን ልንሰማ በእግዚአብሔር ፊት ይገባልን? እስኪ እናንተ ራሳችሁ ፍረዱ።'),
  ('043fa7e4-9e14-507a-aef5-35342a48f2aa', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 20, 20, 'እኛስ ያየነውንና የሰማነውን ከመናገር ዝም እንል ዘንድ አንችልም።”'),
  ('6a57e661-8437-5f41-a958-7f3c18d57406', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 21, 21, 'እነርሱንም የሚቀጡበት ምክንያት ስለ አጡባቸው ገሥጸው ለቀቁአቸው፤ ስለ ተደረገው ተአምር ሕዝቡ ሁሉ እግዚአብሔርን ያመሰግኑ ነበርና።'),
  ('0a24d1cc-3817-5f99-aa55-9559e25ddfd9', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 22, 22, 'ይህ የድኅነት ምልክት ለተደረገለት ለዚያ ሰው ከአርባ ዓመት ይበልጠው ነበረና።'),
  ('3e3e219d-677b-5ce7-a644-7fcf0e99c9cd', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 23, 23, 'ተፈትተውም ወደ ሰዎቻቸው ሄዱ፤ ሊቃነ ካህናትና ሽማግሌዎችም ያሉአቸውን ሁሉ ነገሩአቸው።'),
  ('396c1109-17c1-5eb9-abb9-e42417016ac5', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 24, 24, 'ይህንም በሰሙ ጊዜ በአንድነት ቃላቸውን ወደ እግዚአብሔር ከፍ አድርገው እንዲህ አሉ፥ “ሰማይንና ምድርን፥ ባሕርንም፥ በውስጣቸው ያለውንም ሁሉ የፈጠርህ አንተ እግዚአብሔር ሆይ፥'),
  ('6592890d-dce2-5082-a701-03decb5734f4', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 25, 25, 'አንተ ራስህ በአባታችን በባሪያህ በዳዊት አፍ በመንፈስ ቅዱስ እንዲህ ብለህ የተናገርህ፦ አሕዛብ ለምን ተሰበሰቡ? ሕዝቡስ ለምን ከንቱ ነገርን ተናገሩ?'),
  ('52f53e20-a13e-5f16-ab2b-0ed4778eec1a', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 26, 26, 'የምድር ነገሥታት ለምን ተነሡ? አለቆችስ ከእነርሱ ጋር አብረው በእግዚአብሔርና በመሲሑ ላይ ለምን ዶለቱ?'),
  ('38d06e08-e93f-5054-a22f-30870d87b586', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 27, 27, 'በቀባኸው በቅዱስ ልጅህ ላይ ሄሮድስና ጰንጤናዊው ጲላጦስ ከወገኖቻቸውና ከእስራኤል ሕዝብ ጋር በእውነት በዚች ሀገር ላይ ዶለቱ።'),
  ('4cb82896-6572-5913-aed8-612c1cdee5f4', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 28, 28, 'እጅህና ምክርህ እንዲደረግ የወሰኑትን ይፈጽሙ ዘንድ።'),
  ('a6693bb4-e1d2-53e5-ae27-355063f0ce92', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 29, 29, 'አሁንም አቤቱ፥ ትምክህታቸውን ተመልከት፤ ቃልህንም በግልጥ ያስተምሩ ዘንድ ለባሮችህ ስጣቸው።'),
  ('cd7e9933-4525-5b3c-a371-76e2edba6012', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 30, 30, 'በቅዱሱ ልጅህም በኢየሱስ ክርስቶስ ስም ሕሙማንን ትፈውስ ዘንድ ተአምራትንና ድንቅ ሥራንም ታደርግ ዘንድ እጅህን ዘርጋ።”'),
  ('50ef85f3-79a3-573a-a5a8-6b819ca9da85', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '926288d3-33d2-51e9-aec0-56bfbae48fa9', 31, 31, 'ሲጸልዩም በአንድነት ተሰብስበው የነበሩበት ቦታ ተናወጠ፤ በሁሉም ላይ መንፈስ ቅዱስ መላባቸውና የእግዚአብሔርን ቃል በግልጥ አስተማሩ።'),
  ('5e9f6f61-e658-517b-acad-2e4034cac207', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '61ba0df4-5766-52b0-a886-65a5f609d0bd', 1, 32, 'ያመኑትም ሁሉ አንድ ልብና አንዲት ነፍስ ሆነው ይኖሩ ነበር፤ በውስጣቸውም የሁሉ ገንዘብ በአንድነት ነበር እንጂ “ይህ የእኔ ገንዘብ ነው” የሚል አልነበረም።'),
  ('498199e4-6f70-5117-a194-477ddffd03e8', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '61ba0df4-5766-52b0-a886-65a5f609d0bd', 2, 33, 'ሐዋርያትም የጌታችን ኢየሱስ ክርስቶስን ትንሣኤ በታላቅ ኀይል ይመሰክሩ ነበር፤ በሕዝቡም ዘንድ ታላቅ ጸጋ ነበራቸው።'),
  ('94b7becc-7307-5956-ab93-4524e77943db', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '61ba0df4-5766-52b0-a886-65a5f609d0bd', 3, 34, 'ከእነርሱም አንድ ስንኳ ችግረኛ አልነበረም፤ ቤትና መሬት ያላቸውም ሁሉ እየሸጡ ገንዘቡን ያመጡ ነበር።'),
  ('c21073de-a586-58cc-a5fb-2eb2b874b672', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '61ba0df4-5766-52b0-a886-65a5f609d0bd', 4, 35, 'አምጥተውም በሐዋርያት እግር አጠገብ ያኖሩት ነበር፤ እነርሱም ለእያንዳንዱ እንደ ፍላጎቱ ይከፍሉት ነበር።'),
  ('48980f32-d617-5680-aa04-df5254902e44', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '61ba0df4-5766-52b0-a886-65a5f609d0bd', 5, 36, 'በሐዋርያትም ዘንድ ትርጓሜዉ የመጽናናት ልጅ የሚሆን በርናባስ የተባለ የሌዊ ወገን ስሙን ዮሴፍ የሚሉት አንድ የቆጵሮስ ሰው ነበር።'),
  ('9ebf2710-247c-59c4-a6b9-6f0f9dfc4180', 'd7e0eea9-9cbc-592c-a7f1-2fa64e902d88', '61ba0df4-5766-52b0-a886-65a5f609d0bd', 6, 37, 'እርሻም ነበረውና ሽጦ ገንዘቡን አምጥቶ በሐዋርያት እግር አጠገብ አኖረው።'),
  ('55aab85f-be6c-571d-ab40-eff63c9af3c8', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 1, 1, 'ሐናንያ የተባለ አንድ ሰው ነበረ፤ ሚስቱም ሰጲራ ትባል ነበር፤ መሬቱንም ሸጠ።'),
  ('332614c7-84ca-5073-a4e8-9f6083c6de57', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 2, 2, 'ከሚስቱም ጋራ ተማክሮ የዋጋዉን እኩሌታ አስቀረ፤ የዋጋውንም እኩሌታ አምጥቶ በሐዋርያት እግር አጠገብ አስቀመጠ።'),
  ('10a353d1-324c-5510-a53c-9309cc18312e', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 3, 3, 'ጴጥሮስም፥ “ሐናንያ ሆይ፥ መንፈስ ቅዱስን ታታልለው ዘንድ፥ የመሬትህንም ዋጋ ከፍለህ ታስቀር ዘንድ ሰይጣን በልብህ እንዴት አደረ?'),
  ('71b88ad8-f8bd-523d-a1a8-f5fb8e6c2876', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 4, 4, 'ጥንቱን ሳትሸጠው ያንተ አልነበረምን? ከሸጥኸውስ በኋላ በፈቃድህ አልነበረምን? ይህን ነገር በልብህ ለምን ዐሰብህ? እግዚአብሔርን እንጂ ሰውን አላታለልህም” አለው።'),
  ('5b7f8508-a697-5c14-a9c9-66c19c7a22f8', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 5, 5, 'ሐናንያም ይህን በሰማ ጊዜ ወድቆ ሞተ፤ ጽኑ ፍርሀትም ሆነ፤ የሰሙትም ሁሉ ፈሩ።'),
  ('9f271ffa-6a30-5c40-a22a-2b15af8c06d5', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 6, 6, 'ከእነርሱም ጐልማሶች ተነሥተው ገነዙት፤ ተሸክመውም ወስደው ቀበሩት።'),
  ('eea1f7d5-c3ee-535b-a2cb-83756e11e5b7', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 7, 7, 'ይህም ከሆነ ከሦስት ሰዓት በኋላ ሚስቱ መጣች፤ ባልዋም የሆነውን ሳታውቅ ገባች።'),
  ('27c8b449-c5ce-58de-aed1-c3b3e6864b3f', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 8, 8, 'ጴጥሮስም፥ “እስኪ ንገሪኝ፥ መሬታችሁን የሸጣችሁት ይህን ለሚያህል ነውን?” አላት፤ እርስዋም፥ “አዎን፥ እንዲሁ ነው” አለች።'),
  ('89860d19-e486-58a1-a2cf-1532e626a8c7', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 9, 9, 'ጴጥሮስም፥ “እንግዲህ የእግዚአብሔርን መንፈስ ትፈታተኑት ዘንድ እንዴት ተባበራችሁ? እነሆ፥ ባልሽን የቀበሩት ሰዎች እግሮች በበር ናቸው፤ አንቺንም ይወስዱሻል” አላት።'),
  ('7d524623-7d30-52e0-ac28-4d9611facee7', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 10, 10, 'ያንጊዜም ከእግሩ በታች ወድቃ ሞተች፤ ጐልማሶችም በገቡ ጊዜ በድንዋን አገኙ፤ ወስደውም በባልዋ አጠገብ ቀበሩአት።'),
  ('4869926c-9578-5a49-ade7-7258ab20324b', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 11, 11, 'በአብያተ ክርስቲያናትና ይህንም ነገር በሰሙት ሁሉ ላይ ታላቅ ፍርሀት ሆነ።'),
  ('b56455e0-85cd-533a-a2fc-6eee573388a7', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 12, 12, 'በሐዋርያት እጅም በሕዝቡ ዘንድ ተአምራትና ድንቅ ሥራዎች ይሠሩ ነበር፤ በቤተ መቅደስም በሰሎሞን መመላለሻ በአንድነት ነበሩ።'),
  ('4dd5327c-1750-5395-a9ba-0027121cc113', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 13, 13, 'ሕዝቡም እጅግ ያከብሩአቸው ነበረ። ከሌሎችም ይቀርባቸው ዘንድ አንድ ስንኳን የሚደፍር አልነበረም።'),
  ('a5ee6fee-f2e2-5c01-a548-baa66cbff69b', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', 'ab5b36c6-d7bf-5743-a0c9-875e9bb1d306', 14, 14, 'በጌታችንም የሚያምኑ ብዙዎች ይጨመሩ ነበር፤ ወንዶችና ሴቶችም ብዙዎች ነበሩ።'),
  ('82dd3972-b2cd-5986-a0fe-614a31e1272b', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '6c847364-471f-5608-a782-7b5deba3d34b', 1, 15, 'ጴጥሮስም አልፎ ሲሄድ ጥላው ያርፍባቸው ዘንድ ድውዮችን በአልጋና በቃሬዛ እያመጡ በአደባባይ ያስቀምጡአቸው ነበር፤'),
  ('e3102f46-4db9-5329-ad12-2523af24a4d6', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '6c847364-471f-5608-a782-7b5deba3d34b', 2, 16, 'ደግሞም በኢየሩሳሌም ዙሪያ ከአሉ ከተሞች ብዙዎች ይመጡ ነበር፤ የታመሙትንና ክፉዎች አጋንንት የያዙአቸውንም ያመጡ ነበር፥ ሁሉም ይፈወሱ ነበር።'),
  ('f4cf8d94-8520-5f63-a747-333b25871225', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 1, 17, 'ሊቀ ካህናቱና አብረውት የነበሩት የሰዱቃውያን ወገኖችም ቀንተው በእነርሱ ላይ ተነሡ።'),
  ('b6c5f488-fa78-5711-afa2-bb4059d2ec8f', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 2, 18, 'እጃቸውንም በሐዋርያት ላይ አነሡ፤ ያዙአቸውም፤ በሕዝቡ ወኅኒ ቤትም አስገቧቸው።'),
  ('137484b8-53f6-548c-a2f1-496b7c25e7c0', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 3, 19, 'የእግዚአብሔር መልአክ ግን በሌሊት የወኅኒ ቤቱን ደጃፍ ከፍቶ አወጣቸው፤ እንዲህም አላቸው።'),
  ('ae2fa9f6-187f-50c5-a226-be63b8b62bd2', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 4, 20, '“ሂዱ፤ ወደ ቤተ መቅደስም ግቡና ለሕዝብ ይህን የሕይወት ቃል አስተምሩአቸው።”'),
  ('695dc80b-ad8e-5661-a332-be40d62e9b12', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 5, 21, 'ይህንም በሰሙ ጊዜ ጥዋት ገስግሠው ወደ ቤተ መቅደስ ገቡና አስተማሩ፤ ሊቀ ካህናቱና ከእርሱ ጋር የነበሩት ግን ጉባኤውንና ከእስራኤልም ቤት ሽማግሌዎችን ሁሉ ሰበሰቡ፤ ሐዋርያትንም ያመጡአቸው ዘንድ ወደ ወኅኒ ቤት ላኩ።'),
  ('8bc35f3d-0ed5-50f9-a6b1-b1ee5171699e', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 6, 22, 'አሽከሮቻቸውም መጥተው በወኅኒ ቤት አጡአቸውና ተመልሰው ነገሩአቸው።'),
  ('8a92b4b2-fcd7-591b-ac6d-6b7ba3c46d0b', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 7, 23, '“ወኅኒ ቤቱንም ዙሪያውን ተዘግቶ በቍልፍም ተቈልፎ አገኘነው፤ ወታደሮቹም በሩን ይጠብቁ ነበር፤ ነገር ግን ከፍተን በገባን ጊዜ በውስጥ ያገኘነው የለም” አሉአቸው።'),
  ('81809805-4e92-516e-af19-285c7da99397', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 8, 24, 'ሊቃነ ካህናትና የቤተ መቅደሱ ሹምም ይህን ነገር በሰሙ ጊዜ፥ የሚያደርጉትን አጥተው፥ “እንጃ ይህ ምን ይሆን?” አሉ።'),
  ('76831f45-5f63-5c4d-a318-c02251a173be', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 9, 25, 'አንድ ሰውም መጥቶ፥ “ያሰራችኋቸው እነዚያ ሰዎች እነሆ፥ በቤተ መቅደስ ውስጥ ናቸው፤ ቆመውም ሕዝቡን ያስተምራሉ” ብሎ ነገራቸው።'),
  ('f4a0e76b-89f7-5a63-a78e-3dfc83a386ae', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 10, 26, 'ከዚህም በኋላ የቤተ መቅደሱ ሹም ከሎሌዎቹ ጋር ሔዶ አባብሎ አመጣቸው፤ በግድም አይደለም፤ በድንጋይ እንዳይደበድቧቸው ሕዝቡን ይፈሩ ነበርና።'),
  ('9ae06787-c503-52e1-a487-86548bdc40a8', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 11, 27, 'አምጥተውም በሸንጎ መካከል አቆሙአቸው፤ ሊቀ ካህናቱም መረመራቸው፤'),
  ('1f186e9b-9c20-54d8-a421-f151dd12eefa', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 12, 28, '“በኢየሱስ ስም ለማንም እንዳታስተምሩ ከልክለናችሁ አልነበረምን? እነሆ፥ ኢየሩሳሌምን በትምህርታችሁ ሞላችኋት፤ የዚያንም ሰው ደም በእኛ ላይ ታመጡብን ዘንድ ትሻላችሁን?” አላቸው።'),
  ('ab3c0d34-3c01-5e69-a7af-4d37444592af', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 13, 29, 'ጴጥሮስና ሐዋርያትም መልሰው እንዲህ አሉአቸው፥ “ለሰው ከመታዘዝ ይልቅ ለእግዚአብሔር መታዘዝ ይገባል።'),
  ('e41c7941-04c8-507f-a635-3e45a147570c', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 14, 30, 'የአባቶቻችን አምላክ፥ እናንተ ክዳችሁ በዕንጨት ላይ ሰቅላችሁ የገደላችሁትን ኢየሱስን አስነሣው።'),
  ('019c1339-df44-5caa-a5f8-738c28e33c80', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 15, 31, 'እግዚአብሔር እርሱን ለእስራኤል ንስሓን፥ የኀጢአትንም ስርየት ይሰጥ ዘንድ ራስም አዳኝም አደረገው፤ በቀኙም አስቀመጠው።'),
  ('5c50112c-e75e-571a-a5b9-4d0cfa371590', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 16, 32, 'እኛም ለዚህ ነገር ምስክሮቹ ነን፤ እግዚአብሔር ለሚታዘዙት የሰጣቸው መንፈስ ቅዱስም ምስክር ነው።”'),
  ('407e23bd-11d2-5fd7-a278-25431825d78e', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '342f1680-fe9d-5e81-af21-2adf25dd32c1', 17, 33, 'ይህንም በሰሙ ጊዜ ተበሳጩ፤ ጥርሳቸውንም አፋጩ፤ ሊገድሉአቸውም ወደዱ።'),
  ('e696ad74-8c4d-5110-a9eb-478c7852ffcc', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 1, 34, 'በሸንጎዉም በሕዝቡ ሁሉ ዘንድ የከበረ የኦሪት መምህር ስሙን ገማልያል የሚሉት አንድ ፈሪሳዊ ተነሣ፤ ሐዋርያትንም ከጉባኤዉ ጥቂት ፈቀቅ እንዲያደርጉአቸው አዘዘ።'),
  ('30c17e82-3fd1-5f6b-ab1d-d6d4568d0163', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 2, 35, 'እርሱም እንዲህ አላቸው፥ “እናንተ የእስራኤል ሰዎች ሆይ፥ በእነዚህ ሰዎች በምታደርጉት ነገር ለራሳችሁ ተጠንቀቁ።'),
  ('9e8f3496-f441-5871-a42b-ba85cd0bbd7e', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 3, 36, 'ቀድሞም ከዚህ ዘመን በፊት ቴዎዳስ ተነሥቶ ራሱን ከፍ ከፍ አደረገ፤ አራት መቶ ሰዎችም ተከተሉት፤ ነገር ግን እርሱም ጠፋ፤ የተከተሉትም ሁሉ ተበታተኑ፤ እንደ ኢምንትም ሆኑ።'),
  ('54f7e535-4972-5c47-a970-c07ae2b0de5d', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 4, 37, 'ከእርሱም በኋላ ሰዎች ለግብር በተቈጠሩበት ወራት ገሊላዊው ይሁዳ ተነሣ፤ ብዙ ሕዝብም ተከተሉት፤ እርሱም ሞተ፤ የተከተሉትም ሁሉ ተበታተኑ።'),
  ('e3d20ba5-ce68-5ce9-ac18-9e6604cfdf61', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 5, 38, 'አሁንም እላችኋለሁ፥ ከእነዚህ ሰዎች ራቁ፤ ተዉአቸውም፤ ይህ ምክራቸው፥ ይህም ሥራቸው ከሰው የተገኘ ከሆነ ያልፋል ይጠፋልም።'),
  ('c30d5db5-1512-528f-a480-e9aa562a5c35', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 6, 39, 'ከእግዚአብሔር የመጣ ከሆነ ግን ልታፈርሱት አትችሉም፤ ከእግዚአብሔርም ጋር እንደሚጣላ አትሁኑ።”'),
  ('02d96ee6-19de-5b62-aedc-b2e47c79473b', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 7, 40, 'እሺም አሰኛቸው፤ ሐዋርያትንም ጠርተው ገረፉአቸው፤ እንግዲህ ወዲህም በኢየሱስ ስም እንዳያስተምሩ ገሥጸው ተዉአቸው።'),
  ('df9ae81b-5daf-57d2-a5f9-0586239e652d', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 8, 41, 'እነርሱም ከሸንጎው ፊት ደስ እያላቸው ወጡ፤ ስለ ስሙ መከራ ይቀበሉ ዘንድ መንፈስ ቅዱስ አድሎአቸዋልና።'),
  ('20feed84-a98f-596d-a30a-235640cdecfc', '860ef2bd-c9be-51a1-a7be-1d12e6b84776', '9295e577-e348-51c8-aac4-33031c4b4ba4', 9, 42, 'ሁልጊዜም በቤተ መቅደስና በቤት ስለ ጌታችን ስለ ኢየሱስ እርሱ ክርስቶስ እንደ ሆነ ማስተማርንና መስበክን አልተዉም።'),
  ('fbcd3a3b-6478-59ad-a950-ea248366a001', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 1, 1, 'በዚያም ወራት ደቀ መዛሙርት በበዙ ጊዜ ከግሪክ የመጡ ደቀ መዛሙርት በአይሁድ ምእመናን ላይ አንጐራጐሩባቸው፤ የዕለት የዕለቱን ምግብ ሲያካፍሉ ባልቴቶቻቸውን ቸል ይሉባቸው ነበርና።'),
  ('2557b8a6-5bf3-573e-a979-2c76f5e3f132', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 2, 2, 'ዐሥራ ሁለቱም ሐዋርያት ሕዝቡን ሁሉ ጠርተው እንዲህ አሉአቸው፥ “የእግዚአብሔርን ቃል ትተን ማዕድን እናገለግል ዘንድ የሚገባ አይደለም።'),
  ('19d57acf-bb54-5110-a2d8-b3c6ff13cc8b', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 3, 3, 'ወንድሞቻችን ሆይ፥ ከእናንተ ወገን በመልካም የተመሰከረላቸውን መንፈስ ቅዱስና ጥበብ የሞላባቸውን ሰባት ሰዎችን ምረጡ፤ ለዚህ ሥራም እንሾማቸዋለን።'),
  ('fedf7269-c4c6-5a8f-a8d0-3ccbee701fc4', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 4, 4, 'እኛ ግን ለጸሎትና ቃሉን ለማስተማር እንተጋለን።”'),
  ('b2919403-186a-562d-aaf3-d5a56d37279d', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 5, 5, 'ይህም ነገር በእነርሱ ዘንድ የተወደደ ሆነ፤ ሃይማኖቱ የቀናና መንፈስ ቅዱስ ያደረበትን ሰው እስጢፋኖስን፥ ፊልጶስን፥ ጵሮኮሮስን፥ ኒቃሮናን፥ ጢሞናን፥ ጰርሜናን፥ ወደ ይሁዲነት የተመለሰውን የአንጾኪያውን ኒቆላዎስንም መረጡ።'),
  ('e01fa03b-e276-5fb0-abda-419739cb657f', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 6, 6, 'በሐዋርያትም ፊት አቆሙአቸው፤ ጸልየውም እጃቸውን በራሳቸው ላይ ጫኑ።'),
  ('0bd1e0ed-75e7-5c99-a011-4a895a9ce60f', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '664896c5-5073-50cc-a83f-25d7d6b35268', 7, 7, 'የእግዚአብሔርም ቃል ከፍ ከፍ አለ፤ በኢየሩሳሌምም ምእመናን እጅግ በዙ፤ ከካህናትም መካከል ያመኑ ብዙዎች ነበሩ።'),
  ('95681591-13eb-521f-aea1-7178c4ebfe7b', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 1, 8, 'እስጢፋኖስም የእግዚአብሔር ጸጋና ኀይል የመላበት ሰው ነበር፤ በሕዝቡም መካከል ታላላቅ ተአምራትንና ድንቅ ሥራን ይሠራ ነበር።'),
  ('a3655e95-737e-551b-aa06-797f0e01dfbc', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 2, 9, 'የነጻ ወጭዎች ከምትባለው ምኵራብም ከቀሬናና ከእስክንድርያ፥ ከቂልቅያና ከእስያ የሆኑ ሰዎችም ተነሥተው እስጢፋኖስን ይከራከሩት ነበር።'),
  ('92287d36-2669-5961-aa8c-cc1a15cf43d0', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 3, 10, 'ነገር ግን ይቃወሙት ዘንድ አልቻሉም፤ በጥበብና በመንፈስ ቅዱስ ይከራከራቸው ነበርና።'),
  ('da2e9e89-7ce7-5a36-a9bb-57b919b1970f', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 4, 11, 'ከዚህም በኋላ “ይህን ሰው በሙሴና በእግዚአብሔር ላይ የስድብን ቃል ሲናገር ሰምተነዋል” የሚሉ የሐሰት ምስክሮችን አስነሡበት፤'),
  ('5c3d9617-9cae-5880-ad4e-13767dc9649b', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 5, 12, 'ሕዝቡን፥ ሽማግሌዎችንና ጸሓፊዎችንም አነሳሡአቸው፤ ከበውም እየጐተቱ ወደ ሸንጎ አቀረቡት።'),
  ('5c6f464d-1143-503d-a2d8-0c284079a750', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 6, 13, 'የሐሰት ምስክሮችንም አቆሙበት፤ እነርሱም እንዲህ አሉ፥ “ይህ ሰው በዚህ ቤተ መቅደስ ላይና በኦሪት ላይ የስድብ ቃል እየተናገረ ዝም በል ቢሉት እንቢ አለ፤'),
  ('b56d5401-f348-59b0-a285-291a4f288a23', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 7, 14, 'የናዝሬቱ ኢየሱስ ይህን ቤተ መቅደስ ያፈርሰዋል፤ ሙሴም የሰጠንን ኦሪታችንን ይሽራል ሲል ሰምተነዋል።”'),
  ('f5d2bf80-90ea-5345-af9a-88459b2d282f', '8ed00b40-d8f5-5940-ab2d-6ed6f16b3bda', '013ecb85-7348-594c-abee-e9f14be05e24', 8, 15, 'በሸንጎም ተቀምጠው የነበሩት ሁሉ ትኩር ብለው ተመለከቱት፤ ፊቱንም እንደ እግዚአብሔር መልአክ ፊት ሆኖ አዩት።'),
  ('046c83a9-e1b2-5d13-a57b-a987dcc0ca18', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 1, 1, 'ሊቀ ካህናቱም፥ “በእውነት እንዲህ ብለሃልን?” አለው።'),
  ('4db01dd7-62eb-56cf-a9c5-c431b8547578', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 2, 2, 'እርሱም እንዲህ አለ፥ “ወንድሞቻችንና አባቶቻችን ሆይ፥ ስሙ፤ የክብር አምላክ ለአባታችን ለአብርሃም በሁለት ወንዞች መካከል ሳለ ወደ ካራንም ሳይመጣ ተገለጠለት።'),
  ('415d4241-efbf-58ff-a970-db8e76e27399', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 3, 3, '‘ካገርህ ውጣ፤ ከዘመዶችህም ተለይ፤ እኔም ወደማሳይህ ሀገር ና’ አለው።'),
  ('63742ff7-8ff2-5460-a03b-a657138d3485', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 4, 4, 'ከዚህም በኋላ ከከለዳውያን ሀገር ወጥቶ በካራን ተቀመጠ፤ ከዚያም አባቱ ከሞተ በኋላ፥ ዛሬ እናንተ ወደ አላችሁባት ወደዚች ሀገር አመጣው።'),
  ('29c53e6d-87fe-5da9-a08c-787c10f39324', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 5, 5, 'በውስጥዋም አንድ ጫማ ታህል ስንኳን ርስት አልሰጠውም፤ ነገር ግን እርሱ ከእርሱም በኋላ ዘሩ ሊገዛት ልጅ ሳይኖረው ያንጊዜ እርስዋን ያወርሰው ዘንድ ተስፋ ሰጠው።'),
  ('c3372b63-a796-52f9-a6de-4725b210ca2d', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 6, 6, 'እግዚአብሔርም እንዲህ አለው፦ ‘ዘርህ በባዕድ ሀገር መጻተኞች ሆነው ይኖራሉ፤ አራት መቶ ዓመትም ባሮች አድርገው ይገዙአቸዋል፤ መከራም ያጸኑባቸዋል።'),
  ('7c590f95-423e-5e71-ac18-bc8d17a6a224', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 7, 7, 'ደግሞም እግዚአብሔር አለ፤ ባሮች አድርገው በሚገዙአቸው ወገኖች እኔ እፈርድባቸዋለሁ፤ ከዚህም በኋላ ይወጣሉ፤ በዚህም ሀገር ያመልኩኛል።’'),
  ('6e1e10dd-70e5-563f-ab91-bce21ac89970', '344426a6-5cff-5082-a503-418ab240243a', '41f2ae5a-8890-5059-ac37-7830f4f30030', 8, 8, 'የግዝረትንም ኪዳን ሰጠው፤ ከዚህም በኋላ ይስሐቅን ወለደ፤ በስምንተኛው ቀንም ገረዘው፤ እንዲሁ ይስሐቅም ያዕቆብን፥ ያዕቆብም ዐሥራ ሁለቱን የቀደሙ አባቶችን ገረዙ።'),
  ('40e026a2-63d6-5961-aeb9-e71a82e0ae6e', '344426a6-5cff-5082-a503-418ab240243a', '62aa9cf1-b5c9-5882-a2ba-805cbce475f7', 1, 9, '“የቀደሙ አባቶችም በዮሴፍ ላይ ቀንተው ወደ ግብፅ ሀገር ሸጡት፤ እግዚአብሔር ግን ከእርሱ ጋር ነበረ።'),
  ('4e9fb81e-496b-5bbd-ab51-2df862ef1100', '344426a6-5cff-5082-a503-418ab240243a', '62aa9cf1-b5c9-5882-a2ba-805cbce475f7', 2, 10, 'ከመከራውም ሁሉ አዳነው፤ በግብፅ ንጉሥ በፈርዖን ፊትም ሞገስንና ጥበብን ሰጠው፤ በግብፅና በቤቱ ሁሉ ላይ ቢትወደድ አድርጎ ሾመው።'),
  ('b6686b7b-f797-5350-a601-8d678f213a84', '344426a6-5cff-5082-a503-418ab240243a', '62aa9cf1-b5c9-5882-a2ba-805cbce475f7', 3, 11, 'በግብፅና በከነዓን ሀገር ሁሉ ረኃብና ታላቅ ጭንቅ መጣ፤ አባቶቻችንም የሚበሉት አጡ።'),
  ('55ff5f8d-f43d-5731-af1c-58b9d2f91aa6', '344426a6-5cff-5082-a503-418ab240243a', '62aa9cf1-b5c9-5882-a2ba-805cbce475f7', 4, 12, 'ያዕቆብም በግብፅ ሀገር እህል እንዳለ ሰማ፤ አባቶቻችንንም አስቀድሞ ላካቸው።'),
  ('16e45138-02df-5ae6-a489-be15255b4964', '344426a6-5cff-5082-a503-418ab240243a', '62aa9cf1-b5c9-5882-a2ba-805cbce475f7', 5, 13, 'ወደ ግብፅም እንደ ገና በተመለሱ ጊዜ ወንድሞቹ ዮሴፍን ዐወቁት፤ ፈርዖንም የዮሴፍን ዘመዶች ዐወቃቸው።'),
  ('f5e65678-54ad-58f3-a8ea-a24883ad6a61', '344426a6-5cff-5082-a503-418ab240243a', '62aa9cf1-b5c9-5882-a2ba-805cbce475f7', 6, 14, 'ዮሴፍም አባቱን ያዕቆብንና ዘመዶቹን ሁሉ እንዲጠሩአቸው ላከ፤ ቍጥራቸውም ሰባ አምስት ነፍስ ነበር።'),
  ('1366684a-4c84-5b80-a7c8-e5d962d7d941', '344426a6-5cff-5082-a503-418ab240243a', 'e940d7e3-867b-56f3-af0f-e15def5a24d7', 1, 15, '“ያዕቆብም ወደ ግብፅ ወረደ፥ እርሱም አባቶቻችንም ሞቱ።'),
  ('eaa7e0e8-7b90-55e2-a7d0-89001b34a76a', '344426a6-5cff-5082-a503-418ab240243a', 'e940d7e3-867b-56f3-af0f-e15def5a24d7', 2, 16, 'ወደ ሴኬምም አፍልሰው አብርሃም ከሴኬም አባት ከኤሞር ልጆች በገንዘቡ በገዛው መቃብር ቀበሩዋቸው።'),
  ('7c157b7f-fa6c-50f6-a437-3cbe4b91344b', '344426a6-5cff-5082-a503-418ab240243a', 'e940d7e3-867b-56f3-af0f-e15def5a24d7', 3, 17, '“እግዚአብሔርም ለአብርሃም የማለለት የተስፋው ዘመን በደረሰ ጊዜ እስራኤል በዙ፤ የግብፅንም ሀገር መሉ።'),
  ('a4f38df9-4d39-5459-afde-827e82b31b09', '344426a6-5cff-5082-a503-418ab240243a', 'e940d7e3-867b-56f3-af0f-e15def5a24d7', 4, 18, 'ይህም ዮሴፍን የማያውቀው ሌላ ንጉሥ በግብፅ እስከ ነገሠ ድረስ ነበር።'),
  ('127dbeb9-7b69-5f78-adc7-abe44738744b', '344426a6-5cff-5082-a503-418ab240243a', 'e940d7e3-867b-56f3-af0f-e15def5a24d7', 5, 19, 'እርሱም ወገኖቻችንን ተተንኵሎ አባቶቻችንን መከራ አጸናባቸው፤ ወንድ ልጅንም ሁሉ እንዲገድሉ አዘዘ።'),
  ('2f681926-068f-51e7-a9ce-78994b89c750', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 1, 20, '“ያንጊዜም ሙሴ ተወለደ፤ በእግዚአብሔር ፊትም የተወደደ ሆነ፤ ለሦስት ወርም በአባቱ ቤት አሳደጉት።'),
  ('b7d58630-f178-5b8c-a856-1090b111af28', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 2, 21, 'በተጣለም ጊዜ የፈርዖን ልጅ አነሣችው፤ ልጅም ይሆናት ዘንድ አሳደገችው።'),
  ('0bc318f3-c2e9-579c-a89f-473dcbe6f3cf', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 3, 22, 'ሙሴም የግብፅን ጥበብ ሁሉ ተማረ፤ በሚናገረውና በሚሠራውም ሁሉ ብርቱ ሆነ።'),
  ('1ac78c3a-42ae-5346-a301-eff962e9dc52', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 4, 23, '“አርባ ዓመት ሲሞላውም ወንድሞቹን የእስራኤልን ልጆች ሊጐበኛቸው በልቡ ዐሰበ።'),
  ('936d0ecd-2f01-5ac2-a206-cd58a0fdf48f', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 5, 24, 'አንድ ግብፃዊም ዕብራዊውን ሲበድለው አገኘና ለዚያ ለተበደለው ረድቶ ግብፃዊውን ገደለው በአሸዋም ቀበረው።'),
  ('19977e48-ecfa-5f37-aec0-c7f4bdd98b29', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 6, 25, 'እርሱም እግዚአብሔር በእጁ ድኅነትን እንደሚያደርግላቸው የሚያስተውሉ መስሎት ነበር፤ እነርሱ ግን አላስተዋሉም።'),
  ('0ed1ff70-33b7-5ce4-ac68-dbd64f658fae', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 7, 26, 'በማግሥቱም ከመካከላቸው ሁለት ሰዎች እርስ በርሳቸው ሲጣሉ አገኘ፤ ሊያስታርቃቸውም ወድዶ፦ ‘እናንተማ ወንድማማቾች ናችሁ፤ እርስ በርሳችሁ ለምን ትጣላላችሁ?’ አላቸው።'),
  ('c0895c5a-7885-5a5f-ab10-a599eb692a1d', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 8, 27, 'ያም ባልንጀራውን የሚበድለው ገፋው፤ እንዲህም አለው፦ ‘አንተን በእኛ ላይ ዳኛና ፈራጅ አድርጎ ማን ሾመህ?'),
  ('9851173f-ce28-5351-a2ff-b1960cccae13', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 9, 28, 'ወይስ ትናንትና ግብፃዊውን እንደ ገደልኸው እኔንም ልትገድለኝ ትሻለህን?’'),
  ('9fc4fcc6-fe9c-5fe1-a0e9-b45d0a296ce2', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 10, 29, 'ስለዚህም ነገር ሙሴ ኮብልሎ በምድያም ሀገር ስደተኛ ሆኖ ኖረ፤ በዚያም ሁለት ልጆችን ወለደ።'),
  ('47bdd666-9f4b-521e-ae94-a76981350d7f', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 11, 30, '“አርባ ዓመትም በተፈጸመ ጊዜ በበረሃ በደብረ ሲና የእግዚአብሔር መልአክ በቍጥቋጦ መካከል በእሳት ነበልባል ታየው።'),
  ('821b1ca8-81e2-5b75-a796-c33d585c097b', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 12, 31, 'ሙሴም አይቶ በአየው ተደነቀ፤ ሊያስተውለውም ቀረበ፤ እግዚአብሔርም እንዲህ ብሎ ተናገረው።'),
  ('3a3b4d7a-bc95-524e-acae-f624e7530d6a', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 13, 32, '‘እኔ የአባቶችህ አምላክ፥ የአብርሃም አምላክ፥ የይስሐቅ አምላክ፥ የያዕቆብም አምላክ ነኝ፤’ ሙሴም ተንቀጠቀጠ፤ መረዳትም አልቻለም።'),
  ('a6d3e93e-1462-5412-a056-2e9f8d1f3d9f', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 14, 33, 'እግዚአብሔርም እንዲህ አለው፦ ‘ጫማህን ከእግርህ አውልቅ፤ የቆምህባት ምድር የተቀደሰች ናትና።'),
  ('00e90e04-a392-50eb-a1f6-9b2280941d06', '344426a6-5cff-5082-a503-418ab240243a', '98360fa6-6f5c-5e89-a4ec-94413deb3fac', 15, 34, 'በግብፅ ያሉትን የወገኖችን መከራ ማየትን አይቻለሁ፤ ጩኸታቸውንም ሰምቻለሁ፤ ላድናቸውም ወርጃለሁ፤ አሁንም ና ወደ ግብፅ ሀገር ልላክህ።’'),
  ('61f5711c-3621-5824-a939-51312b6edf82', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 1, 35, '“በእኛ ላይ አለቃና ፈራጅ ማን አድርጎሃል? ብለው የካዱትን ያን ሙሴን በቍጥቋጦው መካከል በታየው በመልአኩ እጅ እርሱን መልእክተኛና አዳኝ አድርጎ እግዚአብሔር ላከው።'),
  ('a843c9e8-5ba1-5571-a8e0-acab96a954b7', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 2, 36, 'እርሱም አርባ ዘመን በግብፅ ሀገርና በኤርትራ ባሕር፥ በበረሃም ተአምራትንና ድንቅ ሥራን እየሠራ አወጣቸው።'),
  ('a82e71bd-ffcf-5408-a504-b54d898ace7e', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 3, 37, 'ለእስራኤልም ልጆች፦ ‘እግዚአብሔር ከወንድሞቻችሁ መካከል እንደ እኔ ያለ ነቢይ ያስነሣላችኋልና እርሱን ስሙት’ ያላቸው ይህ ሙሴ ነው።'),
  ('da6cccac-e46a-57d5-a40d-8c050e40c335', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 4, 38, 'በምድረ በዳ በማኅበሩ መካከል የነበረ እርሱ ነው፤ በደብረ ሲና ከአነጋገረው መልአክና፤ ከአባቶቻችንም ጋር ለእኛ ሊሰጠን የሕይወትን ቃል የተቀበለ እርሱ ነው።'),
  ('5984e3bb-f81b-5c0b-a625-07f11997897e', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 5, 39, 'አባቶቻችን ለእርሱ መታዘዝን እንቢ አሉ፤ ከዱትም፤ ልባቸውንም ወደ ግብፅ ሀገር መለሱ።'),
  ('c31a8a85-2c8a-54fd-ab22-a82541f9ea13', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 6, 40, 'አሮንንም፦ ‘በፊት በፊታችን የሚሄዱ አማልክትን ሥራልን፤ ያ ከምድረ ግብፅ ያወጣን ሙሴ የሆነውን አናውቅምና’ አሉት።'),
  ('e8c5cb3c-6d78-545b-a54a-9875e3979c59', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 7, 41, 'ያንጊዜም የጥጃ ምስል ሠሩ፤ ለጣዖቱም መሥዋዕት አቀረቡ፤ በእጃቸው ሥራም ደስ አላቸው።'),
  ('6c73fe2b-5c4d-5d5a-a28b-e74da8acd898', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 8, 42, 'እግዚአብሔርም ተለያቸው፤ የሰማይ ጭፍራን ያመልኩም ዘንድ ተዋቸው፤ የነቢያት መጽሐፍ እንዲህ እንዳለ፤ ‘እናንት የእስራኤል ወገኖች ሆይ፥ በውኑ በምድረ በዳ ሳላችሁ አርባ ዐመት ያቀረባችሁልኝ ቍርባንና መሥዋዕት አለን?'),
  ('68d3e39a-b702-5b92-a3ee-97764fc0024d', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 9, 43, 'ነገር ግን የሞሎህን ድንኳን አነሣችሁ፤ ሬፋን የሚባለውንም ኮከብ አመለካችሁ፤ ትሰግዱላቸውም ዘንድ ምስሎቻቸውን አበጃችሁ፤ እኔም ወደ ባቢሎን እንድትማረኩ አደርጋችኋለሁ።’'),
  ('d05f10d4-9874-535e-a14e-39911cf5649d', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 10, 44, '“ሙሴን ተናግሮ እንደ አዘዘው በአሳየው ምሳሌ የሠራት የምስክር ድንኳን በአባቶቻችን ዘንድ በምድረ በዳ ነበረች።'),
  ('eb795164-500f-531c-a428-5eaf2578accb', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 11, 45, 'ኢያሱና አባቶቻችንም በተራ ተቀብለው እግዚአብሔር ከአባቶቻችን ፊት አስወጥቶ ወደ ሰደዳቸው ወደ አሕዛብ ሀገር ከእነርሱ ጋር አገቡአት፤ እስከ ዳዊት ዘመንም ነበረች።'),
  ('0d8d9b6b-8e5d-5426-ae68-14137e1f0fe2', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 12, 46, 'ዳዊትም በእግዚአብሔር ፊት ባለመዋልነትን አግኝቶ ለያዕቆብ አምላክ ማደሪያ ያገኝ ዘንድ ለመነ።'),
  ('8975a25a-6e51-59a3-a43c-41f8abe8fa9a', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 13, 47, 'ሰሎሞን ግን ቤትን ሠራለት።'),
  ('5f79227a-c5cc-5446-ada7-c4f9810761d1', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 14, 48, 'ነገር ግን ልዑል የሰው እጅ በሠራው ቤት የሚኖር አይደለም፤ ነቢይ እንዲህ ብሎአልና።'),
  ('2c3ef6b2-b366-59a1-aef2-5d8ae95af3ce', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 15, 49, 'እግዚአብሔር እንዲህ ይላል፦ ‘ሰማይ ዙፋኔ ነው፤ ምድርም የእግሬ መረገጫ ናት፤ ምን ዐይነት ቤት ትሠሩልኛላችሁ? የማርፍበት ቦታስ ምን ዐይነት ቦታ ነው?'),
  ('ca1ea02a-21cc-5a0b-a8aa-3eaa65263507', '344426a6-5cff-5082-a503-418ab240243a', '193fdabe-f618-5cde-ac95-ba3ece27e949', 16, 50, 'ይህን ሁሉ እጆች የሠሩት አይደለምን?’'),
  ('f1a99a35-d3b2-5f65-ab23-f608d83b4350', '344426a6-5cff-5082-a503-418ab240243a', '6803c2e2-4462-5182-a550-bf89f76e4753', 1, 51, '“እናንተ አንገታችሁ የደነደነ፥ ልባችሁም የተደፈነ፥ ጆሮአችሁም የደነቈረ፥ እንደ አባቶቻችሁ መንፈስ ቅዱስን ዘወትር ትቃወማላችሁ።'),
  ('edadabe5-6e4f-54a9-a2e2-62e033c5e51a', '344426a6-5cff-5082-a503-418ab240243a', '6803c2e2-4462-5182-a550-bf89f76e4753', 2, 52, 'አባቶቻችሁ ከነቢያት ያላሳደዱት ማን አለ? ዛሬም እናንተ አሳልፋችሁ የሰጣችሁትንና የገደላችሁትን የጻድቁን መምጣት አስቀድመው የተናገሩትን ገደሉአቸው።'),
  ('99c65127-8b31-5e72-a568-e0720b9c30c9', '344426a6-5cff-5082-a503-418ab240243a', '6803c2e2-4462-5182-a550-bf89f76e4753', 3, 53, 'በመላእክትም ሥርዐት ኦሪትን ተቀብላችሁ አልጠበቃችሁትም።”'),
  ('85ed3a13-a52a-5e4b-aaa8-e0c17a735ac2', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 1, 54, 'ይህንም ሰምተው ተበሳጩ፤ ልባቸውም ተናደደ፤ ጥርሳቸውንም አፋጩበት።'),
  ('e05f80e0-c254-5d4f-a600-ed33335d662f', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 2, 55, 'በእስጢፋኖስም ላይ መንፈስ ቅዱስ መላ፤ ወደ ሰማይም ተመለከተ፤ የእግዚአብሔርን ክብር፥ ኢየሱስም በእግዚአብሔር ቀኝ ቆሞ አየ።'),
  ('8bf3c511-ce93-556a-a763-3509094d3598', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 3, 56, '“እነሆ ሰማይ ተከፍቶ፤ የሰው ልጅም በእግዚአብሔር ቀኝ ቆሞ አያለሁ” አለ።'),
  ('21763158-6320-5313-a976-8697ed51b2c1', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 4, 57, 'እነርሱም በታላቅ ቃል ጮኹ፤ ጆሮአቸውንም ደፈኑ፤ በአንድነትም ተነሥተው ከበቡት።'),
  ('4774fa9b-aee6-52ea-aec6-51ac29d27a57', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 5, 58, 'ከከተማም ወደ ውጭ ጐትተው አውጥተው ወገሩት፤ የሚወግሩት ሰዎችም ልብሳቸውን ሳውል በሚባል ጐልማሳ እግር አጠገብ አስቀመጡ።'),
  ('0acafed8-b27d-55bb-a9df-459cee24b886', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 6, 59, 'እስጢፋኖስም፥ “ጌታዬ ኢየሱስ ሆይ፥ ነፍሴን ተቀበል” እያለ ሲጸልይ ይወግሩት ነበር።'),
  ('fde29e88-09a3-50c8-a3ed-76fcaac83b37', '344426a6-5cff-5082-a503-418ab240243a', 'c2a75570-b22e-513a-a0fa-2d9275c8bd6e', 7, 60, 'በጕልበቱም ተንበርክኮ፥ “አቤቱ፥ ይህን ኀጢአት አትቍጠርባቸው” ብሎ በታላቅ ድምፅ ጮኸ። ይህንም ብሎ ሞተ፤ ሳውልም በእስጢፋኖስ ሞት ተባባሪ ነበር።'),
  ('66471ee0-d0eb-5731-a01f-f4c509c023bb', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '4b89711a-86e9-5bed-aa94-403d1d49301c', 1, 1, 'በዚያ ወራትም በኢየሩሳሌም ባለችው ቤተ ክርስቲያን ላይ ታላቅ ስደት ሆነ፤ ከሐዋርያትም በቀር ሁሉም በይሁዳና በሰማርያ ባሉ አውራጃዎች ሁሉ ተበተኑ።'),
  ('cc98b409-cd14-501e-a732-d6d31483a230', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '4b89711a-86e9-5bed-aa94-403d1d49301c', 2, 2, 'እስጢፋኖስንም ደጋግ ሰዎች አንሥተው ቀበሩት፤ ታላቅ ልቅሶም አለቀሱለት።'),
  ('530f81f7-00a9-5cce-a2b2-ae088e4522c9', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 1, 3, 'ሳውል ግን ገና አብያተ ክርስቲያናትን ይቃወም ነበር፤ የሰውንም ቤት ሁሉ ይበረብር ነበር፤ ወንዶችንም ሴቶችንም እየጐተተ ወደ ወኅኒ ቤት ያስገባቸው ነበር።'),
  ('a7f6c42d-9755-5ef3-a126-b85d9145a612', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 2, 4, 'የተበተኑት ግን እየተዘዋወሩ የእግዚአብሔርን ቃል ሰበኩ፥ አስተማሩም።'),
  ('fca8016e-f356-5ec8-a7cb-7f149935eb70', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 3, 5, 'ፊልጶስም ወደ ሰማርያ ከተማ ወረደ፤ ስለ ክርስቶስም ሰበከላቸው።'),
  ('3ab96a17-ae13-5e10-aee7-d0c86795bf23', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 4, 6, 'ሕዝቡም የነገራቸውን በሰሙና ያደርገው የነበረውን ተአምራት በአዩ ጊዜ በአንድ ልብ የፊልጶስን ነገር ተቀበሉ።'),
  ('ce3f9576-2655-52ab-a06d-af336538f001', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 5, 7, 'ርኩሳን መናፍስት ያደሩባቸውም ብዙዎች ነበሩና፥ በታላቅ ቃል እየጮኹ ይወጡ ነበር፤ ብዙዎች ልምሾዎችና አንካሶችም ይፈወሱ ነበር።'),
  ('74a7961b-96ab-5f9e-a173-235b7c7512be', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 6, 8, 'በዚያችም ከተማ ታላቅ ደስታ ሆነ።'),
  ('3c1be3eb-4a84-5ff5-a8e6-a41718f09b99', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 7, 9, 'በዚያችም ከተማ ሲሞን የሚባል አንድ ሰው ነበር፤ የሰማርያ ሰዎችንም ያስት ነበር፤ ሰውየዉ ሥራየኛ ነበር፤ ራሱንም ታላቅ ያደርግ ነበር።'),
  ('6e3a5d2f-4612-5ce7-a8a7-619d9627c055', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 8, 10, 'ከታናናሾቹም ጀምሮ እስከ ታላላቆቹ ድረስ “ታላቁ የእግዚአብሔር ኀይል ይህ ነው” እያሉ ሁሉም ያደምጡት ነበር።'),
  ('23424432-3123-572c-a595-4e0bc332ca07', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 9, 11, 'ከብዙ ዘመንም ጀምሮ በጥንቈላው ያታልላቸው ስለ ነበር ያዳምጡት ነበር።'),
  ('af6f8210-e4d2-528f-a74a-5226fefb4a00', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 10, 12, 'ነገር ግን ፊልጶስ ስለ እግዚአብሔር መንግሥትና ስለ ኢየሱስ ክርስቶስ ሰብኮላቸው በአመኑ ጊዜ ሴቶችም ወንዶችም ተጠመቁ።'),
  ('b0bd1562-8537-50a3-a111-ee790306d098', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 11, 13, 'ሲሞንም ወዲያውኑ አምኖ ተጠመቀ፤ ፊልጶስንም ይከተል ጀመር፤ በፊልጶስም እጅ የሚደረገውን ተአምርና ታላቅ ኀይል ባየ ጊዜ ይደነቅ ነበር።'),
  ('5cb5e431-9997-5482-a40e-57cc997712b4', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 12, 14, 'በኢየሩሳሌም የነበሩ ሐዋርያትም የሰማርያ ሰዎች የእግዚአብሔርን ቃል እንደ ተቀበሉ በሰሙ ጊዜ ጴጥሮስንና ዮሐንስን ወደ እነርሱ ላኩላቸው።'),
  ('5beff27f-cec8-5ccc-acbe-49dbde5181c0', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 13, 15, 'ወርደውም መንፈስ ቅዱስን እንዲቀበሉ ጸለዩላቸው።'),
  ('de6d0f73-c63a-53c9-a4f9-b274ab119d0d', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 14, 16, 'በጌታችን በኢየሱስ ክርስቶስ ስም ተጠመቁ እንጂ ከመካከላቸው በአንዱ ላይ ስንኳ መንፈስ ቅዱስ ገና አልወረደም ነበርና።'),
  ('f673aa81-deab-5a5c-adbc-cbf170531218', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 15, 17, 'በዚያ ጊዜም እጃቸውን ጫኑባቸው፤ መንፈስ ቅዱስንም ተቀበሉ።'),
  ('e076fca2-d7eb-5c9e-a936-daf2b5ad5af9', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 16, 18, 'ሲሞንም ሐዋርያት እጃቸውን በጫኑበት ሰው ላይ መንፈስ ቅዱስ እንደሚወርድ ባየ ጊዜ ገንዘብ አመጣላቸውና፥'),
  ('9ec2e90e-736e-5882-a9c5-fb8a4477e5f8', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 17, 19, '“እጄን በምጭንበት ሰው ላይ መንፈስ ቅዱስ ይወርድ ዘንድ ለእኔም ይህን ሥልጣን ስጡኝ” አላቸው።'),
  ('10bd7d0c-14d5-5134-ae2c-74d322b2488e', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 18, 20, 'ጴጥሮስ ግን እንዲህ አለው፥ “የእግዚአብሔርን ጸጋ በገንዘብ ልትገዛ ዐስበሃልና ገንዘብህ ከአንተ ጋር ይጥፋ።'),
  ('03a497bb-3147-5761-adca-7532eb668720', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 19, 21, 'በዚህ ነገር ዕድልና ርስት የለህም፥ በእግዚአብሔር ፊት ልብህ የቀና አይደለምና።'),
  ('53f5fad9-2fa1-5ced-ab00-d9624b1c453f', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 20, 22, 'አሁንም ከክፋትህ ተመለስና ንስሓ ግባ። የልቡናህንም ዐሳብ ይተውልህ እንደ ሆነ እግዚአብሔርን ለምን።'),
  ('35dc6fb1-98b7-539d-a501-aa9f8eb36f34', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 21, 23, 'በመራራ መርዝ ተመርዘህ፥ በዐመፃ ማሰሪያ ተተብትበህ የምትኖር ሆነህ አይሃለሁና።”'),
  ('b9290bfb-80f0-5383-acca-f998bc7e9204', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 22, 24, 'ሲሞንም መልሶ፥ “ካላችሁት ሁሉ ምንም እንዳይደርስብኝ እናንተ ወደ እግዚአብሔር ለምኑልኝ” አለ።'),
  ('67711c00-e1ac-56fd-a3a4-3d97607ab22c', '27daa8bf-32de-58a3-a214-d5f4a88f407f', '1b7617f0-5159-59b6-ad9d-a3018638fd65', 23, 25, 'እነርሱም ከመሰከሩና የእግዚአብሔርን ቃል ከተናገሩ በኋላ ወደ ኢየሩሳሌም ተመለሱ፤ በብዙዎች የሰማርያ መንደሮችም የእግዚአብሔርን ቃል አስተማሩ።'),
  ('d45cd399-b9eb-5e71-ad00-af7e885d800e', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 1, 26, 'የእግዚአብሔር መልአክም ፊልጶስን ተናገረው፤ እንዲህም አለው፥ “በቀትር ጊዜ ተነሣና በደቡብ በኩል ከኢየሩሳሌም ወደ ጋዛ በሚያወርደው በምድረ በዳው መንገድ ሂድ።”'),
  ('df67daa1-2b3e-5e9e-a66b-557727e1a5f8', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 2, 27, 'ተነሥቶም ሄደ፤ እነሆም፥ የኢትዮጵያ ንግሥት የሕንደኬ ጃንደረባ ከሹሞችዋ የበለጠ፥ በሀብቷም ሁሉ ላይ በጅሮንድ የነበረ፥ አንድ የኢትዮጵያ ሰው ነበር፤ እርሱም ሊሰግድ ወደ ኢየሩሳሌም መጣ።'),
  ('73c0d1ef-3b86-51d1-afc1-dfa06b5c9023', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 3, 28, 'ሲመለስም በሰረገላው ላይ ተቀምጦ የነቢዩ የኢሳይያስን መጽሐፍ ያነብ ነበር።'),
  ('f4ab7029-5c56-54f4-a23b-be4a2195fa79', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 4, 29, 'መንፈስ ቅዱስም ፊልጶስን፥ “ሂድ፤ ይህን ሰረገላ ተከተለው” አለው።'),
  ('9f0d806e-d55e-563b-a370-05ebc56c936e', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 5, 30, 'ፊልጶስም ፈጥኖ ደርሶ የነቢዩን የኢሳይያስን መጽሐፍ ሲያነብ ሰማው፤ ፊልጶስም፥ “በውኑ የምታነበውን ታውቀዋለህን?” አለው።'),
  ('bfc433d5-9ff4-526c-a988-665cc0ccd60f', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 6, 31, 'ጃንደረባውም፥ “ያስተማረኝ ሳይኖር በምን አውቀዋለሁ?” አለው፤ ወደ ሰረገላውም ወጥቶ አብሮት ይቀመጥ ዘንድ ፊልጶስን ለመነው።'),
  ('c1f7ff42-3d8a-5def-a450-9cbf366a7da2', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 7, 32, 'ያነበው የነበረ የመጽሐፉ ቃልም እንዲህ የሚል ነበር፤ “እንደ በግ ወደ መታረድ ተነዳ፤ የበግ ጠቦትም በሚሸልተው ፊት እንደማይናገር እንዲሁ አፉን አልከፈተም።'),
  ('e9a80e29-5bb6-5fb2-a3a8-2fbd44038806', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 8, 33, 'በውርደቱ ፍርዱ ተወገደ፤ ሕይወቱ ከምድር ተወግዶአልና ትውልዱን ማን ይናገራል?”'),
  ('c224efce-7987-5e7c-a2ba-214fdf848c4e', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 9, 34, 'ጃንደረባውም ለፊልጶስ መልሶ፥ “ነቢዩ ስለ ማን እንዲህ ይላል? ስለ ራሱ ነውን? ወይስ ስለ ሌላ? እባክህ ንገረኝ” አለው።'),
  ('c5627f86-2952-5b90-a068-98d5ea9b797d', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 10, 35, 'ፊልጶስም አፉን ከፈተ፤ ስለ ኢየሱስም ከዚያው መጽሐፍ ጀምሮ አስተማረው።'),
  ('52e99dfd-a56c-5b08-ac3d-9fa34b5875a1', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 11, 36, 'በመንገድ ሲሄዱም ወደ ውኃ ደረሱ፤ ጃንደረባውም፥ “እነሆ፥ ውኃ፥ መጠመቅን ምን ይከለክለኛል?” አለው።'),
  ('375b4e27-aed5-57e3-aebb-b49db058b47a', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 12, 37, 'ፊልጶስም፥ “በፍጹም ልብህ ብታምን ይገባሃል” አለው፤ ጃንደረባውም መልሶ፥ “ኢየሱስ ክርስቶስ የእግዚአብሔር ልጅ እንደ ሆነ እኔ አምናለሁ” አለው።'),
  ('49359078-e4cb-5b53-aac4-c42b9d94f9d7', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 13, 38, 'ሰረገላውንም እንዲያቆሙ አዘዘ፤ አቁመውም ፊልጶስና ጃንደረባው በአንድነት ወደ ውኃው ወረዱ፤ አጠመቀውም።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a4f3e259-c38a-548b-ab36-466ea238931a', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 14, 39, 'ከውኃዉም ከወጡ በኋላ የእግዚአብሔር መንፈስ ፊልጶስን ነጥቆ ወሰደው፤ ጃንደረባዉም ከዚያ ወዲያ አላየውም፤ ደስ እያለውም መንገዱን ሄደ።'),
  ('142a2c97-5901-510c-af3f-2d7ba973ec6a', '27daa8bf-32de-58a3-a214-d5f4a88f407f', 'e8d26263-9fc1-5bc9-ab97-06590505a266', 15, 40, 'ፊልጶስም አዛጦን ወደምትባል ሀገር ደረሰ፤ በከተማዎችም ሁሉ እየተዘዋወረ ወደ ቂሳርያ እስኪደርስ ድረስ ያስተምር ነበር።'),
  ('d67d6d53-8f7b-5ec4-aef4-c06eaf023d49', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 1, 1, 'ሳውል ግን የጌታን ደቀ መዛሙርት ለመግደል ገና እየዛተ ወደ ሊቀ ካህናቱ ሄደ።'),
  ('34ecf2be-891d-5c99-a0f5-abb981d1e493', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 2, 2, 'ምንአልባት በመንገድ የሚያገኘው ሰው ቢኖር ወንዶችንም ሴቶችንም እያሰረ ወደ ኢየሩሳሌም ያመጣቸው ዘንድ በደማስቆ ላሉት ምኵራቦች የሥልጣን ደብዳቤ ከሊቀ ካህናቱ ለመነ።'),
  ('02fd6fec-b018-55a5-aa84-d58a562a1762', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 3, 3, 'ሲሄድም ወደ ደማስቆ ከተማ አቅራቢያ በደረሰ ጊዜ መብረቅ ድንገት ከሰማይ ብልጭ አለበት።'),
  ('3da983a1-d5bb-52b2-a1e8-78c4b3ff0bfa', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 4, 4, 'በምድር ላይም ወደቀ፤ ወዲያውም፥ “ሳውል፥ ሳውል፥ ለምን ታሳድደኛለህ?” የሚለውን ቃል ሰማ።'),
  ('b6b57c08-435d-5ec3-a5fa-a9c3ebd0af18', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 5, 5, 'ሳውልም፥ “አቤቱ፥ አንተ ማነህ?” አለው፤ እርሱም፥ “አንተ የምታሳድደኝ የናዝሬቱ ኢየሱስ ነኝ፤ በሾለ ብረት ላይ ብትቆም ለአንተ ይብስሃል” አለው።'),
  ('d6cc9fcb-19e1-524c-a9df-f94b16dc31ca', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 6, 6, 'እርሱም እየፈራና እየተንቀጠቀጠ፥ “አቤቱ፥ ምን እንዳደርግ ትሻለህ?” አለው፤ ጌታም፥ “ተነሣና ወደ ከተማ ግባ፤ በዚያም ልታደርገው የሚገባህን ይነግሩሃል” አለው።'),
  ('5af99292-e669-5524-a69a-38e3518124f0', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 7, 7, 'ከእርሱም ጋር የነበሩት ሰዎች ድምፅ እየሰሙ ማንንም ሳያዩ ተደንቀው ቆሙ።'),
  ('17b32abc-234c-5517-a84c-5b474e40fb4c', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 8, 8, 'ሳውልም ከምድር ተነሣ፤ ነገር ግን ዐይኖቹ ተገልጠው ሳሉ የሚያየው ነገር አልነበረም፤ እየመሩም ወደ ደማስቆ አገቡት።'),
  ('ddd8aee2-511b-57d8-ad50-ed80f012e5d9', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 9, 9, 'በዚያም ሳያይ ሳይበላና ሳይጠጣ ሦስት ቀን ቈየ።'),
  ('c306826c-6a4d-5814-a891-2bab357a41c2', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 10, 10, 'በደማስቆም ስሙን ሐናንያ የሚሉት አንድ ደቀ መዝሙር ነበር፤ ጌታም በራእይ ተገልጦ፥ “ሐናንያ” ብሎ ጠራው፤ እርሱም፥ “አቤቱ፥ እነሆኝ” አለ።'),
  ('f228bc9d-2439-5bad-a948-2382c38af60a', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 11, 11, 'ጌታም፥ “ተነሣና ቅን በምትባለው መንገድ ሂድ፤ በይሁዳ ቤትም ከጠርሴስ ሀገር የመጣ ሳውል የሚባል ሰው ፈልግ፤ እርሱ አሁን ይጸልያልና” አለው።'),
  ('d150c5f8-3ee8-5dff-a584-6d2e43dc1398', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 12, 12, 'ሳውልም በራእይ ሐናንያ የሚባል ሰው ወደ እርሱ ገብቶ ያይ ዘንድ እጁን ሲጭንበት አየ።'),
  ('953227de-b01d-5b3a-a20c-1ee9e918b9c5', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 13, 13, 'ሐናንያ ግን መልሶ እንዲህ አለ፥ “አቤቱ፥ ስለዚህ ሰው በኢየሩሳሌም በቅዱሳኖችህ ላይ የሚያደርገውን ክፉ ነገር ሁሉ ከብዙ ሰዎች ሰምቻለሁ።'),
  ('d87a8d89-633e-5af8-a696-642d33f530f6', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 14, 14, 'ወደዚህም ከካህናቱ አለቃ አስፈቅዶ የመጣ ስምህን የሚጠሩትን ሁሉ ሊያስር ነው።”'),
  ('00cb9ba3-3e16-54e8-ad7d-3d44a1f0483b', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 15, 15, 'ጌታችንም እንዲህ አለው፥ “ተነሥና ሂድ፤ በአሕዛብና በነገሥታት፥ በእስራኤል ልጆችም ፊት ስሜን ይሸከም ዘንድ ለእኔ የተመረጠ ዕቃ አድርጌዋለሁና።'),
  ('5dac5025-b2c6-5246-ae5e-ad19e42dbba5', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 16, 16, 'እኔም ስለ ስሜ መከራን ይቀበል ዘንድ እንዳለው አሳየዋለሁ።”'),
  ('5ff51536-1686-5969-a7d1-c6b3ba2e05fe', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 17, 17, 'ያንጊዜም ሐናንያ ሄደ፤ ወደ ቤትም ገባ፤ እጁንም ጫነበትና፥ “ወንድሜ ሳውል፥ በመንገድ ስትመጣ የታየህ ጌታችን ኢየሱስ ክርስቶስ ታይና መንፈስ ቅዱስ ይመላብህ ዘንድ ወደ አንተ ልኮኛል” አለው።'),
  ('57291f6c-b034-5e4d-a585-c537a3eab758', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 18, 18, 'ያንጊዜም ፈጥኖ እንደ ቅርፊት ያለ ነገር ከዐይኖቹ ላይ ተገፎ ወደቀ፤ ዐይኖቹም ተገለጡ፤ ወዲያውም አየ፤ ተነሥቶም ተጠመቀ።'),
  ('08209d3e-2bca-508c-ad0c-b451f2e3afd6', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 19, 19, 'እህልም በላ፤ በረታም፤ ጥቂት ቀንም ከደቀ መዛሙርት ጋር በደማስቆ ሰነበተ።'),
  ('14c09650-d563-5d82-a296-e10b4c18fdee', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 20, 20, 'ወዲያውኑም “የእግዚአብሔር ልጅ ነው” ብሎ ስለ ኢየሱስ ክርስቶስ በየምኵራቦቹ ሰበከ፥ አስተማረም።'),
  ('008d0c32-28df-56fc-a98c-957d6a019523', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 21, 21, 'የሰሙትም ሁሉ አደነቁ፤ እንዲህም አሉ፥ “በኢየሩሳሌም ይህን ስም የሚጠሩትን ሁሉ ይጠላቸው የነበረው ይህ አይደለምን? ስለዚህ ወደዚህ የመጣው እያሰረ ወደ ሊቀ ካህናቱ ሊወስዳቸው አይደለምን?”'),
  ('d5e9a78e-7a49-506c-aed8-076bc0d5fe2e', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 22, 22, 'ሳውል ግን እየበረታ ሔደ፤ በደማስቆም ለነበሩት አይሁድ ይህ ክርስቶስ እንደ ሆነ እያስረዳ መልስ አሳጣቸው።'),
  ('19c5eec8-ef77-522a-a1b2-c377995c9d44', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 23, 23, 'ከብዙ ቀንም በኋላ አይሁድ ሳውልን ይገድሉት ዘንድ ተማከሩ።'),
  ('fb2a7c2d-5715-5bf0-a507-6c3c72cd3dea', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 24, 24, 'ሳውል ግን በእርሱ ላይ ሊያደርጉት የሚሹትን ዐወቀባቸው፤ ሊገድሉትም በቀንና በሌሊት የከተማውን በር ይጠብቁ ነበር።'),
  ('685a7ceb-e745-5dae-a707-7db6f619b83c', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 25, 25, 'ደቀ መዛሙርትም በሌሊት ወሰዱት፤ በቅርጫትም አድርገው በቅጽሩ ድምድማት ላይ አወረዱት።'),
  ('28ec48b0-161a-50fc-ae8e-a4b4932ad9d0', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 26, 26, 'ሳውልም ወደ ኢየሩሳሌም በደረሰ ጊዜ ሊገናኛቸው ደቀ መዛሙርትን ፈለጋቸው። ሁሉም ፈሩት፤ የጌታችን ደቀ መዝሙር እንደ ሆነ አላመኑትም ነበርና።'),
  ('d617873d-35a0-5dbe-a1c5-b955164399e4', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 27, 27, 'በርናባስም አግኝቶ ወደ ሐዋርያት ወሰደው፤ ጌታችንም በመንገድ እንደ ተገለጠለትና እንደ አነጋገረው፥ በደማስቆም በኢየሱስ ስም እንደ አስተማረ ነገራቸው።'),
  ('ae1a5342-4c9d-5b34-a843-576185a6faae', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 28, 28, 'በኢየሩሳሌምም አብሮአቸው ይገባና ይወጣ ነበረ፤ በጌታችን በኢየሱስ ስምም በግልጥ ያስተምር ነበር።'),
  ('4481d6db-c27c-50f3-ac21-41c4df0871fa', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 29, 29, 'ከግሪክ ሀገር መጥተው የነበሩትንም አይሁድ ይከራከራቸው ነበር፤ እነርሱም ደግሞ ሊገድሉት ፈለጉ።'),
  ('40603ddd-e722-5b84-a1ca-1654e34ad3fb', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 30, 30, 'ወንድሞችም ይህን ባወቁ ጊዜ ወደ ቂሳርያ አወረዱት፤ ከዚያም ወደ ጠርሴስ ላኩት።'),
  ('663176d3-861f-5550-a650-fbf1d11300d2', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'bb56d8a7-fffb-5484-aa35-e6ec1033fec8', 31, 31, 'በይሁዳ፥ በሰማርያና በገሊላ ያሉ አብያተ ክርስቲያናት ሁሉ በሰላም ኖሩ፤ ታነጹም፤ እግዚአብሔርንም በመፍራት ጸንተው ኖሩ፤ ሕዝቡም በመንፈስ ቅዱስ አጽናኝነት በዙ።'),
  ('9b3a2c58-ee97-5405-a9a7-dca7ccf32bb1', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'aa6937bb-f932-5ca1-ad7e-14a3b43f933d', 1, 32, 'ከዚህም በኋላ ጴጥሮስ በየቦታዉ ሲዘዋወር በልዳ ወደሚኖሩት ቅዱሳን ዘንድ ደረሰ።'),
  ('22f279ea-9b91-507f-ae4f-a74e6f04054d', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'aa6937bb-f932-5ca1-ad7e-14a3b43f933d', 2, 33, 'በዚያም ኤንያ የተሰኘ ሰውን አገኘ፤ እርሱም ታሞ በአልጋ ከተኛ ስምንት ዓመት ሆኖት ነበረ፤ ሽባ ነበርና።'),
  ('40c0d690-964d-523c-a1c3-557aba853c4a', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'aa6937bb-f932-5ca1-ad7e-14a3b43f933d', 3, 34, 'ጴጥሮስም፥ “ኤንያ ሆይ፥ ኢየሱስ ክርስቶስ ይፈውስህ፤ ተነሥና አልጋህን አንጥፍ” አለው፤ ያንጊዜም ተነሣ።'),
  ('c242d0b1-3e2a-5d7b-a0a0-efeb57ef5439', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'aa6937bb-f932-5ca1-ad7e-14a3b43f933d', 4, 35, 'በልዳና በሳሮና የሚኖሩም ሁሉ እርሱን አይተው ወደ ጌታችን ተመለሱ።'),
  ('9c7eab15-cb50-5575-aed9-3fb6368f03bd', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 1, 36, 'በኢዮጴ ሀገርም ጣቢታ የምትባል አንዲት ደቀ መዝሙር ነበረች፤ በትርጓሜውም ዶርቃስ ይሉአታል፤ ፌቆ ማለት ነው፤ እርስዋም ብዙ ደጋግ ሥራ ትሠራ ነበር፤ ምጽዋትም ትሰጥ ነበር።'),
  ('c33dbfa0-10af-5a15-a17b-8ef68790f862', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 2, 37, 'ያንጊዜም ታማ ሞተችና በድንዋን አጥበው በሰገነት አስተኙአት።'),
  ('3c10c5f6-b15c-5712-a735-ee02dc94aae8', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 3, 38, 'ልዳም ለኢዮጴ ቅርብ ነበርና ደቀ መዛሙርት ጴጥሮስ በዚያ እንዳለ ሰምተው ወደ እነርሱ መምጣት እንዳይዘገይ ይማልዱት ዘንድ ሁለት ሰዎችን ወደ እርሱ ላኩ።'),
  ('ad5c634c-a94d-56a0-a16e-368a517f1d2b', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 4, 39, 'ጴጥሮስም ተነሥቶ አብሮአቸው ሄደ፤ በደረሰም ጊዜ ወደ ሰገነት አወጡት፤ ባልቴቶችም ሁሉ ወደ እርሱ መጥተው በፊቱ ቆሙ፤ ያለቅሱላትም ነበር፤ ዶርቃስም በሕይወት ሳለች የሠራችውን ቀሚሱንና መጐናጸፊያውን አሳዩት።'),
  ('26b172ab-f0a2-5064-a075-b8493545f2a8', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 5, 40, 'ጴጥሮስም ሁሉን ካስወጣ በኋላ ተንበርክኮ ጸለየ፤ ወደ በድንዋም መለስ ብሎ፥ “ጣቢታ ሆይ፥ ተነሽ” አላት፤ እርስዋም ዐይኖችዋን ገለጠች፤ ያንጊዜም ጴጥሮስን አየችው፤ ቀና ብላም ተቀመጠች።'),
  ('356c703d-b18c-5a3d-a3b8-c989ca74329b', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 6, 41, 'እጁንም ለእርስዋ ሰጥቶ አስነሣት፤ ቅዱሳንንና ባልቴቶችንም ጠርቶ እርስዋን አድኖ ሰጣቸው።'),
  ('d8e7ed65-a59f-54b4-a7e5-17ec0ca5a9c5', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 7, 42, 'በኢዮጴም ያሉ ሁሉ ይህን ሰሙ፤ ብዙዎችም በጌታችን አመኑ።'),
  ('2f22e1c1-fdb2-519b-af97-f7b362c387f3', '788c56eb-6e21-50f4-aa94-1208d924e3c9', 'd5dfb44d-3874-545f-af20-5d7806750f29', 8, 43, 'ጴጥሮስም በኢዮጴ በቍርበት ፋቂው በስምዖን ቤት ብዙ ቀን ተቀመጠ።'),
  ('9df0342b-de24-5493-a346-5ce34593c24e', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 1, 1, 'በቂሳርያም ቆርኔሌዎስ የሚባል አንድ ሰው ነበረ፤ ኢጣሊቄ ለሚሉት ጭፍራም የመቶ አለቃ ነበር።'),
  ('0f3ecbfb-a3d7-5061-a116-a38e79387dcb', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 2, 2, 'እርሱም ጻድቅና ከነቤተ ሰቡ እግዚአብሔርን የሚፈራ ነበር፤ ለሕዝቡም ብዙ ምጽዋት ይሰጥ ነበር፤ ዘወትርም ወደ እግዚአብሔር ይጸልይ ነበር።'),
  ('24f2743b-8261-508b-a63c-58d598bf215c', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 3, 3, 'የእግዚአብሔር መልአክም በራእይ ከቀኑ በዘጠኝ ሰዓት በግልጥ ታየው፤ ወደ እርሱም ገብቶ፥ “ቆርኔሌዎስ ሆይ፥” አለው።'),
  ('8019ea51-e5b3-5028-af12-295acd78e862', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 4, 4, 'ወደእርሱም ተመልክቶ ፈራና፥ “አቤቱ፥ ምንድን ነው?” አለ፤ መልአኩም እንዲህ አለው፥ “ጸሎትህም ምጽዋትህም መልካም መታሰቢያ ሆኖ ወደ እግዚአብሔር ዐርጎአል።'),
  ('c97532c9-5243-5cd2-a15c-5dfa199aea05', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 5, 5, 'አሁንም ጴጥሮስ የሚባለውን ስምዖንን ይጠሩልህ ዘንድ ወደ ኢዮጴ ከተማ ሰዎችን ላክ።'),
  ('144f049c-8fad-5bf1-af55-72648a0fe8b6', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 6, 6, 'እርሱም ቤቱ በባሕር አጠገብ ባለው በቍርበት ፋቂው በስምዖን ቤት እንግድነት ተቀምጦአል። ልታደርገው የሚገባህን እርሱ ይነግርሃል።”'),
  ('cc2e7b99-9f72-5b34-af9b-6cc57e7386e9', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 7, 7, 'ያነጋገረውም መልአክ ከሄደ በኋላ ከሎሌዎቹ ሁለት፥ ከማይለዩት ጭፍሮቹም አንድ ደግ ወታደር ጠራ።'),
  ('ac55c453-16df-5836-ac42-ff01f1c57d65', '964aeee8-6384-5d91-a5d6-977deb8666d7', 'e0faae0b-7278-5133-a460-31a56fdb2e16', 8, 8, 'ነገሩንም ሁሉ ነግሮ ወደ ኢዮጴ ከተማ ላካቸው።'),
  ('adca9b32-53de-5c0f-ad78-3fa5d565a3cb', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 1, 9, 'በማግሥቱም ሄደው ወደ ከተማዪቱ በር ደረሱ፤ ጴጥሮስም በቀትር ጊዜ ሊጸልይ ወደ ሰገነት ወጥቶ ነበር።'),
  ('87c40c63-6145-5826-a744-f2b919066153', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 2, 10, 'በተራበ ጊዜም ምሳ ሊበላ ወደደ፤ እነርሱም እያዘጋጁ ሳሉ ተመስጦ መጣበት።'),
  ('b799e6dc-4e33-5410-a2a9-4e5fda079de4', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 3, 11, 'ሰማይም ተከፍቶ በአራቱ ማዕዘን የተያዘ እንደ ታላቅ መጋረጃ ያለ ዕቃ ወደ ምድር ሲወርድ አየ።'),
  ('dcc41082-2d8a-5e9d-a2b3-f65bbbbaa850', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 4, 12, 'በውስጡም አራት እግር ያለው እንስሳ ሁሉ፥ አራዊትም፥ የሚንቀሳቀስም፥ የሰማይም ወፎች ነበሩበት።'),
  ('83eed5d5-36c8-5244-acd2-85ed85498288', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 5, 13, '“ጴጥሮስ ሆይ፥ ተነሥና አርደህ ብላ” የሚል ቃል ወደ እርሱ መጣ።'),
  ('44b113bf-41cd-518d-addd-abdf0e23b801', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 6, 14, 'ጴጥሮስ ግን፥ “አቤቱ፥ ከቶ አይሆንም፤ ርኩስ፥ የሚያጸይፍም ከቶ በልች አላውቅም” አለው።'),
  ('9864ad09-6316-5d03-a625-fae0758dd59a', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 7, 15, 'ዳግመኛም፥ “እግዚአብሔር ንጹሕ ያደረገውን አንተ አታርክስ” የሚል ቃል ወደ እርሱ መጣ።'),
  ('753bdcb8-71ec-50d0-af13-e83ca2a2b2af', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 8, 16, 'ይህንም ሦስት ጊዜ አለው፤ ወዲያውኑም ዕቃዉ ወደ ሰማይ ተመለሰ።'),
  ('54259867-a0b1-5069-a89b-7cafaf2102f4', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 9, 17, 'ጴጥሮስም ስለ አየው ራእይ ምን እንደ ሆነ ሲያወጣና ሲያወርድ ከቆርኔሌዎስ ተልከው የመጡ ሰዎች የስምዖንን ቤት እየጠየቁ በደጅ ቁመው ነበር።'),
  ('fe5a6bc3-6efa-5f52-aacb-514420bb9f33', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 10, 18, 'ተጣርተውም፦ ጴጥሮስ የተባለ ስምዖን በእንግድነት በዚያ ይኖር እንደ ሆነ ጠየቁ።'),
  ('6cb2fa4c-0a76-5190-a1ce-99eaea257644', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 11, 19, 'ጴጥሮስም ስለ ታየው ራእይ ሲያወጣ ሲያወርድ መንፈስ ቅዱስ እንዲህ አለው፥ “እነሆ፥ ሦስት ሰዎች ይፈልጉሃል።'),
  ('d6d3d263-b93a-5e9f-a716-bfc789150e3b', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 12, 20, 'ተነሥና ውረድ፤ ምንም ሳትጠራጠር ከእነርሱ ጋር ሂድ፤ እኔ ልኬአቸዋለሁና።”'),
  ('d3964822-a68a-5382-a95d-9b06ddf0e35e', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 13, 21, 'ጴጥሮስም ወደ እነዚያ ሰዎች ወረደና፥ “እነሆ፥ የምትፈልጉኝ እኔ ነኝ፤ ለምን መጥታችኋል?” አላቸው።'),
  ('073142a0-0a07-5422-a965-b772b050b288', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 14, 22, 'እነርሱም፥ “የመቶ አለቃ ቆርኔሌዎስ እግዚአብሔርን የሚፈራ ጻድቅ ሰው ነው፤ በአይሁድም ወገኖች ሁሉ የተመሰከረለት ነው፤ ቅዱስ መልአክ ተገልጦ አንተን ወደ ቤቱ እንዲጠራህ የምታስተምረውንም እንዲሰማ አዝዞታል፤” አሉት።'),
  ('fb329ae9-8cbb-5b06-a3fe-09ac2e4e1ae4', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 15, 23, 'እርሱም ተቀብሎ አሳደራቸው፤ በማግሥቱም ተነሥቶ አብሮአቸው ሄደ፤ በኢዮጴ ከተማ ከሚኖሩት ወንድሞችም አብረውት የሄዱ ነበሩ።'),
  ('e48c7bf3-e34c-56aa-acd0-c25197995f73', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 16, 24, 'በማግሥቱም ወደ ቂሳርያ ከተማ ገባ፤ ቆርኔሌዎስም ዘመዶቹንና የቅርብ ወዳጆቹን ጠርቶ ይጠብቃቸው ነበር።'),
  ('b564b10c-08e3-5f2c-af35-348df4902ee5', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 17, 25, 'ጴጥሮስም በገባ ጊዜ ቆርኔሌዎስ ተቀበለው፤ ከእግሩ በታችም ወድቆ ሰገደለት።'),
  ('1ed7e06b-7b6c-58fb-a134-839a8f378494', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 18, 26, 'ጴጥሮስም፥ “ተነሥ እኔም እንደ አንተው ሰው ነኝ” ብሎ አነሣው።'),
  ('c6016b54-170a-50ad-a49f-f16dd354735c', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 19, 27, 'ከእርሱም ጋር እየተነጋገረ ገባ፤ ወደ እርሱም የመጡ ብዙ ሰዎችን አገኘ።'),
  ('25af3c19-2d4e-5bb9-a545-629e3b2672ba', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 20, 28, 'ጴጥሮስም እንዲህ አላቸው፥ “ለአይሁዳዊ ሰው ሄዶ ከባዕድ ወገን ጋር መቀላቀል እንደማይገባው ታውቃላችሁ፤ ለእኔ ግን ከሰው ማንንም ቢሆን እንዳልጸየፍና ርኩስ ነው እንዳልል እግዚአብሔር አሳየኝ።'),
  ('6d94c8f8-f221-5e64-ac4d-3221814704d2', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 21, 29, 'አሁንም ስለ ላካችሁብኝ ሳልጠራጠር ወደ እናንተ መጣሁ፤ በምን ምክንያት እንደ ጠራችሁኝ እጠይቃችኋለሁ።”'),
  ('1dd0a6c7-b37e-5f09-af17-95ba8c75b14c', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 22, 30, 'ቆርኔሌዎስም እንዲህ አለው፥ “የዛሬ አራት ቀን በዘጠኝ ሰዓት በዚች ሰዓት በቤቴ ስጸልይ የሚያንፀባርቅ ልብስ የለበሰ አንድ ሰው በፊቴ ቆሞ ታየኝ።'),
  ('a1cb7698-2040-59d8-af37-fc1cfa787aad', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 23, 31, 'እንዲህም አለኝ፦ ቆርኔሌዎስ ሆይ፥ በእግዚአብሔር ፊት ጸሎትህ ተሰማ፤ ምጽዋትህም ታሰበልህ።'),
  ('8cd29842-aaab-519b-aa81-40725703ece0', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 24, 32, 'አሁንም ወደ ኢዮጴ ከተማ ላክና በባሕር አቅራቢያ ባለችው በቍርበት ፋቂው በስምዖን ቤት የሚኖረውን ጴጥሮስ የተባለውን ስምዖንን ይጥሩልህ፤ እርሱ መጥቶ የምትድንበትን ይነግርሃል።'),
  ('9d780845-09c9-578a-ad9e-a8ab91169154', '964aeee8-6384-5d91-a5d6-977deb8666d7', '4c684c66-cc09-5a65-a6a6-f5bc1b34a5c0', 25, 33, 'ስለዚህም ወዲያውኑ ወደ አንተ ላክሁ፤ ወደ እኛ በመምጣትህም መልካም አደረግህ፤ አሁንም እግዚአብሔር ያዘዘህን ሁሉ ልንሰማ እነሆ፥ እኛ ሁላችን በእግዚአብሔር ፊት በዚህ አለን።”'),
  ('e6a88928-73af-506a-a970-75fb77bd047a', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 1, 34, 'ጴጥሮስም አፉን ከፈተና እንዲህ አለ፥ “እግዚአብሔር ለሰው ፊት እንደማያዳላ በእውነት አየሁ።'),
  ('c432337d-e0a3-5566-ac8f-5efd6f2eab30', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 2, 35, 'ነገር ግን በሕዝብ ሁሉ ዘንድ እርሱን የሚፈራና እውነትን የሚያደርግ በእርሱ ዘንድ የተወደደ ነው።'),
  ('5f5f2fbf-48d7-5e5d-a886-d58d10e42206', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 3, 36, 'ቃሉን ለእስራኤል ልጆች ላከ፤ በኢየሱስ ክርስቶስም ሰላምን ነገራቸው፤ እርሱም የሁሉ ገዢ ነው።'),
  ('2dc0115f-f721-53a4-a3db-08909768a4e3', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 4, 37, 'ዮሐንስ ከሰበከው ጥምቀት በኋላ ከገሊላ ጀምሮ በይሁዳ የሆነውን ነገር ሁሉ እናንተ ራሳችሁ ታውቃላችሁ።'),
  ('f0889294-4820-5535-aefb-183bf69f9ea9', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 5, 38, 'ስለ ናዝሬቱ ስለ ኢየሱስ እግዚአብሔር በመንፈስ ቅዱስ በኀይልም እንደ ቀባው፥ እየዞረም መልካም እንደ አደረገ፥ ሰይጣን ያሸነፋቸውንም እንደ ፈወሰ ታውቃላችሁ። እግዚአብሔር ከእርሱ ጋር ነበርና።'),
  ('fff747b1-e15c-5f69-a7ff-ac3739a1d491', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 6, 39, 'በይሁዳና በኢየሩሳሌም ባደረገውም ሁሉ እኛ ምስክሮች ነን፤ እርሱንም በዕንጨት ላይ ሰቅለው ገደሉት።'),
  ('ec18678a-08dd-5a5e-a7ab-d1a6e403f845', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 7, 40, 'እግዚአብሔር ግን በሦስተኛው ቀን ከሙታን ለይቶ አስነሣው፤ በግልጥ እንዲታይም አደረገው።'),
  ('eac2a985-346d-5c57-aea1-5ba18c2fb1cc', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 8, 41, 'ይኸውም ለሕዝቡ ሁሉ አይደለም፤ ነገር ግን አስቀድሞ ለመረጣቸውና ምስክሮች ለሚሆኑት ብቻ ነው እንጂ፤ የመረጣቸው የተባልንም እኛ ነን፤ ከሙታንም ተለይቶ ከተነሣ በኋላ ከእርሱ ጋር የበላን የጠጣንም እኛ ነን።'),
  ('103c031d-0caf-57f9-a36f-eaefb1545a64', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 9, 42, 'በእግዚአብሔር ዘንድ በሕያዋንና በሙታን ላይ ፈራጅ ሆኖ የተሾመ እርሱ እንደ ሆነ ለሕዝብ እናስተምር ዘንድ አዘዘን።'),
  ('9753815d-26fa-55ee-ae42-fb4e745f5887', '964aeee8-6384-5d91-a5d6-977deb8666d7', '11c06b73-987d-54d8-afbd-dcbf388f0cd2', 10, 43, 'ለሚያምኑበትም ሁሉ ኀጢአታቸው በስሙ እንደሚሰረይላቸው ነቢያት ሁሉ ምስክሮቹ ናቸው።”'),
  ('fbbd15b0-4cd4-55ad-a860-615c1eeec965', '964aeee8-6384-5d91-a5d6-977deb8666d7', '6ac4b3ad-afe8-5c9e-a0ab-09323554235a', 1, 44, 'ጴጥሮስም ይህን ነገር ሲነግራቸው ይህን ትምህርት በሰሙት ሰዎች ሁሉ ላይ መንፈስ ቅዱስ ወረደ።'),
  ('26d45972-4581-5f2d-aa6c-3dde43e48c75', '964aeee8-6384-5d91-a5d6-977deb8666d7', '6ac4b3ad-afe8-5c9e-a0ab-09323554235a', 2, 45, 'ከጴጥሮስ ጋር የመጡ ከአይሁድ ወገን የሆኑ ምእመናን ሁሉ ደነገጡ፤ የመንፈስ ቅዱስ ጸጋ በአሕዝብ ላይ ወርዶአልና።'),
  ('7077531f-f8ea-51aa-a09b-aafc13068c68', '964aeee8-6384-5d91-a5d6-977deb8666d7', '6ac4b3ad-afe8-5c9e-a0ab-09323554235a', 3, 46, 'በልዩ ልዩ ሀገር ቋንቋ ሲናገሩ፥ እግዚአብሔርንም ሲያመሰግኑ ሰምተዋቸዋልና።'),
  ('00f7e8d7-1112-554e-ac4a-837f7203a2f4', '964aeee8-6384-5d91-a5d6-977deb8666d7', '6ac4b3ad-afe8-5c9e-a0ab-09323554235a', 4, 47, 'ጴጥሮስም፥ “እንደ እኛ መንፈስ ቅዱስን ከተቀበሉ በኋላ እንግዲህ በውኃ እንዳይጠመቁ ውኃን ሊከለክላቸው የሚችል ማነው?” አለ።'),
  ('6c5f3b5a-63d8-5375-aaff-25a0fa9e9858', '964aeee8-6384-5d91-a5d6-977deb8666d7', '6ac4b3ad-afe8-5c9e-a0ab-09323554235a', 5, 48, 'በኢየሱስ ክርስቶስም ስም እንዲጠመቁ አዘዛቸው። ከዚህም በኋላ ጥቂት ቀን አብሮአቸው እንዲቀመጥ ጴጥሮስን ማለዱት።'),
  ('95f6d4fd-432d-5440-a685-8272a3c5631b', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 1, 1, 'ሐዋርያትና በይሁዳ የነበሩ ወንድሞችም አሕዛብ የእግዚአብሔርን ቃል እንደ ተቀበሉ ሰሙ።'),
  ('f399c653-ff54-5ade-a6e3-f9c63b7c8052', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 2, 2, 'ጴጥሮስም ወደ ኢየሩሳሌም በወጣ ጊዜ ከአይሁድ ወገን የሆኑት ወንድሞች ተቃወሙት።'),
  ('f2b87eca-2292-5744-a4b5-69ff2f69cc7c', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 3, 3, '“ወደ አልተገረዙት ሰዎች ቤት ገብተህ አብረሃቸው በልተሃል” አሉት።'),
  ('6a83e7f4-e373-5517-ae13-09e23783b52d', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 4, 4, 'ጴጥሮስም ከመጀመሪያ ጀምሮ ይነግራቸው ጀመረ፤ እንዲህም አላቸው።'),
  ('51852c78-4ca1-54b5-aacf-5da8d84e9589', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 5, 5, '“በኢዮጴ ከተማ ሳለሁ ስጸልይ ተመስጦ መጣብኝና ራእይ አየሁ፤ ታላቅ መጋረጃ የመሰለ ዕቃ በአራቱ ማዕዘን ተይዞ ከሰማይ ወረደ፤ ወደ እኔም መጣ።'),
  ('2019481e-59a7-5942-adb3-b8b583cd65b7', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 6, 6, 'በውስጡም አራት እግር ያላቸው እንስሳንና አራዊትን፥ ተንቀሳቃሾችንም፥ የሰማይ ወፎችንም አየሁ።'),
  ('313e79c3-69eb-5085-ae26-eca412018723', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 7, 7, '‘ጴጥሮስ ሆይ፥ ተነሥና አርደህ ብላ’ የሚለኝንም ቃል ሰማሁ።'),
  ('8999b598-d1ce-5454-a689-44ca3fb4cd2f', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 8, 8, '‘አቤቱ፥ ከቶ አይሆንም፤ ንጹሕ ያልሆነ ርኩስ ነገር ወደ አፌ ገብቶ አያውቅም’ አልሁ።'),
  ('1ec696ff-48d0-5fe3-a78b-15000f5da27a', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 9, 9, 'ደግሞም፦ ‘እግዚአብሔር ንጹሕ ያደረገውን አንተ አታርክሰው’ የሚል ቃል ከሰማይ መለሰልኝ።'),
  ('3bd67b0d-1337-550d-ab69-59ca669ce88a', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 10, 10, 'እንዲህም መላልሶ ሦስት ጊዜ ነገረኝ፤ ዳግመኛም ሁሉ ተጠቅልሎ ወደ ሰማይ ተመለሰ።'),
  ('8f2e1367-2002-5367-ac35-6c4c9b2da74d', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 11, 11, 'በዚያችም ሰዓት ከቂሳርያ ወደ እኔ የተላኩ ሦስት ሰዎች መጡ፤ እኔ ባለሁበት ግቢ በርም ቆሙ።'),
  ('7a2df762-13e1-546b-a013-3abd0072deef', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 12, 12, 'መንፈስ ቅዱስም፦ ‘ሳትጠራጠር አብረሃቸው ሂድ’ አለኝ፤ እነዚህ ስድስቱ ወንድሞቻችንም ተከትለውኝ መጡና ወደዚያ ሰው ቤት ገባን።'),
  ('4a30a556-d691-540c-a8f5-6880a6c547d1', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 13, 13, 'እርሱም በቤቱ ቆሞ ሳለ የእግዚአብሔርን መልአክ እንዳየ ‘ወደ ኢዮጴ ከተማ ልከህ ጴጥሮስ የተባለውን ስምዖንን ይጥሩልህ።'),
  ('0116505b-95c5-5901-aa3f-4005ae7b576b', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 14, 14, 'አንተና ቤተ ሰቦችህ ሁሉ የምትድኑበትን ነገር እርሱ ይነግርሃል’ እንደ አለው ነገረን።'),
  ('adb81c61-3a37-5b59-a757-2f44d290a7d0', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 15, 15, 'ላስተምራቸው በጀመርሁ ጊዜም ቀድሞ በእኛ ላይ እንደ ወረደ ሁሉ መንፈስ ቅዱስ በእነርሱም ላይ ወረደ።'),
  ('5cd61dd7-7aa8-51db-abef-769dbf4c4de5', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 16, 16, '‘ዮሐንስ በውኃ አጠመቀ፤ እናንተ ግን፤ በመንፈስ ቅዱስ ትጠመቃላችሁ’ ያለውን የጌታችንን ቃል ዐሰብሁ።'),
  ('cb85bcf1-179a-56ba-a23b-b9d5bf107aaa', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 17, 17, 'እንግዲህ እግዚአብሔር በጌታችን በኢየሱስ ክርስቶስ ለአመንነው ለእኛ እንደ ሰጠን፥ ያን ጸጋውን እንደ እኛ አስተካክሎ ከሰጣቸው እግዚአብሔርን ልከለክል የምችል እኔ ማነኝ?”'),
  ('38652cfe-c776-5ff0-a1d5-0751a10d3787', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '24555d0b-c190-5de1-a4cb-53c1d13ab5db', 18, 18, 'ይህንም በሰሙ ጊዜ ዝም አሉ፥ “እግዚአብሔር ለአሕዛብ ደግሞ ለሕይወት የሚሆን ንስሓን ሰጣቸው እንጃ” እያሉ እግዚአብሔርን አመሰገኑ።'),
  ('d55e1bf3-116f-57ff-a0e5-4178e83d7a62', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '4c8840f1-47d1-50f3-ad11-50b87e155062', 1, 19, 'በእስጢፋኖስ ሞት ምክንያት የተበተኑት ግን፤ ወደ ፊንቄ ወደ ቆጵሮስና ወደ አንጾኪያ ደረሱ፤ ቃሉንም ለአይሁድ ብቻ እንጂ ለአንድስ እንኳ አይናገሩም ነበር።'),
  ('bb9fa54a-daa0-57ea-ab7d-a88f8e577246', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '4c8840f1-47d1-50f3-ad11-50b87e155062', 2, 20, 'ከመካከላቸውም ወደ አንጾኪያ ሄደው ለአረማውያን የጌታችን የኢየሱስ ክርስቶስን ነገር ያስተማሩ የቆጵሮስና የቄሬና ሰዎች ነበሩ።'),
  ('2980906d-c99c-5d71-a07a-d2b172830d7b', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '4c8840f1-47d1-50f3-ad11-50b87e155062', 3, 21, 'የእግዚአብሔርም እጅ ከእነርሱ ጋር ነበረ፤ ወደ ጌታም ተመልሰው ያመኑ ሰዎች ቍጥራቸው በዛ።'),
  ('8d684c34-b661-5f40-a498-3b38fcf9f70e', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '4c8840f1-47d1-50f3-ad11-50b87e155062', 4, 22, 'ስለ እነርሱ የተነገረውም ይህ ነገር በኢየሩሳሌም ባለችው ቤተ ክርስቲያን ዘንድ ተሰማ፤ በርናባስንም ወደ አንጾኪያ ላኩት።'),
  ('d56c1771-a422-525d-a63b-d31003df8a18', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '4c8840f1-47d1-50f3-ad11-50b87e155062', 5, 23, 'በደረሰ ጊዜም የእግዚአብሔርን ጸጋ አየና ደስ አለው፤ በፍጹም ልባቸውም በእግዚአብሔር ጸንተው ይኖሩ ዘንድ መከራቸው።'),
  ('31c88729-9f2f-5b64-aa9c-69876fcbfa2e', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '4c8840f1-47d1-50f3-ad11-50b87e155062', 6, 24, 'ደግ ሰው፥ መንፈስ ቅዱስ ያደረበት፥ ሃይማኖተኛም ነበርና፤ በጌታችንም አምነው ብዙዎች አሕዛብ ተጨመሩ።'),
  ('ef19e0aa-28de-5278-aa09-b88b7805ccc2', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '936e03bb-4146-5b56-a3ac-f490e191e1e9', 1, 25, 'ከዚህም በኋላ በርናባስ ሳውልን ሊፈልግ ወደ ጠርሴስ ሄደ፤ በአገኘውም ጊዜ ወደ አንጾኪያ ወሰደው።'),
  ('5cdba15b-303b-504a-a7e4-228ea5b6b2f4', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '936e03bb-4146-5b56-a3ac-f490e191e1e9', 2, 26, 'በቤተ ክርስቲያንም አንድ ዓመት አብረው ተቀመጡ፤ ብዙ ሕዝብንም አስተማሩ፤ ደቀ መዛሙርትም መጀመሪያ በአንጾኪያ ክርስቲያን ተብለው ተጠሩ።'),
  ('34c3ce80-cd81-550e-a732-8e2924de6597', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '936e03bb-4146-5b56-a3ac-f490e191e1e9', 3, 27, 'ያንጊዜም ነቢያት ከኢየሩሳሌም ወደ አንጾኪያ ወረዱ።'),
  ('faebbf75-5642-5510-a190-b03160d038e9', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '936e03bb-4146-5b56-a3ac-f490e191e1e9', 4, 28, 'ከመካከላቸውም አጋቦስ የተባለ አንድ ሰው ተነሥቶ በዓለም ሁሉ ጽኑ ረኃብ እንደሚመጣ በመንፈስ ቅዱስ ተገልጦለት ተናገረ፤ ይህም በቄሣር ቀላውዴዎስ ዘመን ሆነ።'),
  ('643ab170-f8b7-5c0c-a093-c1e6a3b62922', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '936e03bb-4146-5b56-a3ac-f490e191e1e9', 5, 29, 'ከዚህም በኋላ ደቀ መዛሙርት እያንዳንዳቸው የሚችሉትን ያህል አወጣጥተው በይሁዳ ሀገር ለሚኖሩት ወንድሞቻቸው ርዳታን ይልኩ ዘንድ ወሰኑ።'),
  ('b2974069-662d-5815-a672-a85e35004eba', '9fffb848-8fa6-527a-a73e-8b0ccc1ede92', '936e03bb-4146-5b56-a3ac-f490e191e1e9', 6, 30, 'እንደዚህም አድርገው በበርናባስና በሳውል እጅ ወደ ቀሳውስት ላኩት።'),
  ('92385278-5aa1-5bcf-a3d6-aae5694b121a', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '81c44b00-656b-5526-a344-08215db21001', 1, 1, 'በዚያም ወራት ሄሮድስ የቤተ ክርስቲያንን ሹሞች ያዛቸው፤ መከራም አጸናባቸው።'),
  ('a07e6d07-7e3c-57f5-a2cb-8be5bd3498ac', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '81c44b00-656b-5526-a344-08215db21001', 2, 2, 'የዮሐንስንም ወንድም ያዕቆብን በሰይፍ ገደለው።'),
  ('893700ff-2b2e-51e6-aa12-40863057f2ca', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '81c44b00-656b-5526-a344-08215db21001', 3, 3, 'አይሁድንም ደስ እንዳላቸው አይቶ ጴጥሮስን ደግሞ ያዘው፤ ያንጊዜም የፋሲካ በዓል ነበር።'),
  ('fde50849-3d81-550d-a2a1-17b9af77f9cb', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '81c44b00-656b-5526-a344-08215db21001', 4, 4, 'ይዞም ወኅኒ ቤት አስገባው፤ ለሚጠብቁት ለዐሥራ ስድስቱ ወታደሮችም አሳልፎ ሰጠው፤ ከፋሲካም በኋላ ወደ ሕዝብ ሊያቀርበው ወድዶ ነበር።'),
  ('acb69653-648f-55da-ae34-2f9b0738f5b3', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '81c44b00-656b-5526-a344-08215db21001', 5, 5, 'ጴጥሮስንም በወኅኒ ቤት ይጠብቁት ነበር፤ በቤተ ክርስቲያንም ዘወትር ስለ እርሱ ወደ እግዚአብሔር ይጸልዩ ነበር።'),
  ('d1849ed8-f30f-5e33-ad1f-92dce8735821', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 1, 6, 'ሄሮድስም ማለዳ ያቀርበው ዘንድ በወደደባት በዚያች ሌሊት ጴጥሮስ ሁለቱን እጆቹን በሰንሰለት ታስሮ በሁለት ወታደሮች መካከል ተኝቶ ነበር፤ ጠባቂዎችም የወኅኒ ቤቱን በር ይጠብቁ ነበር።'),
  ('e02b7158-9857-5b2a-a310-d94d7aa54b84', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 2, 7, 'የእግዚአብሔርም መልአክ ወርዶ በአጠገቡ ቆመ፤ በቤትም ውስጥ ብርሃን ሆነ፤ ጴጥሮስንም ጎኑን ነክቶ ቀሰቀሰውና፥ “ፈጥነህ ተነሥ” አለው፥ ሰንሰለቶቹም ከእጆቹ ወልቀው ወደቁ።'),
  ('fa79b8ef-a187-5ee0-a134-a8dae468e018', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 3, 8, 'መልአኩም፥ “ወገብህን ታጠቅ፥ ጫማህንም ተጫማ” አለው፤ እንደ አዘዘውም አደረገ፤ “ልብስህንም ልበስና ተከተለኝ” አለው።'),
  ('e1d71ce2-7f88-5545-a88a-7ffaa5fd09c7', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 4, 9, 'ተከትሎትም ወጣ፤ ጴጥሮስ ግን ራእይ የሚያይ ይመስለው ነበረ እንጂ በመልአኩ የሚደረገው ነገር እውነት እንደ ሆነ አላወቀም ነበር።'),
  ('bb541f37-dc3c-507a-a652-f8d806bfd8d1', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 5, 10, 'መጀመሪያውንና ሁለተኛውን ዘብ አልፈው ወደ ከተማ ወደምትወስደው ወደ ብረቱ መዝጊያ ደረሱ፤ ያንጊዜም መዝጊያው ራሱ ተከፈተላቸው፤ ወጥተውም በአንድ ስላች መንገድ ሄዱ፤ መልአኩም ጴጥሮስን ትቶት ሄደ።'),
  ('6276e9ca-a144-5b4f-a600-451ff5656a74', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 6, 11, 'ያንጊዜም የጴጥሮስ ልቡና ተመለሰለትና፥ “እግዚአብሔር መልአኩን ልኮ ከሄሮድስ እጅና የአይሁድ ሕዝብ ይጠብቁት ከነበረው ሁሉ እንደ አዳነኝ በእውነት አሁን ዐወቅሁ” አለ።'),
  ('925ee1bb-5a02-51b2-ac26-b787a4ded696', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 7, 12, 'ከዚህም በኋላ በአስተዋለ ጊዜ ብዙዎች ወንድሞች ተሰብስበው ይጸልዩበት ወደ ነበረው ማርቆስ ወደተባለው ወደ ዮሐንስ እናት ወደ ማርያም ቤት ሄደ።'),
  ('1d00023a-9c68-5a6e-a631-27b3221367fd', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 8, 13, 'ጴጥሮስም በሩን አንኳኳ፤ ሮዴ የምትባል ብላቴናም ልትከፍትለት መጣች።'),
  ('70b7c1ca-529b-5f55-a588-1ab319a586b2', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 9, 14, 'የጴጥሮስም ድምፅ መሆኑን ዐውቃ ከደስታ የተነሣ አልከፈተችለትም፤ ነገር ግን ጴጥሮስ በበር ቆሞ ሳለ ሮጣ ነገረቻቸው።'),
  ('40a6a9d8-3efd-5d77-aafd-5cf9d8a01f89', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 10, 15, 'እነርሱም “አብደሻልን? አንድ ጊዜ ታገሺ” አሉአት፤ እርስዋ ግን እርሱ እንደ ሆነ ታረጋግጥ ነበር። እነርሱም፥ “ምናልባት መልአኩ ይሆናል” አሉ።'),
  ('13af50f1-45a0-5e8a-aae4-e3b2b3e9affc', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 11, 16, 'ጴጥሮስ ግን በሩን ማንኳኳቱን ቀጠለ፤ ከፍተውም ባዩት ጊዜ ተደነቁ።'),
  ('4c106a1f-5c65-5bc0-a44e-c831dfb6fc87', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 12, 17, 'እርሱ ግን ዝም እንዲሉ በእጁ አመለከታቸው፤ ከወኅኒ ቤትም እግዚአብሔር እንደ አወጣው ነገራቸው፤ “ይህንም ለያዕቆብና ለወንድሞች ሁሉ ንገሩ” አላቸው፤ ከዚያም ወጥቶ ወደ ሌላ ስፍራ ሄደ።'),
  ('0f148cae-8111-54c4-ad70-6ddb30d7b259', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 13, 18, 'በነጋ ጊዜም ወታደሮች፥ “ጴጥሮስ ምን ሆነ?” ብለው ታወኩ።'),
  ('2dc2f6f0-8d96-5c5e-aae8-37e70e7ff884', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '851c9b72-4ce0-5e12-ad5d-989c34ad93dc', 14, 19, 'ሄሮድስ ግን አስፈልጎ ባጣው ጊዜ ጠባቂዎችን መረመረ፤ ይገድሉአቸውም ዘንድ አዘዘ፤ ከዚህም በኋላ ከይሁዳ ወደ ቂሳርያ ወርዶ በዚያ ተቀመጠ።'),
  ('62a7288f-fa57-536a-a212-c618c8cc7b9b', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '304b977f-280e-538d-af5f-d176b805a774', 1, 20, 'ሄሮድስም በጢሮስና በሲዶና ሰዎች ተቈጥቶ ነበር፤ በአንድነትም ወደ እርሱ መጥተው የንጉሡን ቢትወደድ በላስጦስን እንዲያስታርቃቸው ማለዱት፤ የሀገራቸው ምግብ ከንጉሥ ሄርድስ ነበርና።'),
  ('d559e48c-4fb2-51dc-a396-d4c2d2cb9bee', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '304b977f-280e-538d-af5f-d176b805a774', 2, 21, 'ከዚህም በኋላ አንድ ቀን ሄሮድስ ልብሰ መንግሥቱን ለብሶ፥ በአደባባይ ተገኝቶ ይፈርድ ጀመረ።'),
  ('e6bb316f-314b-57ef-ac01-6cdc6179d854', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '304b977f-280e-538d-af5f-d176b805a774', 3, 22, 'ሕዝቡም፥ “የእግዚአብሔር ቃል ነው፤ የሰው ቃልም አይደለም” እያሉ ጮኹ።'),
  ('54ff9fa2-c2cd-5677-a67e-f0150fd70faf', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '304b977f-280e-538d-af5f-d176b805a774', 4, 23, 'ለእግዚአብሔርም ክብር ስለ አልሰጠ ያንጊዜ የእግዚአብሔር መልአክ ቀሠፈው፤ ተልቶም ሞተ።'),
  ('cf9d2368-e629-55ca-a998-a9c6409eafbf', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '304b977f-280e-538d-af5f-d176b805a774', 5, 24, 'የእግዚአብሔርም ቃል ከፍ አለ፤ በዛም።'),
  ('74cf5f73-c5f9-5eaa-a904-56b4f545d340', '43dca93f-3a8d-58c2-a169-40e72f7b9b9e', '304b977f-280e-538d-af5f-d176b805a774', 6, 25, 'በርናባስና ሳውልም አገልግሎታቸውን ፈጽመው ከኢየሩሳሌም ተመለሱ፤ ማርቆስ የተባለውን ዮሐንስንም አስከትለውት መጡ።'),
  ('39cbfe55-ec59-5c5c-a6ee-5f78c8411a92', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '3e557fec-5898-5554-a1d4-6d5dfc96d71a', 1, 1, 'በአንጾኪያ በነበረችው ቤተ ክርስቲያንም ነቢያትና መምህራን ነበሩ፤ እነርሱም በርናባስ፥ ኔጌር የተባለው ስምዖን፥ የቀሬናው ሉቅዮስ፥ ከአራተኛው ክፍል ገዢ ከሄሮድስ ጋር ያደገው ምናሔ፥ ሳውልም ነበሩ።'),
  ('13fffcc3-2bce-5aba-a9f1-8c0506ae21d0', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '3e557fec-5898-5554-a1d4-6d5dfc96d71a', 2, 2, 'የእግዚአብሔርን ሥራ ሲሠሩ፥ ሲጾሙም መንፈስ ቅዱስ፥ “በርናባስንና ሳውልን እኔ ለፈለግኋቸው ሥራ ለዩልኝ” አላቸው።'),
  ('e3320e1c-d0e7-5e1c-a8fc-33ecc5b23ebf', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '3e557fec-5898-5554-a1d4-6d5dfc96d71a', 3, 3, 'ያንጊዜም ከጾሙና ከጸለዩ፥ እጃቸውንም በራሳቸው ላይ ከጫኑባቸው በኋላ ላኩአቸው።'),
  ('a807b4dc-7556-51e5-afee-6ab421155aac', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 1, 4, 'ከመንፈስ ቅዱስም ተልከው ወደ ሴሌውቅያ ወረዱ፤ ከዚያም በመርከብ ወደ ቆጵሮስ ሄዱ።'),
  ('70c20842-dfe3-55f9-a32b-756dc80af173', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 2, 5, 'ወደ ሰልሚና ሀገርም ገብተው በአይሁድ ምኵራቦች የእግዚአብሔርን ቃል አስተማሩ፤ ዮሐንስም እየአገለገላቸው ከእነርሱ ጋር ነበር።'),
  ('c82ce77f-a969-5cb8-a198-ccfcc71646ef', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 3, 6, 'በደሴቲቱም ሁሉ ሲዘዋወሩ ጳፉ ወደምትባል ሀገር ደረሱ፤ በዚያም አንድ አይሁዳዊ የሆነ ሐሰተኛ ነቢይና አስማተኛ ሰው አገኙ፤ ስሙም በርያሱስ ይባላል።'),
  ('a012d8cd-d0b3-5b65-ac7e-d1088d781780', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 4, 7, 'እርሱም ብልህ ሰው በሆነ ሰርግዮስ ጳውሎስ በሚባል አገረ ገዢ ዘንድ ይኖር ነበረ። የእግዚአብሔርንም ቃል ሊሰማ ወድዶ በርናባስንና ሳውልን ወደ እርሱ ጠራቸው።'),
  ('69825335-fb1c-51e1-a84e-9e9fe7217cad', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 5, 8, 'አስማተኛው ኤልማስም የስሙ ትርጓሜ እንዲህ ነበረና፥ ገዥውን ከማመን ሊከለክለው ፈልጎ ተቃወማቸው።'),
  ('195748b5-5f8a-57ae-a2dc-0b3b2919e489', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 6, 9, 'ጳውሎስ በተባለው በሳውል ላይም ቅዱስ መንፈስ ሞላበት፤ አተኵሮም ተመለከተው።'),
  ('cdfe271d-3bad-5dd3-a4a8-ec8a27218c19', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 7, 10, 'እንዲህም አለው፥ “ሽንገላንና ክፋትን ሁሉ የተመላህ፥ የሰይጣን ልጅ፥ የጽድቅ ሁሉ ጠላት ሆይ፥ የቀናውን የእግዚአብሔርን መንገድ ማጣመምህን ትተው ዘንድ እንቢ አልህን?'),
  ('c2ed9220-3b30-5dc5-aff5-1f6d0c401cf3', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 8, 11, 'እነሆ፥ አሁን የእግዚአብሔር እጅ በአንተ ላይ ነው፤ ዕውርም ትሆናለህ፤ እስከ ጊዜውም ፀሐይን አታይም፤” ወዲያውኑም ታወረ፤ ጨለማም ዋጠው፤ የሚመራውም ፈለገ።'),
  ('8997925a-e38d-5ff9-aa55-c10792a39e62', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', '43696eff-c464-5ac0-ae81-89af9f6d8977', 9, 12, 'አገረ ገዢውም የሆነውን በአየ ጊዜ ተገረመ፤ በጌታችን ትምህርትም አመነ።'),
  ('84f4d715-c7b1-589c-aac7-7549d1f11d7e', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 1, 13, 'ከዚህም በኋላ እነ ጳውሎስ ከጳፉ ከተማ ወጥተው ሄዱና የጵንፍልያ አውራጃ ወደምትሆን ወደ ጰርጌን ገቡ፤ ዮሐንስ ግን ትቶአቸው ወደ ኢየሩሳሌም ተመለሰ።'),
  ('5aa95b6c-2c89-5e15-a4f6-efa512dc7ae3', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 2, 14, 'እነርሱም ከጰርጌን አልፈው የጲስድያ አውራጃ ወደምትሆን ወደ አንጾኪያ ደረሱ፤ በሰንበት ቀንም ወደ ምኵራብ ገብተው ተቀመጡ።'),
  ('678d0bde-7ac5-5dc3-a7ed-0b5f48f8602c', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 3, 15, 'ኦሪትንና ነቢያትን ካነበቡ በኋላም የምኵራቡ አለቆች፥ “እናንተ ወንድሞቻችን ሆይ፥ ለሕዝብ ሊነገር የሚገባው የምክር ቃል እንደ አላችሁ ተናገሩ” ብለው ላኩባቸው።'),
  ('fbfaa986-a763-5379-ae53-4f41408ca5aa', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 4, 16, 'ጳውሎስም ተነሥቶ ዝም እንዲሉ አዘዘና እንዲህ አላቸው፥ “እናንት የእስራኤል ሰዎችና እግዚአብሔርንም የምትፈሩ ሁሉ፥ ስሙ።'),
  ('015c8104-97d4-559c-abf2-6820fd3da5aa', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 5, 17, 'የእስራኤል ሕዝብ አምላክ አባቶቻችንን መረጣቸው፤ ወገኖቹንም በተሰደዱበት በምድረ ግብፅ ከፍ ከፍ አደረጋቸው፤ ከዚያም ከፍ ባለ ክንዱ አወጣቸው።'),
  ('bc79f2f6-7ff7-53c9-a507-5d0000004aae', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 6, 18, 'አርባ ዘመንም በምድረ በዳ መገባቸው።'),
  ('4688bfd0-b487-5d66-a4a8-4701f3b1ab73', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 7, 19, 'ሰባቱን የከነዓንን አሕዛብ አጥፍቶ ምድራቸውን አወረሳቸው።'),
  ('2edf81a4-2b20-5702-a55a-75d77428be4e', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 8, 20, 'ከዚህም በኋላ አራት መቶ አምሳ ዓመት እስከ ነቢዩ እስከ ሳሙኤል ዘመን ድረስ መሳፍንትን ሾመላቸው።'),
  ('70c5fba2-d644-55b7-a3de-ef5a9cf08da6', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 9, 21, 'ከዚያም ወዲያ ንጉሥ ያነግሥላቸው ዘንድ ለመኑ፤ እግዚአብሔርም ከብንያም ነገድ የተወለደውን ሰው የቂስን ልጅ ሳኦልን አርባ ዓመት አነገሠላቸው።'),
  ('a12b88cc-df8f-5ad7-a7bf-ce5b60828e2e', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 10, 22, 'እርሱንም ሻረው፤ ከእርሱም በኋላ ዳዊትን አነገሠላቸው፤ ‘የእሴይን ልጅ ዳዊትን ፈቃዴን ሁሉ የሚፈጽም እንደ ልቤም የታመነ ሰው ሆኖ አገኘሁት’ ብሎ መሰከረለት።'),
  ('058b50b0-7c13-5dd3-a916-f78f9dd7424b', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 11, 23, 'እግዚአብሔር ተስፋ እንደ ሰጣቸው ከዳዊት ዘር ለእስራኤል መድኀኒት አድርጎ ኢየሱስን አመጣላቸው።'),
  ('dddbf1ce-3464-5f9e-a6f6-e7153eb0a235', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 12, 24, 'እርሱ ከመምጣቱ አስቀድሞ ዮሐንስ ለእስራኤል ሕዝብ ሁሉ የንስሓ ጥምቀትን ሰበከላቸው።'),
  ('666e1975-b228-5eac-a1d3-faeb2493ac1f', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 13, 25, 'ዮሐንስም መልእክቱን ሲፈጽም እንዲህ አላቸው፦ ‘እኔን ለምን ትጠራጠሩኛላችሁ? እርሱን አይደለሁም፤ የጫማውን ማዘቢያ ከእግሩ ልፈታ የማይገባኝ ከእኔ በኋላ እነሆ፥ ይመጣል።’'),
  ('731ed4bd-dc3f-5063-a656-a6fb9d60d32d', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 14, 26, '“እናንተ ከአብርሃም ወገን የተወለዳችሁ ወንድሞቻችን እግዚአብሔርንም የምትፈሩ፥ ይህ የሕይወት ቃል ለእናንተ ተልኮአል።'),
  ('9d13f7eb-70e0-5c65-aa6f-e5465850ea98', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 15, 27, 'በኢየሩሳሌም የሚኖሩና አለቆቻቸው ግን እርሱን አላወቁም፤ የነቢያት መጻሕፍትንም በየሰንበቱ ሁሉ ሲያነቡ አላስተዋሉትም፤ ነገር ግን ይሙት በቃ ፈረዱበት፥ ስለ እርሱ የተጻፈውንም ሁሉ ፈጸሙበት።'),
  ('c9896f8a-79c0-549b-a98b-b19900dd39e8', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 16, 28, 'ለሞትም የሚያበቃ ምንም በደል ባላገኙበት ጊዜ እንዲገድለው ጲላጦስን ለመኑት።'),
  ('cf3065ed-a3d3-5ce9-a4da-4808e34c62ac', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 17, 29, 'ስለ እርሱም የተጻፈውን ሁሉ ከፈጸሙ በኋላ ከመስቀል አውርደው በመቃብር ቀበሩት።'),
  ('7e691ec9-7a61-5f32-a736-203cc1cfa8a1', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 18, 30, 'እግዚአብሔር ግን ከሙታን ለይቶ አስነሣው።'),
  ('e66e19d0-e995-5d40-a6a9-865c66146b77', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 19, 31, 'ከተነሣም በኋላ ከገሊላ ወደ ኢየሩሳሌም አብረውት ለወጡት ብዙ ቀን ተገለጠላቸው። እነርሱም በሕዝብ ዘንድ ምስክሮች ሆኑት።'),
  ('06570e2e-64e5-564d-a0ab-5e933a8b3360', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 20, 32, '“እኛም እግዚአብሔር ለአባቶቻችን ያናገረላቸውን ተስፋ እንነግራችኋለን።'),
  ('257d3823-b93f-599c-a631-d551fac7fe77', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 21, 33, 'በሁለተኛው መዝሙር፦ ‘አንተ ልጄ ነህ፤ እኔ ዛሬ ወለድሁህ’ እንዳለ ኢየሱስን አስነሥቶ ተስፋውን ለእኛ ለልጆቻቸው ፈጽሞአል።'),
  ('a4ecb551-1bba-5871-a1f9-d0a261befbb8', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 22, 34, 'መፍረስ መበስበስንም እንዳያይ እግዚአብሔር ከሙታን ለይቶ እንዳስነሣው እንዲህ አለ፦ ‘የታመነውን የዳዊትን ቅዱስ ተስፋ እሰጣችኋለሁ።'),
  ('ad476a10-c691-55eb-aef6-cf6d39a5bcbf', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 23, 35, 'በሌላ ስፍራም እንዲህ ይላል፦ ‘ጻድቅህን መፍረስ መበስበስን ያይ ዘንድ አትሰጠውም።’'),
  ('b05d3028-c825-5ac8-a92e-4a61f34995a9', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 24, 36, 'ዳዊት ግን በዘመኑ ለእግዚአብሔር ትእዛዝ አገልግሎአል፤ እንደ አባቶቹ ሞተ፥ ተቀበረም፤ መፍረስ መበስበስንም አይቶአል።'),
  ('6b507fd7-6be0-542e-a0d9-430649c547f7', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 25, 37, 'ይህ እግዚአብሔር ያስነሣው ግን መፍረስ መበስበስን አላየም።'),
  ('b9f23b2e-5a58-5d4d-a664-3b000a57e3ef', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 26, 38, 'እንግዲህ ወንድሞቻችን፥ በእርሱ ኀጢአታችሁ እንደሚሰረይላችሁ ተስፋ የሰጣችሁን ዕወቁ።'),
  ('1812042d-d636-5bc5-aac5-c176eef676fc', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 27, 39, 'ከሁሉም ይልቅ በሙሴ ሕግ መጽደቅ የተሳናችሁ ናችሁ። በእርሱ ግን ያመነ ሁሉ ይጸድቃል።'),
  ('43edc278-6b38-5cd0-a6fc-c93eb6d85b24', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 28, 40, 'እንግዲህ እንዲህ የሚለው የነቢያት ቃል እንዳይደርስባችሁ ተጠንቀቁ።'),
  ('1a743b67-6c84-59ea-a46d-3e26f5441695', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 29, 41, '‘እነሆ፥ እናንተ የምታቃልሉ፥ እዩ፤ ተደነቁም፤ ያለዚያ ግን ትጠፋላችሁ፤ ማንም ቢነግራችሁ የማታምኑትን ሥራ እኔ በዘመናችሁ እሠራለሁና።’ ”'),
  ('14d29b3b-24f5-5cc4-a97d-83a1411cfbeb', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 30, 42, 'ከምኵራብም ከወጡ በኋላ ይህን ነገር በሁለተኛው ሰንበት እንዲነግሩአቸው ማለዱአቸው።'),
  ('3e45d85b-039a-5254-a5cd-adb82880add8', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 31, 43, 'ጉባኤውም በተፈታ ጊዜ ከአይሁድና ወደ ይሁዲነት ከተመለሱት ከደጋጉ ሰዎች ብዙዎች ጳውሎስንና በርናባስን ተከተሉአቸው፤ እነርሱም በእግዚአብሔር ጸጋ ይድኑ ዘንድ እያስረዱ ነገሯቸው።'),
  ('0d85093f-249d-53b0-a4c5-480966bf54ae', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 32, 44, 'በሁለተኛው ሰንበትም የከተማው ሰዎች ሁሉ የእግዚአብሔርን ቃል ይሰሙ ዘንድ ተሰበሰቡ።'),
  ('a8c04917-99e3-5c72-af5e-4af62ebe48b3', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 33, 45, 'አይሁድም የተሰበሰበውን ብዙ ሕዝብ ባዩ ጊዜ ቀኑባቸው፤ እየተሳደቡም ጳውሎስ የተናገረውን ቃል ተቃወሙ።'),
  ('4a6a264d-df2b-56c0-a68c-29caea4517ae', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 34, 46, 'ጳውሎስና በርናባስም ደፍረው እንዲህ ብለው ተናገሩአቸው፥ “የእግዚአብሔርን ቃል ለእናንተ አስቀድሞ ልንነግራችሁ ይገባል፤ እንቢ ብትሉና ራሳችሁን ለዘለዓለም ሕይወት የተዘጋጀ ባታደርጉ ግን እነሆ፥ ወደ አሕዛብ እንመለሳለን።'),
  ('1df8d03f-2575-5b99-a8b4-878823401261', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 35, 47, 'እግዚአብሔር፦ እስከ ምድር ዳርቻ ላሉት ሁሉ መድኀኒት ትሆን ዘንድ ለአሕዛብ ብርሃን አድርጌሃለሁ” ብሎ አዝዞናልና።'),
  ('ecf68b83-3df2-5a1b-a503-c19a3e2c318f', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 36, 48, 'አሕዛብም ይህን ሰምተው ደስ አላቸው፤ የእግዚአብሔርንም ቃል አከበሩ፤ ለዘለዓለም ሕይወትም የተዘጋጁ ሁሉ አመኑ።'),
  ('e1eec4a3-cf01-5c8f-a185-548845353a80', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 37, 49, 'የእግዚአብሔርም ቃል በሀገሩ ሁሉ ተዳረሰ።'),
  ('d7d0262e-1393-5307-a171-5fd1a6c02f44', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 38, 50, 'አይሁድ ግን እግዚአብሔርን የሚፈሩ የከበሩ ሴቶችንና የከተማውን ሽማግሌዎች አነሳሡአቸው፤ በጳውሎስና በበርናባስ ላይም ስደትን አስነሡ፤ ከሀገራቸውም አባረሩአቸው።'),
  ('f030187b-b686-5754-a9f3-3133211edacf', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 39, 51, 'እነርሱ ግን የእግራቸውን ትቢያ አራግፈውባቸው ወደ ኢቆንዮን ሄዱ።'),
  ('89e5d81d-8515-501b-a82b-e78367a84a7a', 'b82830d1-e7ff-505e-a9f1-7186398eadc1', 'da7bed80-52c5-5646-a1c2-6b010f934ee6', 40, 52, 'መንፈስ ቅዱስም በደቀ መዛሙርት ላይ ሞላ፤ ደስም አላቸው።'),
  ('2dd9301f-944c-51fe-ac7f-61d0fa78bb0d', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 1, 1, 'ኢቆንዮን በምትባል ከተማም እንደ ሁልጊዜው ወደ አይሁድ ምኵራብ ገቡ፤ ከአይሁድና ከአረማውያንም ብዙ ሰዎች እስኪያምኑ ድረስ አስተማሩ።'),
  ('d01df10c-f4dc-5912-a31e-032a18483474', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 2, 2, 'ማመንን እንቢ ያሉት የአይሁድ ወገኖች ግን የአሕዝብን ልብ በወንድሞች ላይ አነሣሡ፤ አስከፉም።'),
  ('a022ef9c-6e67-5ce2-aac5-8e2fcde6305f', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 3, 3, 'በጌታም ፊት ደፍረው እያስተማሩ፥ እርሱም የጸጋውን ቃል ምስክር እያሳየላቸው፥ በእጃቸውም ድንቅ ሥራና ተአምራትን እያደረገላቸው ብዙ ወራት ኖሩ።'),
  ('809eacd9-cba6-5cda-a69d-ac4587ccc79f', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 4, 4, 'የከተማውም ሕዝብ ሁሉ ተለያዩ፤ እኩሌቶቹ ወደ አይሁድ፥ እኩሌቶቹም ወደ ሐዋርያት ሆኑ።'),
  ('7c71747c-4b65-5157-a6f7-acc2606c6fe9', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 5, 5, 'አሕዛብና አይሁድ ግን ከአለቆቻቸው ጋር ሊያንገላትዋቸውና በድንጋይ ሊደበድቧቸው ተነሡ።'),
  ('87421c31-99f8-5e1e-acf1-de4c8d693dc3', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 6, 6, 'ሐዋርያትም ይህን ዐውቀው ወደ ሊቃኦንያ ከተሞች ወደ ልስጥራንና ወደ ደርቤን፥ ወደየአውራጃውም ሸሹ።'),
  ('e7bebaa3-2fd9-516d-a3b5-59a497081321', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '9b0db7c2-92c0-597e-a222-387d37a17c79', 7, 7, 'በዚያም ወንጌልን ሰበኩ።'),
  ('02e7a1fd-331c-5517-a82b-7a013faaca48', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 1, 8, 'በልስጥራንም እግሩ የሰለለ፥ ከእናቱም ማኅፀን ጀምሮ ሽባ የሆነ፥ ከቶም ሂዶ የማያውቅ አንድ ሰው ተቀምጦ ነበር።'),
  ('6a67eee6-7287-56d9-a24c-af130fd4a3e9', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 2, 9, 'እርሱም ጳውሎስን ሲያስተምር ሰማው፤ ጳውሎስም ትኩር ብሎ ተመለከተው፤ እምነት እንዳለውና እንደሚድንም ተረዳ።'),
  ('bfd44573-6048-5bdf-a8b9-ceb558b89c3a', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 3, 10, 'ድምፁንም ከፍ አድርጎ፥ “ተነሥና ቀጥ ብለህ በእግርህ ቁም እልሃለሁ” አለው፤ ወዲያውኑም ተነሥቶ ተመላለሰ።'),
  ('bd5cd571-2900-5c4e-a578-84751e90e936', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 4, 11, 'ሕዝቡም ጳውሎስ ያደረገውን ባዩ ጊዜ፥ “አማልክት ሰዎችን መስለው ወደ እኛ ወረዱ” እያሉ በሊቃኦንያ ቋንቋ ጮኹ።'),
  ('2748b4ae-29dc-543e-ad44-21ee7cd9bab2', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 5, 12, 'በርናባስን ድያ አሉት፤ ጳውሎስንም የትምህርቱ መሪ እርሱ ነበርና ሄርሜን ብለው ጠሩት።'),
  ('b5f4d0bb-30b3-5836-aed9-acdc9df52b8b', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 6, 13, 'በከተማውም ፊት ለፊት ቤተ መቅደስ ያለው የድያ ካህን ኮርማዎችንና የአበባ አክሊሎችን ወደ ደጃፍ አመጣ፤ ከሕዝቡም ጋር ሆኖ ሊሠዋላቸው ወደደ።'),
  ('bea04650-d217-52a1-adaf-7e20c9d1c197', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 7, 14, 'ሐዋርያት በርናባስና ጳውሎስም በሰሙ ጊዜ፥ ልብሳቸውን ቀደዱ፤ ፈጥነውም እየጮኹ ወደ ሕዝቡ ሄዱ።'),
  ('7c85fe0d-14a6-5d26-af05-e9ea8f92cec3', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 8, 15, 'እንዲህም አሉአቸው፥ “እናንተ ሰዎች፥ ይህን ነገር ለምን ታደርጋላችሁ? እኛስ እንደ እናንተ የምንሞት ሰዎች አይደለንምን? ነገር ግን ይህን ከንቱ ነገር ትታችሁ ሰማይና ምድርን፥ ባሕርንም በውስጣቸውም ያለውን ሁሉ ወደ ፈጠረ ወደ ሕያው እግዚአብሔር ትመለሱ ዘንድ ወንጌልን እናስተምራችኋለን።'),
  ('7498add6-5051-572e-a683-a24a420689f7', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 9, 16, 'አሕዛብን ሁሉ በቀድሞ ዘመን እንደ ነበሩበት እንደ ጠባያቸው ሊኖሩ ተዋአቸው።'),
  ('5fe5893e-9e72-574c-a57f-29377ca9e945', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 10, 17, 'ከዚህም ሁሉ ጋር መልካም ሥራን እየሠራ ከሰማይ ዝናምን፥ ፍሬ የሚሆንበትንም ወራት ሲሰጠን፥ ልባችንንም በመብልና በደስታ ሲሞላው ራሱን ያለ ምስክር አልተወም።”'),
  ('0e98f2c4-8b2d-5b02-ad73-39dcc55a2a5c', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 11, 18, 'ይህንም ብለው እንዳይሠዉላቸው ሕዝቡን በግድ አስተዉአቸው።'),
  ('e0d968e7-343e-531d-af71-d7a24647cc96', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 12, 19, 'አይሁድም ከአንጾኪያና ከኢቆንያ መጡ፤ ልባቸውንም እንዲያጠኑባቸው አሕዛብን አባበሉአቸው፤ ጳውሎስንም እየጐተቱ ከከተማ ውጭ አውጥተው በድንጋይ ደበደቡት፤ የሞተም መሰላቸው።'),
  ('a134973a-66eb-5a06-a0c1-b347ec0abaf7', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', '5d12bf18-0aa5-542e-a85e-6345f1bf3893', 13, 20, 'ደቀ መዛሙርቱም ከበቡት፤ ነገር ግን ተነሥቶ አብሮአቸው ወደ ከተማ ገባ፤ በማግሥቱም ከበርናባስ ጋር ወደ ደርቤን ሄደ።'),
  ('074944c0-84d9-5f2b-a7c3-38cec416a249', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 1, 21, 'በዚያችም ከተማ ወንጌልን ሰበኩ፤ ብዙ ሰዎችንም ደቀ መዛሙርት አድርገው ወደ ልስጥራን፥ ወደ ኢቆንዮንና ወደ አንጾኪያ ተመለሱ።'),
  ('e9b3feee-96dd-5828-a114-79e0a31a837f', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 2, 22, 'የደቀ መዛሙርትንም ልቡና አጽናኑ፤ በሃይማኖትም እንዲጸኑ፦“ በብዙ ድካምና መከራ ወደ እግዚአብሔር መንግሥት እንገባ ዘንድ ይገባናል” እያሉ መከሩአቸው።'),
  ('0341f6a1-0491-570e-aa41-91e37691a683', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 3, 23, 'ለቤተ ክርስቲያንም ቀሳውስትን ሾሙ፤ ጾሙ፤ ጸለዩም፤ ለሚታመኑበት ለእግዚአብሔርም አደራ ሰጡአቸው።'),
  ('f5b25b04-cf88-5f8d-a407-b2b7a6d50630', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 4, 24, 'ከጲስድያም ዐልፈው ጵንፍልያ ደረሱ።'),
  ('0140b83b-27b0-54e9-a9ca-b7f1e814d2df', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 5, 25, 'ጴርጌን በተባለችው ከተማም ቃሉን ከተናገሩ በኋላ ወደ ኢጣሊያ ወረዱ።'),
  ('ebcbaf2b-fcc4-5f3d-a0de-d9f25b7b3a04', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 6, 26, 'ከዚያም ስለሚሠሩት ሥራ ለእግዚአብሔር ጸጋ አደራ ወደ ተሰጡበት ወደ አንጾኪያ በመርከብ ሄዱ።'),
  ('fde2b3da-1102-5492-a75b-c0816b7d60d2', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 7, 27, 'አንጾኪያም በደረሱ ጊዜ ምእመናኑን ሁሉ ሰብስበው እግዚአብሔር ያደረገላቸውን ሁሉ፥ ለአሕዛብም የሃይማኖትን በር እንደ ከፈተላቸው ነገሩአቸው።'),
  ('d3ed4111-bbf8-5a61-a23c-774d2993b55a', 'c122f376-d9e5-5f8f-aa5a-b945735c8497', 'ea8dd59e-def4-591c-aa49-5f43b8616389', 8, 28, 'ከደቀ መዛሙርትም ጋር አያሌ ቀን ተቀመጡ።'),
  ('7775a5b8-4fae-51aa-a11b-40f8f248ce4c', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '06752716-efd1-55d8-a237-7b351edd2406', 1, 1, 'ከይሁዳ ሀገርም የወረዱ ሰዎች፥ “እንደ ሙሴ ሕግ ካልተገዘራችሁ ልትድኑ አትችሉም” እያሉ ወንድሞችን ያስተምሩ ነበር።'),
  ('d5a292ce-140f-50d4-ac0d-f64e740b1078', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '06752716-efd1-55d8-a237-7b351edd2406', 2, 2, 'ሕዝቡም እጅግ ታወኩ፤ ጳውሎስንና በርናባስንም ተከራከሩአቸው፤ ስለዚህ ነገርም ጳውሎስንና በርናባስን፥ ጓደኞቻቸውንም በኢየሩሳሌም ወደ አሉት ወደ ሐዋርያትና ቀሳውስት ሊልኳቸው ተማከሩ።'),
  ('191d0b58-8fad-5a24-a93d-13df1a74c573', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '06752716-efd1-55d8-a237-7b351edd2406', 3, 3, 'ከቤተ ክርስቲያንም በተላኩ ጊዜ ወደ ሰማርያና ወደ ፊንቄ ደርሰው አሕዛብ ወደ ሃይማኖት እንደ ተመለሱ ነገሩቸአቸው፤ ወንድሞችንም ሁሉ እጅግ ደስ አሰኙአቸው።'),
  ('05bd25df-9f9f-509c-ab9a-3d79667d561e', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '06752716-efd1-55d8-a237-7b351edd2406', 4, 4, 'ወደ ኢየሩሳሌም በደረሱ ጊዜም ምእመናንና ሐዋርያት፥ ቀሳውስትም ተቀበሉአቸው፤ እግዚአብሔርም በአሕዛብ መካከል ያደረገላቸውን ነገሩአቸው።'),
  ('df4f1836-0c5d-55d6-a4cf-9c820f578c44', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '06752716-efd1-55d8-a237-7b351edd2406', 5, 5, 'ነገር ግን ካመኑት ከፈሪሳውያን ወገን አንዳንዶች ተነሥተው፥ “ትገዝሩአቸው ዘንድና የሙሴን ሕግ እንዲጠብቁ ታዝዙአቸው ዘንድ ይገባል” አሉ።'),
  ('07a40d92-5e45-526f-a907-ec6d502c9774', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 1, 6, 'ሐዋርያትና ቀሳውስትም ስለዚህ ነገር የሚያደርጉትን ያዩ ዘንድ ተሰበሰቡ።'),
  ('b459accf-98bf-5596-a2a8-b2ff00fe8c73', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 2, 7, 'ብዙ ክርክርም ከተከራከሩ በኋላ ጴጥሮስ ተነሥቶ እንዲህ አላቸው፥ “ወንድሞች ሆይ፥ ስሙ፤ ለአሕዛብ ከአፌ የወንጌሉን ቃል እንዳሰማቸውና እንዲያምኑ እግዚአብሔር አስቀድሞ እንደ መረጠኝ እናንተ ራሳችሁ ታውቃላችሁ።'),
  ('c031ec11-b081-54af-a59c-3a09b95e496a', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 3, 8, 'ልብን የሚያውቅ እግዚአብሔርም ለእኛ እንደ ሰጠን መንፈስ ቅዱስን በመስጠት መሰከረላቸው።'),
  ('3f316a08-a8e1-5b2d-a70b-fe1f1ebe7a78', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 4, 9, 'ልባቸውንም በእምነት አንጽቶ ከእኛ አልለያቸውም።'),
  ('b016b53d-8f02-57a1-a7d7-c12c7e34e646', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 5, 10, 'አሁንም እግዚአብሔርን አትፈታተኑት፤ እኛም አባቶቻችንም ልንሸከመው ያልቻልነውን ቀንበር በደቀ መዛሙርት ጫንቃ ላይ ለምን ትጭናላችሁ?'),
  ('22e9c562-b8bb-554e-a229-3269dfee642d', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 6, 11, 'ነገር ግን በጌታችን በኢየሱስ ክርስቶስ ጸጋ እንድን ዘንድ እንታመናለን፤ እነርሱም እንደ እኛ ይድናሉ።”'),
  ('45465744-10f8-562e-a5a5-c09a88db9e48', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b3ab91f1-df01-53fd-a558-bd5a6871dc94', 7, 12, 'ያንጊዜም ሕዝቡ ሁሉ ጸጥ ብለው እግዚአብሔር በአሕዛብ ዘንድ ያደረገላቸውን ተአምራትና ድንቅ ሥራ ሁሉ ሲናገሩ ጳውሎስንና በርናባስን አዳመጡአቸው።'),
  ('83f63d31-6c0f-5c46-ad1a-9a89d48322b2', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 1, 13, 'እነርሱም ጸጥ ባሉ ጊዜ ያዕቆብ መልሶ እንዲህ አለ፥ “ወንድሞች ሆይ፥ ስሙኝ።'),
  ('5cb7f47d-03f2-56fd-a374-ae4ab9e0fb34', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 2, 14, 'ስምዖንም፥ እግዚአብሔር አስቀድሞ አሕዛብን ይቅር እንዳላቸውና ከውስጣቸውም ለስሙ ሕዝብን እንደ መረጠ ተናግሮአል።'),
  ('08fc0d79-e00f-54aa-ab94-66b5b64db720', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 3, 15, 'በዚህም መጽሐፍ እንዲህ ብሎ እንደ ተናገረ የነቢያት ቃል ይስማማል።'),
  ('e6328bcc-bcb3-5aed-a47c-468090033dbb', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 4, 16, 'ከዚህም በኋላ የወደቀችውን የዳዊትን ቤት መልሼ እሠራታለሁ፤ ፍራሽዋንም አድሳለሁ፤'),
  ('a85675a9-7a32-573f-af77-bfdcf4598568', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 5, 17, 'የቀሩት ሰዎችና ስሜም የተጠራባቸው አሕዛብ ሁሉ እግዚአብሔርን ይፈልጉ ዘንድ፥ ይላል ይህን የሚያደርግ እግዚአብሔር፤'),
  ('8571aee1-7002-547f-ae3e-49b7816be52b', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 6, 18, 'ከጥንት ጀምሮ ሥራው ሁሉ በእግዚአብሔር ዘንድ የታወቀ ነው።'),
  ('7c3041d7-6bb6-533d-ac4a-2008142c51f9', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 7, 19, '“አሁንም ወደ እግዚአብሔር በተመለሱ አሕዛብ ላይ ሥርዐት አታክብዱ እላችኋለሁ።'),
  ('6359cb20-332c-5886-a69b-f66e33cc8ef3', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 8, 20, 'ነገር ግን ለጣዖት ከሚሠዋው፥ ከዝሙት፥ ሞቶ የተገኘውንና ደም ከመብላት እንዲርቁ፥ ለራሳቸው የሚጠሉትንም በወንድሞቻቸው ላይ እንዳያደርጉ እዘዙአቸው።'),
  ('3490fe06-5820-5899-ab1f-457e68ea22cd', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'e21ef17d-7b4b-55e9-af7f-3db4f701034b', 9, 21, 'ሙሴም ከጥንት ጀምሮ በየከተማዉ የሚሰብክላቸው ትምህርት ነበር፤ በየምኵራቡም በየሰንበቱ ያነብቡት ነበር።”'),
  ('cb91de86-4309-59cc-aac7-aa865ac0d3cf', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 1, 22, 'ከዚህም በኋላ ሐዋርያትና ቀሳውስት ሕዝቡም ሁሉ ከጳውሎስና ከበርናባስ ጋር ወደ አንጾኪያ የሚልኳቸውን ሰዎች ይመርጡ ዘንድ ተስማሙ፤ ከባልንጀሮቻቸው መካከልም የተማሩትን ሰዎች በርናባስ የተባለ ይሁዳንና ሲላስን መረጡ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('91e089f4-f820-5164-a7ba-acb53daad033', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 2, 23, 'እንዲህ የምትል መልእክትም በእጃቸው ጻፉ፤ “ከሐዋርያትና ከቀሳውስት ከወንድሞችም በአንጾኪያ፥ በሶርያና በኪልቅያ ለሚኖሩ፥ ከአሕዛብ ላመኑ ወንድሞቻችን ትድረስ፤ ሰላም ለእናንተ ይሁን፥ ደስ ይበላችሁ።'),
  ('4cf22795-d5f8-54f0-adb9-8c3833660e6e', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 3, 24, 'ያላዘዝናቸው ሰዎች ከእኛ ወጥተው፦ ‘ትገዘሩ ዘንድና የኦሪትንም ሕግ ትጠብቁ ዘንድ ይገባችኋል’ ብለው በነገር እንደ አወኩአችሁና ልባችሁን እንደ አናወጡት ሰምተናል።'),
  ('7cd91e46-dbf3-5acc-ae35-ef4a48519074', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 4, 25, 'ሁላችን ከተሰበሰብን በኋላ በአንድ ቃል በየን፤ አንድ ሆነንም ከወንድሞቻችን ከጳውሎስና ከበርናባስ ጋር ወደ እናንተ የምንልካቸውን ሰዎች መረጥን።'),
  ('71285b0d-e959-5f01-a162-71ee7b530950', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 5, 26, 'እነርሱም ስለ ጌታችን ስለ ኢየሱስ ክርስቶስ ስም ሰውነታቸውን አሳልፈው የሰጡ ሰዎች ናቸው።'),
  ('761902c6-1e50-5ff8-af47-1182b1895aab', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 6, 27, 'ይሁዳንና ሲላስን ልከናቸዋልና እነርሱ በቃላቸው ይህን ያስረዱአችኋል።'),
  ('b981d229-eac6-51ac-aec5-d85fe3787dd6', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 7, 28, 'ሥርዐት እንዳናከብድ ሌላም ሸክም እንዳንጨምር መንፈስ ቅዱስ ከእኛ ጋር ነውና፤ ነገር ግን ይህን በግድ ትተዉ ዘንድ እናዝዛችኋለን።'),
  ('6623e615-35c2-5349-acec-d3d28f878934', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 8, 29, 'ለአማልክት የተሠዋውን፥ ሞቶ የተገኘውን፥ ደምንም አትብሉ፤ ከዝሙትም ራቁ፤ በራሳችሁ የምትጠሉትንም በወንድሞቻችሁ ላይ አታድርጉ፥ ከእነዚህ ሥራዎችም ሰውነታችሁን ብትጠብቁ በሰላም ትኖራላችሁ፤ ደኅና ሁኑ።”'),
  ('494e79be-0e87-5288-af0e-11cae4baf512', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 9, 30, 'እነርሱም ተልከው ወደ አንጾኪያ ወረዱ፤ ሕዝቡንም ሰብስበው የተላከውን ደብዳቤ ሰጡአቸው።'),
  ('3b3ae33a-f0ca-53a0-a2ab-7dde5364973b', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 10, 31, 'እነርሱም አንብበው እጅግ ደስ አላቸው፥ ተጽናኑም።'),
  ('0a53ab82-cc7e-5669-a681-91fbf8aec93d', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 11, 32, 'ይሁዳና ሲላስም መምህራን ነበሩና አስተማሩአቸው፤ ወንድሞችንም በብዙ ቃል አጽናኑአቸው።'),
  ('51756a58-567e-5c72-a0d5-659252cedf66', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 12, 33, 'በእነርሱም ዘንድ አያሌ ቀን ከተቀመጡ በኋላ ወንድሞቻቸውን ተሰናብተው በሰላም ወደ ሐዋርያት ተመለሱ።'),
  ('37cbd40b-1199-5f95-a925-387fb85fdc3c', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 13, 34, 'ሲላስ ግን በዚያ ሊቈይ ወደደ።'),
  ('6f93ad91-58d1-568e-a9da-1c3138949cc0', '228e472d-1264-5566-a4fc-64eeaa44b5d9', '43045133-4302-5b81-ae0d-49f40263dd1b', 14, 35, 'ጳውሎስና በርናባስም በአንጾኪያ ቈዩ፤ ከሌሎች ብዙ ሰዎች ጋርም የእግዚአብሔርን ቃል ሰበኩ፤ አስተማሩም።'),
  ('005f9b60-1566-538d-a18c-3ec4cb0ae512', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b1ba0a61-70f4-5cab-af20-1bd18fb94d9f', 1, 36, 'ከጥቂት ቀን በኋላም ጳውሎስ በርናባስን፦“እንግዲህስ እንመለስና የእግዚአብሔርን ቃል ባስተማርንባቸው ሀገሮች ያሉትን ወንድሞች እንጐብኛቸው፤ እንዴት እንዳሉም እንወቅ” አለው።'),
  ('0dbde246-eb20-53e1-a42f-91cfdb833e4e', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b1ba0a61-70f4-5cab-af20-1bd18fb94d9f', 2, 37, 'በርናባስም ማርቆስ የተባለውን ዮሐንስን ከእነርሱ ጋር ይዞት ሊሄድ ወደደ።'),
  ('da8ae5fa-cf20-5682-a88c-9b0132f29a3b', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b1ba0a61-70f4-5cab-af20-1bd18fb94d9f', 3, 38, 'ጳውሎስ ግን ከእነርሱ ጋር ሊወስደው አልፈቀደም፤ እነርሱ በጵንፍልያ ሳሉ ትቶአቸው ሄዶአልና፤ አብሮአቸውም ለሥራ አልመጣም ነበርና።'),
  ('6a625d1e-907b-5325-aae6-d74f543e06da', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b1ba0a61-70f4-5cab-af20-1bd18fb94d9f', 4, 39, 'ስለዚህም ተኰራርፈው እርስ በርሳቸው ተለያዩ፤ በርናባስም ማርቆስን ይዞ በመርከብ ወደ ቆጵሮስ ሄደ።'),
  ('0f50c91d-531c-568f-a092-64deed13d62d', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b1ba0a61-70f4-5cab-af20-1bd18fb94d9f', 5, 40, 'ጳውሎስ ግን ሲላስን መረጠ፤ ወንድሞችም ለእግዚአብሔር ጸጋ አደራ ከሰጡት በኋላ ሄደ።'),
  ('da7b1f64-3c6c-544a-aad8-58655c687bcb', '228e472d-1264-5566-a4fc-64eeaa44b5d9', 'b1ba0a61-70f4-5cab-af20-1bd18fb94d9f', 6, 41, 'በሶርያና በኪልቅያም እየዞረ አብያተ ክርስቲያናትን አጽናና።'),
  ('8ab86c68-7ac2-5f1c-a411-0309da1f01b6', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 1, 1, 'ወደ ደርቤንና ወደ ልስጥራን ከተማም ደረሰ፤ እነሆም፥ በዚያ የአንዲት ያመነች አይሁዳዊት ልጅ ጢሞቴዎስ የሚባል አንድ ደቀ መዝሙር ነበር፤ አባቱ ግን አረማዊ ነበረ።'),
  ('cb0f2ce1-6341-58cf-a2e6-0144b1f45c9e', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 2, 2, 'በደርቤንና በልስጥራን በኢቆንዮንም ያሉ ወንድሞች ሁሉ ይመሰክሩለት ነበር።'),
  ('8e7f43b8-767e-5f2b-ae27-c6aceed54dd7', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 3, 3, 'ጳውሎስም ከእርሱ ጋር ይዞት ሊሄድ ወደደ፤ በዚያም ሀገር ስለ አሉት አይሁድ ወስዶ ገረዘው፤ አባቱ አረማዊ እንደ ነበረ ሁሉም ያውቁ ነበርና።'),
  ('2f1a36d5-891d-553b-a4c3-b263ce4b2114', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 4, 4, 'በየከተማውም ሲሔዱ፥ ሐዋርያትና ቀሳውስት በኢየሩሳሌም ያዘዙትን ሥርዐት አስተማሩአቸው።'),
  ('8244cf27-3b29-5d76-a594-82ac92908de4', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 5, 5, 'አብያተ ክርስቲያናትም በሃይማኖት ጸኑ፤ ዕለት ዕለትም ቍጥራቸው ይበዛ ነበር።'),
  ('cbad2b20-d71c-5199-a6e6-df2ec108eb89', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 6, 6, 'ነገር ግን የእግዚአብሔርን ቃል በእስያ እንዳይናገሩ መንፈስ ቅዱስ ስለከለከላቸው ወደ ፍርግያና ወደ ገላትያ አውራጃ ሄዱ፤'),
  ('3fc0bbb7-bc0c-52d9-a847-cd84a8ecfefb', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 7, 7, 'ሚስያ በደረሱ ጊዜም ወደ ቢታንያ ሊሄዱ ወደዱ፤ የጌታችን ኢየሱስ መንፈስ ግን አልፈቀደላቸውም።'),
  ('2ff0d824-fd6b-51bf-a56d-acc297d26d05', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 8, 8, 'ከሚስያም ዐልፈው ወደ ጢሮአዳ ወረዱ።'),
  ('e040ee0d-0998-5f65-ac3d-99201e563569', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 9, 9, 'ለጳውሎስም በሌሊት አንድ መቄዶናዊ ሰው ቁሞ፥ “ወደ እኛ ወደ መቄዶንያ ዕለፍና ርዳን” እያለ ሲማልደው በራእይ ተገለጸለት።'),
  ('67174146-4d2c-5b41-ab8c-6f16aac804d4', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 10, 10, 'ራእዩንም ባየ ጊዜ ወዲያውኑ ወደ መቄዶንያ ልንሄድ ወደድን፤ ወንጌልን እንሰብክላቸው ዘንድ እግዚአብሔር የሚጠራን መስሎናልና።'),
  ('0badf0e7-f08c-5755-a065-8ee37cc20c15', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 11, 11, 'ከጢሮአዳም ወጥተን ወደ ሰሞትራቄ ገባን፤ በማግሥቱም ናጶሊ ወደምትባለው ሀገር በመርከብ መጣን።'),
  ('226bb1cf-dfbd-55bf-a21f-0f8f4afd8490', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'b98fdcd9-33e7-5d29-a306-f14de87bb3ff', 12, 12, 'ከዚያም ወደ ፊልጵስዩስ ሄድን፤ ይህችውም የመቄዶንያ ዋና ከተማና የሮም ቅኝ ግዛት ነበረች፤ በዚያችም ሀገር ጥቂት ቀን ሰነበትን።'),
  ('98ae9279-961a-5e5a-af4d-479a219c0fa0', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', '9fec31b9-3068-50c1-a3cf-8445b8a93d3b', 1, 13, 'በሰንበት ቀንም ከከተማዉ በር ወደ ባሕሩ ዳር ወጣን፤ በዚያ የጸሎት ቤት ያለ መስሎን ነበርና፤ በዚያም ተቀምጠን፥ በዚያ ለተሰበሰቡ ሴቶች እናስተምር ጀመርን።'),
  ('7c885551-88b5-55cf-a0af-f5d55342377b', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', '9fec31b9-3068-50c1-a3cf-8445b8a93d3b', 2, 14, 'በመካከላቸውም ቀይ ሐር የምትሸጥ ከትያጥሮን ሀገር የመጣች እግዚአብሔርን የምትፈራ አንዲት ሴት ነበረች፤ እግዚአብሔርም ልቡናዋን ከፍቶላት ነበርና ጳውሎስ የሚያስተምረውን ታዳምጥ ነበር፤ ስምዋም ልድያ ይባል ነበር።'),
  ('a3e236f3-37df-574c-a0b9-be063e3e138d', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', '9fec31b9-3068-50c1-a3cf-8445b8a93d3b', 3, 15, 'እርስዋም ከቤተ ሰቦችዋ ጋር ተጠመቀች፤ “ለእግዚአብሔር አማኝ ካደረጋችሁኝስ ወደ ቤቴ ገብታችሁ እደሩ” ብላ ማለደችን፤ የግድም አለችን።'),
  ('d332b02c-6dbb-50b7-ae11-e9ec30f41ac6', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 1, 16, 'ለጸሎት ስንሄድም የምዋርተኛነት መንፈስ ያደረባት አንዲት ልጅ አገኘችን፤ በጥንቈላም የምታገኘውን ብዙ እጅ መንሻ ለጌቶችዋ ታገባ ነበር።'),
  ('3aeb1c14-8205-5dd5-aee7-a74cfa930b76', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 2, 17, 'ከዚህም በኋላ ጳውሎስንና እኛን እየተከተለች፥ “እነዚህ ሰዎች የልዑል እግዚአብሔር አገልጋዮች ናቸው፤ የሕይወትንም መንገድ ያስተምሩአችኋል” እያለች ትጮኽ ነበር።'),
  ('6e5139e1-f194-56f7-a4f1-f126bd7ce5ca', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 3, 18, 'ብዙ ቀንም እንዲሁ ታደርግ ነበር፤ ጳውሎስንም አሳዘነችው፤ መለስ ብሎም፥ “መንፈስ ርኩስ፥ ከእርስዋ እንድትወጣ በጌታችን በኢየሱስ ክርስቶስ ስም አዝዤሃለሁ” አለው፤ ወዲያውኑም ተዋት።'),
  ('c83198f5-2496-56ed-a893-76cbdca8c826', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 4, 19, 'ጌቶችዋም የምታገባላቸው የጥቅማቸው ተስፋ እንደ ቀረ ባዩ ጊዜ ጳውሎስንና ሲላስን ይዘው በገበያ እየጐተቱ ወደ ገዢዎች ወሰዱአቸው።'),
  ('25522747-2238-5e61-afce-afc15e7fa7e2', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 5, 20, 'ወደ ገዢዎችም አቅርበው፥ “እነዚህ ሰዎች ከተማችንን ያሸብሩብናል፤ እነርሱም አይሁድ ናቸው።'),
  ('c6e4626e-a3bc-5b72-a53e-62c09c8adfb8', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 6, 21, 'እኛ የሮሜ ሰዎች ስንሆንም ልናደርገው የማይገባንን ሕግ ይናገራሉ” አሉ።'),
  ('6c2cfc36-0bac-5e1f-ac08-2318bd2dcade', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 7, 22, 'ሕዝቡም ተነሡባቸው፤ ገዢዎቹም ልብሳቸውን ገፍፈው በበትር ይመቱአቸው ዘንድ አዘዙ።'),
  ('d53cd7ea-c25c-5506-aaa4-6eeadefdc438', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 8, 23, 'በብዙም ደብድበው አሰሩአቸው፤ የወህኒ ቤቱን ዘበኛም አጽንቶ እንዲጠብቃቸው አዘዙት።'),
  ('32386bef-3188-5d1c-ae03-06ae22144f2c', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 9, 24, 'እርሱም ትእዛዙን ተቀብሎ ወደ ውስጠኛው ወኅኒ ቤት አስገባቸው፤ እግራቸውንም በግንድ አጣብቆ ጠረቃቸው።'),
  ('c0a4f783-c6e9-5b98-a438-1c3fe90d787e', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 10, 25, 'በመንፈቀ ሌሊትም ጳውሎስና ሲላስ ጸለዩ፤ እግዚአብሔርንም በዜማ አመሰገኑት፤ እስረኞቹም ይሰሙአቸው ነበር።'),
  ('d761e78b-98fd-5d1d-ad6d-a908000dc5c5', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 11, 26, 'ድንገትም ታላቅ ንውጽውጽታ ሆነ፤ የወህኒ ቤቱ መሠረትም ተናወጠ፤ በሮችም ሁሉ ያንጊዜ ተከፈቱ፤ የሁሉም እግር ብረቶቻቸው እየወለቁ ወደቁ።'),
  ('2d4e04ea-dbaf-5c51-aa5f-514de9c36d6d', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 12, 27, 'የወህኒ ቤቱ ጠባቂም ከእንቅልፉ በነቃ ጊዜ በሮች ሁሉ ተከፍተው አየ፤ ሰይፉንም መዝዞ ራሱን ሊገድል ወደደ፤ እስረኞቹ ያመለጡት መስሎት ነበርና።'),
  ('8bdf0184-5350-58ca-a4e2-027adc79e2c6', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 13, 28, 'ጳውሎስም፥ “በራስህ ክፉ ነገር አታድርግ፤ ሁላችንም ከዚህ አለን” ብሎ በታላቅ ቃል ጮኸ።'),
  ('cd55dad1-ed06-5fed-ab88-be45305a4171', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 14, 29, 'መብራት አምጥቶም እየተንቀጠቀጠ ወደ ውስጥ ሄደና ለጳውሎስና ለሲላስ ወድቆ ሰገደ።'),
  ('2b71127d-53a2-523c-a0d4-83e9ce5bc762', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 15, 30, 'ወደ ውጭም አውጥቶ “ጌቶች፥ እድን ዘንድ ምን ላድርግ?” አላቸው።'),
  ('ec195f16-0541-50b8-a935-940020118c82', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 16, 31, 'እነርሱም፥ “በጌታችን በኢየሱስ ክርስቶስ እመን፤ አንተና ቤተ ሰብህም ሁሉ ትድናላችሁ” አሉት።'),
  ('2e38d0f6-1b37-55fd-a7b6-53505b42df43', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 17, 32, 'የእግዚአብሔርንም ቃል ለእርሱና በቤቱ ላሉት ሁሉ ነገሩአቸው።'),
  ('d0993898-679e-56bc-a59e-c37c4c567f2b', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 18, 33, 'ወዲያውኑም በሌሊት ወስዶ ቍስላቸውን አጠበላቸው፤ እርሱም በዚያው ጊዜ ከቤተ ሰቡ ሁሉ ጋር ተጠመቀ።'),
  ('0effde35-4a6e-5217-ae7e-d1827960d28b', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 19, 34, 'ወደ ቤቱም አግብቶ ማዕድ አቀረበላቸው፤ በጌታችን ስለ አመነም እርሱ ከቤተ ሰቡ ጋር ደስ አለው።'),
  ('9a8c6c62-7ab6-58d1-af91-60de03aefd07', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 20, 35, 'በነጋ ጊዜም፥ ገዢዎቹ፥ “እነዚያን ሰዎች ፈትታችሁ ልቀቋቸው” ብለው ብላቴኖቻቸውን ላኩ።'),
  ('6b1b22e4-9e71-57cd-a726-289c8a4c4b98', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 21, 36, 'የወህኒ ቤቱ ጠባቂም በሰማ ጊዜ ሄዶ ገዢዎቹ “ይፈቱ” ብለው እንደ ላኩ ይህን ነገር ለጳውሎስና ለሲላስ ነገራቸው፤ “አሁንም ውጡና በሰላም ሂዱ” አላቸው።'),
  ('1fc9b67c-8b03-5d61-a4ff-3434efefb32c', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 22, 37, 'ጳውሎስ ግን፥ “እኛ የሮም ሰዎች ስንሆን፥ ያለ ፍርድ በአደባባይ ገረፉን፤ አሰሩንም፤ አሁንም በስውር ሊያወጡን ይሻሉ፤ አይሆንም፥ ራሳቸው መጥተው ያውጡን” አላቸው።'),
  ('f86414b9-4de6-5007-a7a6-aed25c1b80f2', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 23, 38, 'ብላቴኖቻቸውም ሄደው ይህንን ነገር ለገዢዎቹ ነገሩአቸው፤ የሮም ሰዎች መሆናቸውንም ሰምተው ደነገጡ።'),
  ('d623908b-cab8-5d84-ab33-effd9c651350', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 24, 39, 'መጥተውም ከከተማቸው እንዲወጡ ማለዱአቸው።'),
  ('d0d419eb-c70d-5853-a3ed-549f416fd84e', '2461e07d-7422-5970-aa2d-d1018d6c2bf5', 'fcd7d16c-4534-56e1-a0f5-14479f387367', 25, 40, 'ከወኅኒ ቤቱም ከወጡ በኋላ ወደ ልድያ ቤት ገብተው ወንድሞችን አገኙ፤ አጽናንተዋቸውም ሔዱ።'),
  ('66413d99-a88c-51a4-ab97-139c510e1083', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 1, 1, 'አንፊጶልና አጶሎንያ ወደሚባሉ ሀገሮችም ሄዱ፤ የአይሁድ ምኵራብ ወደ አለበት ወደ ተሰሎንቄም ደረሱ።'),
  ('e411ba88-b5ab-5e6f-a284-b934c284a095', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 2, 2, 'ጳውሎስም እንደ አስለመደው ወደ እነርሱ ገብቶ ሦስት ሳምንት ከመጻሕፍት እየጠቀሰ ሲከራከራቸው ሰነበተ።'),
  ('3a362162-db18-551a-acba-7c07ff6f32bf', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 3, 3, 'ክርስቶስ እንዲሞት ከሙታንም ተለይቶ እንዲነሣ፥ እየተረጐመና እየአስተማራቸው፥ “ይህ እኔ የነገርኋችሁ ኢየሱስ እርሱ ክርስቶስ ነው” ይል ነበር።'),
  ('c7f02a7b-5d56-5218-aafc-7b3c63e4f01d', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 4, 4, 'ከእነርሱና ከደጋጎች አረማውያንም ብዙ ሰዎች፥ ከታላላቆች ሴቶችም ጥቂቶች ያይደሉ አምነው ከጳውሎስና ከሲላስ ጋር ሆኑ።'),
  ('9dba60ce-07be-5e61-ae8f-7ad5bdb663ad', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 5, 5, 'የማያምኑ አይሁድ ግን ቀኑባቸው፤ ከገበያም ክፉዎች ሰዎችን አምጥተው፥ ሰዎችንም ሰብስበው ሀገሪቱን አወኳት፤ ፈለጓቸውም፤ የኢያሶንን ቤትም በረበሩ፤ ወደ ሕዝቡም ሊያወጧቸው ሽተው ነበር።'),
  ('58f40e19-2310-55b0-af2b-57ef98bde962', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 6, 6, 'በአጧቸውም ጊዜ ኢያሶንን ጐተቱት፤ በዚያም የነበሩትን ጓደኞች ጭምር ወደ ሹሞቹ ወሰዱአቸው፤ እየጮኹም እንዲህ ይሉ ነበር፥ “ዓለምን የሚያውኳት እነዚህ ናቸው፤ ወደዚህም መጥተዋል።'),
  ('4cbc8b09-811b-5005-ab5b-47882c7ecfec', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 7, 7, 'ይህ ኢያሶንም ተቀበላቸው፤ እነርሱም በቄሣር ላይ የወንጀል ሥራ ይሠራሉ፤ ሌላ ሕግንም ያስተምራሉ፤ ኢየሱስም ሌላ ንጉሥ ነው” ይላሉ።'),
  ('a5406731-00fd-56b5-affd-d3007aa52008', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 8, 8, 'ሕዝቡና የከተማው ሹሞችም ይህን በሰሙ ጊዜ ታወኩ።'),
  ('31a9e910-542c-56d5-a930-d552a7bcf3b3', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 9, 9, 'ከኢያሶንና ከጓደኞቹም ዋስ ተቀብለው ለቀቁአቸው።'),
  ('a334395d-a201-5305-ad1d-91a5934d5f94', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 10, 10, 'ወንድሞች ግን ጳውሎስንና ሲላስን በሌሊት ወደ ቤርያ ሸኙአቸው፤ ወደዚያም በደረሱ ጊዜ ወደ አይሁድ ምኵራብ ገቡ።'),
  ('53a42cb9-9ec4-5cd2-a30a-1d1579a9c7ac', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 11, 11, 'በተሰሎንቄ ካሉትም እነርሱ ይሻላሉ፤ በፍጹም ደስታ ቃላቸውን ተቀብለዋልና፤ ነገሩም እንደ አስተማሩአቸው እንደ ሆነ ለመረዳት ዘወትር መጻሕፍትን ይመረምሩ ነበር።'),
  ('ee1726bf-d45d-52f5-a41f-8665017e3da2', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 12, 12, 'ከመካከላቸውም ያመኑ ብዙዎች ነበሩ፤ ከአረማውያን ወገን የሆኑ ብዙ ደጋግ ሴቶችም ነበሩ፤ ወንዶችም ብዙዎች ነበሩ።'),
  ('c3822d3c-53d8-5a7e-ad77-5fb2c1480692', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 13, 13, 'በተሰሎንቄ የነበሩ አይሁድ ግን ጳውሎስ በቤርያ የእግዚአብሔርን ቃል እንደ አስተማረ ባወቁ ጊዜ፥ ወደዚያ መጥተው ሕዝቡን አወኩአቸው።'),
  ('51a07b6d-5e30-51dc-a1e5-65a6969c1ea5', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 14, 14, 'ያንጊዜም ወንድሞች ጳውሎስን ሸኝተው ወደ ባሕር አደረሱት፤ ሲላስና ጢሞቴዎስ ግን በዚያው ቀሩ።'),
  ('e4312dfc-b978-5499-ac70-2039b71b35c3', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '20d8a1ae-8533-522e-a047-4766679578ce', 15, 15, 'ጳውሎስን የሸኙት ሰዎችም እስከ አቴና ከተማ ድረስ አብረውት መጥተው ነበርና ፈጥነው ይከተሉት ዘንድ ወደ ሲላስና ወደ ጢሞቴዎስ ላካቸው፤ ተመልሰውም ሄዱ።'),
  ('8f4f4893-94ed-5163-aed3-21c85e3f0f35', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '393b5b3a-201a-54e4-ad1f-ae4f9985b7ad', 1, 16, 'ጳውሎስም በአቴና ሆኖ ሲጠብቃቸው ከተማው ሁሉ ጣዖት ሲያመልኩ ባየ ጊዜ ልቡናው ተበሳጨ።'),
  ('214f0227-5870-5f90-a676-f3c4b0741f1e', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '393b5b3a-201a-54e4-ad1f-ae4f9985b7ad', 2, 17, 'ስለዚህም በምኵራብ አይሁድንና እግዚአብሔርን የሚፈሩትን፥ ሁልጊዜም በገበያ የሚያገኛቸውን ሁሉ ይከራከራቸው ነበር።'),
  ('6b38ec35-79ed-5ee4-ad1b-bbfb8d1db1bf', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '393b5b3a-201a-54e4-ad1f-ae4f9985b7ad', 3, 18, 'የኤፌቆሮስን ትምህርት ከተማሩ ፈላስፋዎች መካከልና ረዋቅያውያን ከሚባሉት ወገን የሆኑ ሌሎች ፈላስፎችም የተከራከሩት ነበሩ፤ እኩሌቶችም፥ “ይህ ለፍላፊ ምን ሊናገር ይፈልጋል?” ይሉ ነበር፤ ሌሎችም፥ “ስለ ኢየሱስ ከሙታን ስለ መነሣቱም ሰብኮላቸዋልና የአዲስ አምላክ ትምህርትን ያስተምራል” አሉ።'),
  ('cc66f884-d294-5666-a5eb-c52212d50a48', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '393b5b3a-201a-54e4-ad1f-ae4f9985b7ad', 4, 19, 'ይዘውም አርዮስፋጎስ ወደሚባል ሸንጎ ወሰዱት፤ እንዲህም አሉት፥ “ይህን የምታስተምረውን አዲስ ትምህርት እናውቅ ዘንድ ይቻለናልን? እስቲ ንገረን?'),
  ('3b8c6876-c86a-513c-a872-a02feff66a60', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '393b5b3a-201a-54e4-ad1f-ae4f9985b7ad', 5, 20, 'በጆሮአችን እንግዳ ነገር ታሰማናለህና እኛም ይህ ነገር ምን እንደ ሆነ ልንረዳ እንወዳለን።”'),
  ('0fef936f-9346-561e-a87c-6033a4168ab8', '5a25946f-86a0-56b6-ad3c-0190b8d33446', '393b5b3a-201a-54e4-ad1f-ae4f9985b7ad', 6, 21, 'የአቴና ሰዎችና በዚያም የነበሩ እንግዶች ሁሉ አዲስ ነገርን ከመናገርና ከመስማት በቀር ሌላ ዐሳብ አልነበራቸውም።'),
  ('65519475-b98b-57b7-a28e-ec14cb6faf57', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 1, 22, 'ጳውሎስም በአርዮስፋጎስ ውስጥ ቆሞ እንዲህ አላቸው፥ “እናንተ የአቴና ሰዎች! በሥራችሁ ሁሉ አማልክትን ማምለክ እንደምታበዙ አያችኋለሁ።'),
  ('482a8919-c2bb-5b57-a4b0-c68a55e94c2b', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 2, 23, 'በዚህም ሳልፍ ‘ለማይታወቅ አምላክ’ የሚል ጽሕፈት ያለበትን የምታመልኩበትን መሠዊያችሁን አየሁ፤ እነሆ፥ እኔ ይህን ሳታውቁ የምታመልኩትን እገልጽላችኋለሁ።'),
  ('903989c7-99af-569b-a332-81b282efb10f', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 3, 24, 'ዓለሙንና በእርሱም ያለውን ሁሉ የፈጠረ አምላክ እርሱ የሰማይና የምድር ጌታ ነውና እጅ በሠራው መቅደስ አይኖርም።'),
  ('cea80916-1868-5413-a9ab-6869a58675e5', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 4, 25, 'እርሱም ሕይወትንና እስትንፋስን፥ ሌላውንም ነገር ሁሉ ለሁሉ ይሰጣልና እንደ ችግረኛ የሰው እጅ አያገለግለውም።'),
  ('942bd676-cfe3-5eea-a624-0d68acc2ae1f', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 5, 26, 'እርሱም በምድር ሁሉ ላይ ይኖሩ ዘንድ ሰዎችን ሁሉ ከአንድ ሰው ፈጠረ፤ ይኖሩባትም ዘንድ ዘመንንና ቦታን ወስኖ ሠራላቸው።'),
  ('aa6066fc-fbb7-559b-a39f-12d31cad5018', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 6, 27, 'ምናልባት ያገኙት እንደ ሆነ እግዚአብሔርን ይፈልጉት ዘንድ፤ ነገር ግን ከሁላችን የራቀ አይደለም።'),
  ('ae715e1d-e6eb-5588-a5c6-e1f9ad2e8ae0', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 7, 28, 'እኛ በእርሱ ሕይወትን እናገኛለን፤ በእርሱም እንንቀሳቀሳለን፤ በእርሱም ጸንተን እንኖራለን፤ ከመካከላችሁም፦ ‘እኛ ዘመዶቹ ነን’ የሚሉ ፈላስፎች አሉ።'),
  ('03823b92-7722-5069-a7f7-0f7987d3d8f6', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 8, 29, 'እንግዲህ እኛ የእግዚአብሔር ዘመዶች ከሆን በሰው ዕውቀትና ብልሀት በተቀረጸ በድንጋይና በብር፥ በወርቅም አምላክነቱን ልንመስለው አይገባም።'),
  ('fbaf1535-8722-5efd-a549-7ad8713f50f5', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 9, 30, 'የቀድሞውንስ ያለ ማወቅ ዘመን እግዚአብሔር አሳልፎታል፤ ዛሬ ግን በመላው ዓለም ንስሓ እንዲገቡ ሰውን ሁሉ አዝዞአል።'),
  ('359113f2-1e81-55c6-a144-683dfad2089d', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 10, 31, 'በመረጠው ሰው እጅ በዓለም በእውነት የሚፈርድባትን ቀን ወስኖአልና፤ እርሱን ከሙታን ለይቶ በማስነሣቱም ብዙዎችን ወደ ሃይማኖት መልሶአልና።”'),
  ('76fff3e5-dc74-543d-ac58-2beb812810ec', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 11, 32, 'የሙታንንም ትንሣኤ በሰሙ ጊዜ እኩሌቶቹ አፌዙበት፤ ሌሎችም፥ “ስለዚህ ነገር በሌላ ቀን እናዳምጥሃለን” አሉት።'),
  ('9e390731-e65e-517e-ae55-decabf9ca712', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 12, 33, 'ጳውሎስም ከመካከላቸው ወጥቶ ሄደ።'),
  ('3237e44b-7c48-5256-a781-0013d6e3c82d', '5a25946f-86a0-56b6-ad3c-0190b8d33446', 'b68465cc-407e-529c-af3b-80ce2c8f372c', 13, 34, 'አምነው የተከተሉት ሰዎችም ነበሩ፤ ከእነርሱም አንዱ ከአርዮስፋጎስ ባለሥልጣኖች ወገን የሚሆን ዲዮናስዮስ ነበር፤ ደማሪስ የምትባል ሴትም ነበረች፤ ሌሎችም አብረዋቸው ነበሩ።'),
  ('8316efdc-655b-59d8-a81a-dca150e8fcff', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 1, 1, 'ከዚህ በኋላ ጳውሎስ ከአቴና ወጥቶ ወደ ቆሮንቶስ ሄደ።'),
  ('3b0f38f6-658b-53b2-afa4-51b547b2a1e7', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 2, 2, 'አቂላ የሚባል አንድ አይሁዳዊም አገኘ፤ የትውልድ ሀገሩም ጳንጦስ ነው፤ እርሱም ከጥቂት ወራት በፊት ከኢጣልያ ተሰዶ መጣ፤ ሚስቱ ጵርስቅላም አብራው ነበረች፤ ቀላውዴዎስ አይሁድ ከሮም እንዲሰደዱ አዝዞ ነበርና ወደ እነርሱ መጣ።'),
  ('31e22c08-ff1e-528c-abc5-d1078b0eda42', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 3, 3, 'ሥራቸው አንድ ስለ ነበረ ድንኳን ሰፊዎችም ስለ ነበሩ ከእነርሱ ጋር አብሮ ኖረ፤ በአንድነትም ይሠሩ ነበር።'),
  ('277615a7-413d-5725-a2c3-d4b4b34084bf', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 4, 4, 'ጳውሎስም በየሰንበቱ በምኵራብ ይከራከራቸው ነበር፤ አይሁድንና አረማውያንንም ያሳምናቸው ነበር።'),
  ('68bd78aa-e484-503d-afbd-cf3582d22044', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 5, 5, 'ሲላስና ጢሞቴዎስም ከመቄዶንያ በወረዱ ጊዜ ጳውሎስ፥ ኢየሱስ እርሱ ክርስቶስ እንደ ሆነ ለአይሁድ እየመሰከረ ቃሉን በማስተማር ይተጋ ነበር።'),
  ('a87a3c58-037e-5f47-a59b-fc5c83f1d9da', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 6, 6, 'እነርሱም በተቃወሙትና በሰደቡት ጊዜ ልብሱን አራግፎ፥ “እንግዲህ እኔ ንጹሕ ነኝ፤ ደማችሁ በራሳችሁ ላይ ነው፤ ከእንግዲህስ ወዲህ ወደ አሕዛብ እሄዳለሁ” አላቸው።'),
  ('65a756b9-c01e-5142-ae86-2b58372080e1', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 7, 7, 'ከዚያም አልፎ ስሙ ኢዮስጦስ ወደሚባል እግዚአብሔርን ወደሚፈራ ሰው ቤት ገባ፤ ቤቱም በምኵራብ አጠገብ ነበር።'),
  ('9de01889-d3bd-5797-a2c0-123ee69154d3', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 8, 8, 'የምኵራብ አለቃ ቀርስጶስም ከነቤተ ሰቡ በጌታችን በኢየሱስ ክርስቶስ አመነ፤ ከቆሮንቶስ ሰዎችም ብዙዎች ሰምተው አምነው ተጠመቁ።'),
  ('f78fe403-3d1e-526b-a41e-67e5b21ce45c', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 9, 9, 'ጌታችንም ጳውሎስን በሌሊት ራእይ እንዲህ አለው፥ “አትፍራ፥ ነገር ግን ተናገር፥ ዝምም አትበል፤'),
  ('656cc604-82ea-55ca-aee8-83ae64c725bc', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 10, 10, 'እኔ ከአንተ ጋር ነኝና ማንም ሊጐዳህ የሚነሣብህ የለም፤ በዚች ከተማ ብዙ ሕዝብ አሉኝና።”'),
  ('10faf9d6-57b2-5095-a461-ae446c7d6432', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 11, 11, 'ጳውሎስም የእግዚአብሔርን ቃል እየአስተማራቸው ዓመት ከስድስት ወር በቆሮንቶስ ተቀመጠ።'),
  ('d2a4f9fd-c097-5792-a349-b731336f1c40', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 12, 12, 'ጋልዮስም የአካይያ አገረ ገዢ በሆነ ጊዜ አይሁድ ተባብረው በጳውሎስ ላይ ተነሡ፤ ወደ ሸንጎም አመጡት።'),
  ('4552df23-6d6b-5c88-a5d9-3c545cbbe802', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 13, 13, 'እንዲህም አሉት፥ “ይህ ሰው ኦሪትን በመቃወም እግዚአብሔርን ያመልኩ ዘንድ ሰዎችን ያባብላል።”'),
  ('d1de8eef-a2cc-5505-ae66-5812bf0ea1cf', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 14, 14, 'ጳውሎስም ይመልስላቸው ዘንድ አፉን ሊከፍት ወድዶ ሳለ አገረ ገዢው ጋልዮስ መልሶ አይሁድን እንዲህ አላቸው፥ “እናንተ አይሁድ ሆይ፥ የበደላችሁ በደል ቢኖር፥ ወይም ሌላ በደል ቢኖርበት አቤቱታችሁን በሰማሁና ባከራከርኋችሁ ነበር።'),
  ('ddbfe976-800f-5482-a439-78f63d07a5df', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 15, 15, 'ስለ ትምህርትና ስለ ስሞች፥ ስለ ሕጋችሁም የምትከራከሩ ከሆነ ግን ለራሳችሁ ዕወቁ፤ እኔ እንዲህ ያለ ነገር ልሰማ አልፈቅድም።”'),
  ('a8ba2c2f-6af0-5c2d-a175-28db223e7767', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 16, 16, 'ከሸንጎውም አባረራቸው።'),
  ('e356dbfe-5f5f-5882-aa14-b506ea380212', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 17, 17, 'አረማውያንም ሁሉ የምኵራቡን አለቃ ሶስቴንስን ይዘው በሸንጎ ፊት ደበደቡት፤ የእርሱም ነገር ጋልዮስን ምንም አላሳዘነውም።'),
  ('306451e2-3ef1-5185-a8a4-3208aab591f5', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 18, 18, 'ጳውሎስም እንደ ገና በወንድሞቹ ዘንድ ጥቂት ቀን ተቀመጠ፤ በሰላምም ሸኙትና ወደ ሶርያ በባሕር ተጓዘ፤ ጵርስቅላና አቂላም አብረውት ነበሩ፤ ስእለትም ነበረበትና በክንክራኦስ ራሱን ተላጨ።'),
  ('53d029dc-2463-525f-aff3-a7d62da63b90', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 19, 19, 'ወደ ኤፌሶንም ደረሱ፤ በዚያም ተዋቸውና እርሱ ብቻውን ወደ ምኵራብ ገብቶ አይሁድን ተከራከራቸው።'),
  ('ec39892b-f088-5555-a5de-cfd5cc7146bc', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 20, 20, 'እነርሱም ብዙ ጊዜ እንዲሰነብት ማለዱት፤ ነገር ግን አልወደደም።'),
  ('91f6ba9e-a304-5cee-a2df-dd340d412f0b', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 21, 21, 'ከዚህም በኋላ በሚሸኙት ጊዜ፥ “እግዚአብሔር ቢፈቅድ እንደገና እመለሳለሁ፤ አሁን ግን የሚመጣውን በዓል በኢየሩሳሌም ላደርግ እወዳለሁ” አላቸው፤ ከኤፌሶንም በመርከብ ሄደ።'),
  ('055d7d9e-39f1-5e45-a838-7b54ffa671e7', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 22, 22, 'ወደ ቂሳርያም ደረሰ፤ ከዚያም ወጥቶ ለቤተ ክርስቲያን ሰላምታ ከሰጠ በኋላ ወደ አንጾኪያ ሄደ።'),
  ('2aa6289d-e4f8-5069-aba2-4fdf1cbbf88c', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 23, 23, 'ጥቂት ቀንም ተቀመጠ፤ ከዚያም ወጥቶ በገላትያና በፍርግያ በኩል በተራ እየዞረ ሄደ፤ ደቀ መዛሙርትንም አጸናቸው።'),
  ('3f5937e7-10c0-516c-a136-1f6949dcebc3', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 24, 24, 'በእስክንድርያም የሚኖር፥ ንግግር የሚችልና መጽሐፍን የሚያውቅ አጵሎስ የሚባል አንድ አይሁዳዊ ሰው ወደ ኤፌሶን መጣ።'),
  ('bdfeea0d-69be-532e-ac20-f71a57b86de0', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 25, 25, 'እርሱም የእግዚአብሔርን መንገድ የተማረ ነበር፤ ስለ ኢየሱስ ክርስቶስም ሊያስተምርና ሊመሰክር ከልቡ የሚተጋ ነበር፤ ነገር ግን የዮሐንስን ጥምቀት ብቻ ተጠምቆ ነበር።'),
  ('69249c65-73e5-5805-a7af-07cf6523f9e7', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 26, 26, 'እርሱም በምኵራብ በግልጥ ይናገር ጀመር፤ ጵርስቅላና አቂላም በሰሙት ጊዜ ወደ ማደሪያቸው ወስደው ፍጹም የእግዚአብሔርን መንገድ አስረዱት።'),
  ('103cff3c-453b-5f01-a81e-8d1b278a68f4', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 27, 27, 'ወደ አካይያም ሊሄድ በወደደ ጊዜ ወንድሞች አጽናኑት፤ እንዲቀበሉትም ወደ ደቀ መዛሙርት ጻፉለት፤ ወደ እነርሱም በደረሰ ጊዜ፥ በእግዚአብሔር ጸጋ ላመኑት ብዙ አስተማራቸው፤ ትልቅ ርዳታም ረዳቸው።'),
  ('b5584389-bc65-5ee7-a4c1-dc27665f9ca9', '37fe09da-0e96-5cf3-a120-83f31be01745', '39875f6f-d1bf-5ad7-add9-b46862f300ca', 28, 28, 'ተሰብስበው ሳሉም በሕዝቡ ሁሉ ፊት አይሁድን በግልጥ እጅግ ይከራከራቸው ነበር፤ ስለ ኢየሱስም እርሱ ክርስቶስ እንደ ሆነ ከመጻሕፍት ማስረጃ ያመጣላቸው ነበር።'),
  ('8d9a3fd9-4e08-5d30-a769-20cd0cc15546', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 1, 1, 'ከዚህም በኋላ አጵሎስ በቆሮንቶስ ሳለ፥ ጳውሎስ ላይ ላዩን ሄዶ ወደ ኤፌሶን መጣ፤ በዚያም ጥቂት ደቀ መዛሙርትን አገኘ።'),
  ('1497c821-b8c1-5e07-a6db-cedf6d7bd82d', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 2, 2, '“ካመናችሁ ጀምሮ በውኑ መንፈስ ቅዱስን ተቀብላችኋልን?” አላቸው፤ እነርሱም፥ “አልተቀበልንም መንፈስ ቅዱስ እንዳለ ስንኳ አልሰማንም” አሉት።'),
  ('0cf6376d-38b5-5652-a6c2-13d38f5e83c9', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 3, 3, 'እርሱም፥ “እንኪያ በምን ተጠመቃችሁ?” አላቸው፤ እነርሱም፥ “በዮሐንስ ጥምቀት” አሉት።'),
  ('32b6e442-7a0a-55b5-a42f-845dbeb7fb84', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 4, 4, 'ጳውሎስም፥ “ዮሐንስ ከእርሱ በኋላ በሚመጣው በኢየሱስ ክርስቶስ እንዲያምኑ እየሰበከ የንስሓ ጥምቀትን አጠመቀ” አላቸው።'),
  ('9bedcb4a-c759-524e-a5c5-3fdb3d542e7b', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 5, 5, 'እነርሱም ይህን በሰሙ ጊዜ በጌታችን በኢየሱስ ክርስቶስ ስም ተጠመቁ።'),
  ('2c2a32f5-c2b5-5fa1-aaa0-598a66b284c5', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 6, 6, 'ጳውሎስም እጁን በጫነባቸው ጊዜ መንፈስ ቅዱስ በእነርሱ ላይ ወረደ፤ ያንጊዜም በሀገሩ ሁሉ ቋንቋ ተናገሩ፤ ትንቢትም ተናገሩ።'),
  ('afc92455-1273-5e16-a362-6bea1f04870d', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 7, 7, 'ሰዎቹም ሁሉ ዐሥራ ሁለት ያህሉ ነበር።'),
  ('0e0d65fd-7aa9-5792-a536-84c8bbe27f73', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 8, 8, 'ጳውሎስም ወደ ምኵራብ ገብቶ በግልጥ አስተማረ፤ ስለ እግዚአብሔርም መንግሥት እያስተማራቸውና እያሳመናቸው ሦስት ወር ቈየ።'),
  ('6df07031-1f82-5e2f-abba-e3bb6a004f2d', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 9, 9, 'በተሰበሰበውም ሕዝብ ፊት አንዳንዶች በእግዚአብሔር ትምህርት ላይ ክፉ እየተናገሩ ባላመኑ ጊዜ፥ ጳውሎስ ከእነርሱ ተለየ፤ ደቀ መዛሙርቱንም ይዞ ጢራኖስ በሚባል መምህር ቤት ሁልጊዜ ያስተምራቸው ነበር።'),
  ('29de85fc-3445-5981-a54a-64296b42d25e', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '8836c27a-3b33-5f43-a076-2d84eb63e225', 10, 10, 'በእስያም ያሉ አይሁድና አረማውያን ሁሉ የእግዚአብሔርን ቃል እስኪሰሙ ድረስ እንደዚሁ ሁለት ዓመት ኖረ።'),
  ('516b6ad9-ec12-584b-a41d-21f7491a787c', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 1, 11, 'እግዚአብሔርም በጳውሎስ እጅ ታላላቅ ሥራን ይሠራ ነበር።'),
  ('cd7469b8-eee2-5ace-a025-0e04d9ef732a', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 2, 12, 'ከልብሱ ዘርፍና ከመጠምጠሚያዉ ጫፍ ቈርጠው እየወሰዱ በድውያኑ ላይ ያኖሩት ነበር፤ እነርሱም ይፈወሱ ነበር፤ ክፉዎች መናፍስትም ይወጡ ነበር።'),
  ('23cb37de-437a-5e29-a1ae-f953fc961a4a', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 3, 13, 'ከአይሁድም አስማት እያደረጉ የሚዞሩ ሰዎች ክፉዎች መናፍስት ባሉባቸው ላይ “ጳውሎስ በሚያስተምርበት በኢየሱስ ስም እናምላችኋለን” እያሉ የጌታችን የኢየሱስን ስም ይጠሩባቸው ነበር።'),
  ('f979a7be-e0bd-52cf-affc-55057423b297', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 4, 14, 'እኒህ እንዲህ ያደርጉ የነበሩትም የካህናቱ አለቃ የአይሁዳዊው የአስቂዋ ልጆች ናቸው፤ እነርሱም ሰባት ነበሩ።'),
  ('2603d94f-a0a8-52c4-a2a4-2208d04b13f1', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 5, 15, 'ያም ክፉ መንፈስ፥ “በኢየሱስ አምናለሁ፥ ጳውሎስንም አውቀዋለሁ፤ እንግዲህ እናንተ እነማን ናችሁ?” ብሎ መለሰላቸው።'),
  ('bd53c2f7-928f-5412-af5b-aaeccb143d13', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 6, 16, 'ያም ክፉ መንፈስ የያዘው ሰው ተነሣባቸው፤ አየለባቸውም፤ አሸነፋቸውም፤ አቍስሎም ከዚያ ቤት አስወጥቶ አባረራቸው።'),
  ('cff7771d-5c22-5cb3-a369-434367d65fe5', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 7, 17, 'ይህም ነገር በኤፌሶን በሚኖሩ በአይሁድና በአረማውያን ሁሉ ዘንድ ተሰማ፤ ሁሉም ፈሩ፤ የጌታችን የኢየሱስንም ስም ከፍ ከፍ አደረጉ።'),
  ('56d4d031-cafe-523d-a7d8-9787880b587d', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 8, 18, 'ያመኑትም ሁሉ እየመጡ ስለ ሠሩት ንስሓ ይገቡ ነበር።'),
  ('96df042a-5218-5b25-ae48-2c806fa853cd', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 9, 19, 'ብዙዎች አስማተኞችም መጽሐፎቻቸውን እየሰበሰቡ እያመጡ በሕዝቡ ሁሉ ፊት በእሳት ያቃጥሉ ነበር፤ ያቃጠሏቸው የመጽሐፎች ዋጋም አምሳ ሺህ ብር ነበር።'),
  ('d348a595-8d4f-521d-ad15-c33463fdde7d', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 10, 20, 'እንዲህም እያለ የእግዚአብሔር ቃል በኀይል ያድግና ይበረታ ነበር።'),
  ('d53e85a0-5196-53a3-a06d-d0c686af1301', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 11, 21, 'ይህም ከተፈጸመ በኋላ ጳውሎስ በመቄዶንያና በአካይያ በኩል አልፎ ወደ ኢየሩሳሌም ሊሄድ በልቡ ዐሰበ፥ “እዚያም ከደረስሁ በኋላ ሮሜን ላያት ይገባኛል” አለ።'),
  ('a33a0c08-d9ed-51a5-ad83-157f2f389de6', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '0605c713-f540-5d42-aca8-b2c1f281d298', 12, 22, 'ከሚያገለግሉትም ሁለቱን ጢሞቴዎስንና አርስጦስን ወደ መቄዶንያ ላከ፤ እርሱ ራሱ ጳውሎስ ግን ብዙ ቀን በእስያ ተቀመጠ።'),
  ('be80c11c-7555-5df8-a8ec-b9fb1c2fef42', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 1, 23, 'በዚያም ወራት ስለዚህ ትምህርት ብዙ ሁከት ሆነ።'),
  ('071ec2c9-28c4-59e6-ae79-7027e64b1a8e', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 2, 24, 'በዚያም ብር ሠሪ የሆነ ድሜጥሮስ የሚባል አንድ ሰው ነበር፤ ለአርጤምስም ከብር የቤተ መቅደስ ምስል ይሠራ ነበር፤ አንጥረኞችንም እያሠራ ብዙ ገንዘብ ይሰጣቸው ነበር።'),
  ('dcc20f0c-5717-58c2-a537-47191f8213dc', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 3, 25, 'አንጥረኞችንና ይህን የመሰለውን ሥራ የሚሠሩትንም ሁሉ ሰብስቦ እንዲህ አላቸው፥ “እናንተ ሰዎች ሆይ፥ ጥቅም የምናገኘው በዚህ ሥራችን እንደ ሆነ እናንተ ታውቃላችሁ።'),
  ('ab9d179e-4c98-513d-aaf5-34dece6d7680', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 4, 26, 'አሁን ግን እንደምታዩትና እንደምትሰሙት ይህ ጳውሎስ ኤፌሶንን ብቻ ሳይሆን መላውን እስያን አሳተ፤ ብዙ ሕዝብንም መለሰ፤ በሰው እጅ የሚሠሩትንም ሁሉ አማልክት አይደሉም አላቸው።'),
  ('7d4b8f2e-2c69-5e3e-a182-04c3db657940', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 5, 27, 'አሁን የምንቸገር በዚህ ነገር ብቻ አይደለም፤ እስያና መላው ዓለም የሚያመልካት የታላቋ የአርጤምስም መቅደስ ክብር ይቀራል፤ ገናናነቷም ይሻራል።”'),
  ('998a7d50-1fb1-5c79-aceb-8d7d1bca77f9', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 6, 28, 'ይህንም በሰሙ ጊዜ ተቈጡና ድምፃቸውን ከፍ አድርገው፥ “የኤፌሶን አርጤምስ ክብርዋ ታላቅ ነው” አሉ።'),
  ('b69e987b-4f58-5052-aa46-7958a0abe43f', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 7, 29, 'ከተማውም ሁሉ ታወከ፤ የመቄዶንያን ሰዎች የጳውሎስን ወዳጆች ጋይዮስንና አርስጥሮኮስንም ከእነርሱ ጋር እየጐተቱበአንድነት ወደ ጨዋታው ቦታ ሮጡ።'),
  ('2d5fee37-6369-5fa8-a8a1-535190624aae', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 8, 30, 'ጳውሎስም ወደ አሕዛብ መካከል ሊገባ ወድዶ ነበር፤ ነገር ግን ደቀ መዛሙርት ከለከሉት።'),
  ('6a77fc65-de0e-5580-a772-a91b02648fc5', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 9, 31, 'ከእስያም የሆኑ ታላላቆች ወዳጆቹ ወደ ጨዋታው ቦታ እንዳይገባ ልከው ማለዱት።'),
  ('3a3a5d19-8a14-5b6b-aa74-9710c12e4c89', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 10, 32, 'በዚያም በጨዋታው ቦታ የነበሩ ሰዎች እየጮኹ ቈዩ፤ በሌላም ቋንቋ የሚጮሁ ነበሩ፤ በጉባኤው ታላቅ ድብልቅልቅ ሆኖ ነበርና፤ ከእነርሱ የሚበዙት ግን በምን ምክንያት እንደ ተሰበሰቡ አያውቁም ነበር።'),
  ('93972f27-8898-5e67-ac07-c1e1f17f34a6', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 11, 33, 'በዚያ የነበሩ አይሁድም እስክንድሮስ የሚባል አይሁዳዊ ሰውን ከመካከላቸው አስነሡ፤ እርሱም ተነሥቶ በእጁ ምልክት ሰጠና ለሕዝቡ ሊከራከርላቸው ወደደ።'),
  ('f0e466f9-2a39-5bd4-a5cd-7d26fbd0a71b', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 12, 34, 'አይሁዳዊ እንደሆነም ባወቁ ጊዜ “የኤፌሶን አርጤምስ ክብርዋ ታላቅ ነው” እያሉ ሁለት ሰዓት ያህል ሁሉም በአንድ ድምፅ ጮሁ።'),
  ('b7540fa8-245e-54ed-abd7-5d290cee82a5', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 13, 35, 'ከዚህም በኋላ የከተማው ጸሓፊ ተነሥቶ ሕዝቡን ጸጥ አሰኝቶ እንዲህ አላቸው፥ “እናንተ የኤፌሶን ሰዎች ሆይ፥ ስሙ፤ የኤፌሶን ከተማ ታላቂቱን አርጤምስንና ከሰማይ የወረደውን ጣዖትዋን እንደምትጠብቅ የማያውቅ ማነው?'),
  ('b231010b-d3df-5fda-a9ec-a6ec5f16fb56', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 14, 36, 'ስለዚህም እርስዋን መቃወም የሚቻለው ያለ አይመስለኝም፤ አሁንም ይህን በጠብና በክርክር ሳይሆን በቀስታ ልናደርገው ይገባናል።'),
  ('549048f2-ff6d-53d5-a42f-161702d0e356', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 15, 37, 'የአማልክትን ቤት ያልዘረፉትንና በአማልክቶቻችን ላይ ክፉ ቃልን ያልተናገሩትን እነዚህን ሰዎች እነሆ ወደ እዚህ አምጥታችኋቸዋል።'),
  ('13c368c6-af80-5de2-a82c-2114fe0e0166', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 16, 38, 'ድሜጥሮስና ከእርሱ ጋር ያሉ አንጥረኞች ግን በማንም ላይ ጠብ እንዳላቸው እርስ በርሳቸው ይከራከሩ፤ እነሆም በከተማው ውስጥ ፍርድ ቤት አለ፤ ዳኞችም አሉ።'),
  ('0fd41335-a858-5a3e-ac01-60baaabb90cd', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 17, 39, 'ነገር ግን ይህ የምትከራከሩበት ነገር ሌላ ከሆነ በሕግ ሸንጎ ይፈታል።'),
  ('4bcc19a8-a037-55db-a929-b1041d3360e6', '8b08089e-27e6-50d3-a6d6-f42ae1a59033', '86cacad0-c96f-539b-a817-463a23abe4e7', 18, 40, 'ዛሬም በደል ሳይኖር በአመጣችሁብን ክርክር እኛ እንቸገራለንና ስለዚህ ክርክር የምንወቃቀሰው ነገር የለም፥” ይህንም ብሎ ሸንጎውን ፈታ።'),
  ('ce58468d-12aa-5b9c-a61b-6152ed65aa14', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '4acaf071-36d2-5309-a6ef-477dbe3cfec1', 1, 1, 'ክርክሩም ከተፈጸመ በኋላ ጳውሎስ ደቀ መዛሙርቱን ጠራና አጽናናቸው፤ ተሰናበታቸውም፤ ወጥቶም ወደ መቄዶንያ ሄደ።'),
  ('32462fe4-93c1-50b6-ae42-e2a991775ae5', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '4acaf071-36d2-5309-a6ef-477dbe3cfec1', 2, 2, 'በዚያ አውራጃም አልፎ ሄደ፤ በቃሉም ብዙ አስተማራቸው፤ ከዚያም በኋላ ወደ ግሪክ ሀገር ሄደ።'),
  ('5bc48b8e-568f-56f8-a2d3-c0a06fc2255e', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '4acaf071-36d2-5309-a6ef-477dbe3cfec1', 3, 3, 'በዚያም ሦስት ወር ተቀመጠ፤ ወደ ሶርያም በመርከብ ለመሄድ ዐስቦ ሳለ አይሁድ ስለ ተማከሩበት ወደ መቄዶንያ ሊመለስ ቈረጠ።'),
  ('4e07bec5-4739-5d4e-a374-cebf9611abcc', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '4acaf071-36d2-5309-a6ef-477dbe3cfec1', 4, 4, 'ከእርሱም ጋር የቤርያ ሀገር ሰው የሚሆን ሱሲጳጥሮስ፥ የተሰሎንቄም ሰዎች አርስጥሮኮስና ሲኮንዱስ፥ የደርቤኑ ሰው ጋይዮስና ጢሞቴዎስም፥ የእስያ ሰዎች የሚሆኑ ቲኪቆስና ጥሮፊሞስም አብረውት ሄዱ።'),
  ('d231473d-c86a-5330-aae9-2b05cf1d0a43', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '4acaf071-36d2-5309-a6ef-477dbe3cfec1', 5, 5, 'እነርሱም ቀድመውን ሄደው በጢሮአስ ቆዩን።'),
  ('b601572d-a72a-53c7-afa0-074587fe4418', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 1, 6, 'እኛ ግን ከፋሲካ በኋላ ከፊልጵስዩስ ተነሥተን በባሕር ላይ ተጕዘን በአምስት ቀን ወደ ጢሮአስ ደረስን፤ በዚያም ሰባት ቀን ተቀመጥን።'),
  ('ee995bd4-6753-5cdf-aabe-0491ef0953d1', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 2, 7, 'ከሳምንቱም በመጀመሪያው ቀን እሑድ ማዕድ ለመባረክ ተሰብስበን ሳለን ጳውሎስ በማግሥቱ የሚሄድ ነውና ያስተምራቸው ጀመረ፤ እስከ መንፈቀ ሌሊትም ድረስ ትምህርቱን አስረዘመ።'),
  ('541dc506-0a00-55fc-abfd-03d1040c1660', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 3, 8, 'ተሰብስበን በነበርንበት ሰገነትም ብዙ መብራት ነበር።'),
  ('afd937b4-7c07-5d9b-aa27-24d05ffffd4e', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 4, 9, 'ስሙ አውጤክስ የሚባል አንድ ጐልማሳ ልጅም በመስኮት በኩል ተቀምጦ ሳለ ከባድ እንቅልፍ አንቀላፍቶ ነበር፤ ጳውሎስም ትምህርቱን ባስረዘመ ጊዜ ያ ጐልማሳ ከእንቅልፉ ብዛት የተነሣ ከተኛበት ከሦስተኛው ፎቅ ወደ ታች ወደቀ፤ ሬሳውንም አነሡት።'),
  ('118b20f6-87f0-58c8-ab54-f65190c9365b', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 5, 10, 'ጳውሎስም ወርዶ በላዩ ወደቀ፤ አቅፎም ያዘው፤ እነርሱንም፥ “ነፍሱ አለችና አትደንግጡ” አላቸው።'),
  ('87874ecc-ffab-5494-a2d3-458b6fb35fba', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 6, 11, 'ከዚህም በኋላ ወደ ሰገነት ወጣ፤ ማዕዱንም ባርኮ በላ፤ እስኪነጋም ድረስ ብዙ ትምህርት አስተማራቸው፤ ከዚያ በኋላም ተነሥቶ ሄደ።'),
  ('4410adbc-f53e-5d40-a890-86784dee4898', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 7, 12, 'ብላቴናውንም ደኅና ሆኖ ወሰዱት፤ እጅግም ደስ አላቸው።'),
  ('0cc75d33-9958-592b-a19e-13f2679d299f', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 8, 13, 'እኛ ግን በመርከብ ሆነን ወደ አሶስ ሄድን፤ ከዚያ ጳውሎስን ልንቀበለው እንሻ ነበርና፤ እንደዚሁ በእግር እንደሚመጣ ነግሮን ነበርና ተቀበልነው።'),
  ('32041582-cd81-5916-a6b3-080e22190839', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 9, 14, 'አሶስም ደረስን፤ በመርከብም ይዘነው ወደ ሚጢሊኒ ሄድን።'),
  ('965aadaa-5338-5119-ac03-a3c5c7e0f318', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 10, 15, 'በማግሥቱም ከዚያ ወጥተን በኪዮስ ፊት ለፊት ደረስን፤ በማግሥቱም ወደ ሳሞስ አለፍን፤ በትሮጊሊዮም ተቀመጥን፤ ከዚህ ቀን በኋላም ወደ መሊጡ ደረስን።'),
  ('b806671f-a781-511e-a08f-ab634d97afbf', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 11, 16, 'ጳውሎስም በእስያ እንዳይዘገይ በኤፌሶን በኩል ሊሄድ ቈርጦ ነበር፤ የሚቻለውም ቢሆን ለበዓለ ኀምሳ ኢየሩሳሌም ለመድረስ ቸኵሎ ነበርና።'),
  ('adc8d315-7643-5b61-ac7e-32d004b7d8bc', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 12, 17, 'ከመሊጡም የቤተ ክርስቲያንን ቀሳውስት ይጠሩአቸው ዘንድ ወደ ኤፌሶን ላከ።'),
  ('a427ecec-c544-5a20-a29d-fc154a80e954', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 13, 18, 'ወደ እርሱም በመጡ ጊዜ እንዲህ አላቸው፥ “ወደ እስያ ከገባሁበት ከመጀመሪያው ቀን ጀምሮ በዘመኑ ሁሉ ከእናንተ ዘንድ እንደ ተቀመጥሁ እናንተ ታውቃላችሁ።'),
  ('4308e529-4760-5ea1-a085-dc03ca20c941', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 14, 19, 'እግዚአብሔርን እያገለገልሁ በፍጹም መከራና በልቅሶ ከአይሁድም ሴራ የተነሣ በደረሰብኝ ፈተና እየተጋደልሁ፥'),
  ('6abded07-52a1-5fa9-af4c-ce441c16c6fa', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 15, 20, 'በጉባኤም ሆነ በቤት ስነግራችሁና ሳስተምራችሁ ከሚጠቅማችሁ ነገር አንዳች ስንኳን አላስቀረሁባችሁም።'),
  ('6cdcdb82-985d-537b-a482-108b5deeca82', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 16, 21, 'ወደ እግዚአብሔር መመለስንና በጌታችን በኢየሱስ ክርስቶስ ማመንን ለአይሁድና ለአረማውያን እየመሰከርሁ፤'),
  ('ef210ea6-ac45-58c9-a34d-3b8c862b9734', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 17, 22, 'አሁንም እነሆ በመንፈስ ታሥሬ ወደ ኢየሩሳሌም እሄዳለሁ፤ ነገር ግን በዚያ የሚያገኘኝን አላውቅም።'),
  ('c2987bc3-3fd1-5d76-af24-69aed47e5a21', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 18, 23, 'ነገር ግን መንፈስ ቅዱስ፦ በየከተማው መከራና እስራት ይጠብቅሃል ብሎ ይመሰክርልኛል።'),
  ('488d8ea6-f6ae-5f28-ae38-f911cd0e3d37', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 19, 24, 'ነገር ግን የእግዚአብሔርን የጸጋውን ወንጌል እንዳስተምር ከጌታችን ከኢየሱስ ክርስቶስ የተቀበልሁትን ሩጫዬን እንድጨርስና መልእክቴንም እንድፈጽም ነው እንጂ ለሰውነቴ ምንም አላስብላትም።'),
  ('3a73949c-4e6b-5c96-abfb-ac8ec9250838', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 20, 25, 'አሁንም እነሆ፥ የእግዚአብሔርን መንግሥት የሰበክሁላችሁ እናንተ ሁላችሁ ከእንግዲህ ወዲህ ፊቴን እንደማታዩኝ እኔ ዐውቄአለሁ።'),
  ('ea276433-a0b8-5142-ac47-704985876ec7', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 21, 26, 'እኔ ከሁላችሁም ደም ንጹሕ እንደ ሆንሁ እነሆ ዛሬ በዚች ሌሊት እመሰክርላችኋለሁ።'),
  ('bcaf9331-90c8-5d9c-ac3f-0df471fb242e', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 22, 27, 'ከእግዚአብሔር ምክር ሁሉ የሰወርኋችሁና ያልነገርኋችሁ የለም።'),
  ('6144c446-79f3-5023-a4de-300d089af994', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 23, 28, 'አሁንም በገዛ ደሙ የዋጃትን የእግዚአብሔርን ቤተ ክርስቲያን ትጠብቁ ዘንድ መንፈስ ቅዱስ እናንተን ጳጳሳት አድርጎ ለሾመባት ለመንጋው ሁሉና ለራሳችሁ ተጠንቀቁ።'),
  ('009b6999-9a1a-56ea-aeb7-bdadfdf3ba8a', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 24, 29, 'ከእኔ በኋላ ለመንጋዪቱ የማይራሩ ነጣቂዎች ተኵላዎች እንደሚመጡ እኔ አውቃለሁ።'),
  ('30d91981-1b14-5fdb-a539-5b60336da4c7', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 25, 30, 'ደቀ መዛሙርትንም ወደ እነርሱ ይመልሱ ዘንድ ጠማማ ትምህርትን የሚያስተምሩ ሰዎች ከእናንተ መካከል ይነሣሉ።'),
  ('4a7432d3-fd59-5359-a89b-976a9e017576', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 26, 31, 'ስለዚህም ትጉ፤ እኔ ሁላችሁንም ሳስተምር ሦስት ዓመት ሙሉ ሌትም ቀንም እንባዬ እንዳልተገታ ዐስቡ።'),
  ('229e1534-530c-53a3-a7df-28b43568e626', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 27, 32, 'አሁንም ለእግዚአብሔርና ሊያንጻችሁ፥ በቅዱሳንም ሁሉ መካከል ርስትን ሊሰጣችሁ ለሚችለው ለጸጋው ቃል አደራ ሰጥቻችኋለሁ።'),
  ('59e31ba9-7d1c-54f8-a9a1-e7651fadafbf', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 28, 33, 'ወርቅም ቢሆን፥ ብርም ቢሆን፥ ልብስም ቢሆን ከእናንተ ከአንዱ ስንኳ አልተመኘሁም።'),
  ('3aa2c96f-63e1-5680-a836-564b122258f4', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 29, 34, 'እነዚህም እጆች ለምሻው ነገርና ከእኔም ጋር ላሉት እንዳገለገሉ እናንተ ታውቃላችሁ።'),
  ('eef4a69b-b4e5-5f70-aabb-90cbcb1014d5', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 30, 35, 'በድካማችንና በሥራችን ነዳያንን እንቀበላቸው ዘንድ እንደሚገባን ይህን አስተምሬአችኋለሁ፤ ‘ከሚቀበል ይልቅ የሚሰጥ ብፁዕ ነው’ ያለውንም የጌታችንን የኢየሱስን ቃል ዐስቡ።”'),
  ('2cedbf8b-8ba6-5935-aa09-0cdd99519395', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 31, 36, 'ይህንም ከአለ በኋላ ተንበርክኮ አብረውት ካሉት ሁሉ ጋር ጸለየ።'),
  ('c7d9ef66-8f75-5a3b-a788-737b81a3771e', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 32, 37, 'ሁሉም እጅግ አለቀሱ፤ ጳውሎስንም አንገቱን አቅፈው ሳሙት።'),
  ('21e570e8-581b-5943-aefc-7163d0ce9483', '8bb04c16-79f3-5e43-afb5-d8fade94b79a', '7d6b51fe-2af1-5aa7-af56-9bf48e05e383', 33, 38, 'ይልቁንም “ከእንግዲህ ወዲህ ፊቴን አታዩትም” ስለ አላቸው እጅግ አዘኑ። እስከ መርከብም ድረስ ሸኙት።'),
  ('1b5e9a3a-2afe-58db-acb7-b86f89458503', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 1, 1, 'ከእነርሱም ከተለየን በኋላ እኛ በመርከብ ተሳፍረን፥ መንገዳችንንም አቅንተን ወደ ቆስ መጣን፤ በበነጋውም ወደ ሮዶስ፥ ከዚያም ወደ ጳጥራ ገባን።'),
  ('36b0dabd-6505-548c-a8b6-1c0077dffad8', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 2, 2, 'ወደ ፊንቄም የሚያልፍ መርከብ አግኝተን በዚያ ላይ ተሳፍረን ሄድን።'),
  ('e2ffb43c-e539-5dfc-a586-e16417f49b2d', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 3, 3, 'ቆጵሮስንም አየናት፤ በስተ ግራችንም ትተናት ወደ ሶርያ ሄድን፤ ወደ ጢሮስም ወረድን፤ በመርከብ ያለውን ጭነት ሁሉ በዚያ ያራግፉ ነበርና።'),
  ('b11f824c-7b0b-5a1e-acdb-d20387c053ff', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 4, 4, 'በዚያም ደቀ መዛሙርትን አገኘንና በእነርሱ ዘንድ ሰባት ቀን ተቀመጥን፤ እነርሱም በመንፈስ ቅዱስ ተገልጾላቸው ጳውሎስን ወደ ኢየሩሳሌም እንዳይወጣ ነገሩት።'),
  ('821a0fd9-553c-54c3-a05f-d6e849c69001', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 5, 5, 'ከዚህም በኋላ ለመሄድ ወጣን፤ ሁሉም ከሚስቶቻቸውና ከልጆቻቸው ጋር እስከ ከተማው ውጭ ሸኙን፤ በባሕሩም ዳር ተንበርክከን ጸለይን።'),
  ('24667b73-63e4-5184-acca-c22ffb06e587', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 6, 6, 'እርስ በርሳችንም ተሳስመን ተሰነባበትን፤ ከዚህም በኋላ ወደ መርከብ ወጣን፤ እነርሱም ወደ ቤታቸው ተመለሱ።'),
  ('317bf267-8ae5-5466-ae2e-1ec6964b4073', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 7, 7, 'እኛም ከጢሮስ ወጥተን አካ ወደምትባል ሀገር መጣን፤ ወንድሞቻችንንም አግኝተን ሰላም አልናቸው፤ በእነርሱም ዘንድ አንድ ቀን አደርን።'),
  ('d9949979-aa0e-5ea8-a130-3358b16304b6', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 8, 8, 'በማግሥቱም ወጥተን ወደ ቂሳርያ ሄድን፤ ወደ ወንጌላዊው ወደ ፊልጶስ ቤትም ገባን፤ እርሱም ከሰባቱ ወንድሞች ዲያቆናት አንዱ ነው።'),
  ('7de0f7b2-8066-5cf2-add3-263d4ac573c7', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 9, 9, 'ለእርሱም ትንቢት የሚናገሩ አራት ደናግል ሴቶች ልጆች ነበሩት።'),
  ('018bd48a-ed91-5796-a524-c77251805643', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 10, 10, 'በእርሱም ዘንድ ብዙ ቀን ኖርን፤ ከይሁዳም አጋቦስ የሚባል አንድ ነቢይ ወረደ።'),
  ('51e7f30b-0508-542b-aa04-d201cf513f22', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 11, 11, 'ወደ እኛም መጣና የጳውሎስን መታጠቂያ አንሥቶ እጁንና እግሩን በገዛ እጁ አስሮ እንዲህ አለ፥ “መንፈስ ቅዱስ እንዲህ ይላል፤ የዚህን መታጠቂያ ጌታ አይሁድ በኢየሩሳሌም እንዲህ ያስሩታል፤ ለአሕዛብም አሳልፈው ይሰጡታል።”'),
  ('b0d5f1b0-4303-586a-a5ed-d484224438c9', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 12, 12, 'ይህንም ሰምተን የሀገሪቱን ሰዎች ይዘን ወደ ኢየሩሳሌም እንዳይወጣ ጳውሎስን ማለድነው።'),
  ('f52a1f67-f64a-57f8-adbd-5db17dbbf884', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 13, 13, 'ጳውሎስ ግን መልሶ፥ “ለምን እንዲህ ታደርጋላችሁ? እያለቀሳችሁ ልቤን ትሰብሩታላችሁ፤ እኔ እኮ ተስፋ የማደርገው መከራንና እግር ብረትን ብቻ አይደለም፤ እኔ ግን በጌታችን በኢየሱስ ክርስቶስ ስም በኢየሩሳሌም ለመሞትም ቢሆን የቈረጥሁ ነኝ” አለ።'),
  ('c89bfe31-74d3-5a2c-ae06-c212b14e8185', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 14, 14, 'እንቢ ባለ ጊዜም ዝም አልን፤ እኛም እግዚአብሔር የፈቀደው ይሁን ብለን ተውነው።'),
  ('f5c87b11-89bb-5036-a9f2-ed73cf214809', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 15, 15, 'ከእነዚያም ቀኖች በኋላ ተዘጋጅተን ወደ ኢየሩሳሌም ወጣን።'),
  ('4ce82c08-70a9-5023-a61d-450fa9cd664d', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 16, 16, 'ከደቀ መዛሙርትም ከቂሳርያ አብረውን የመጡ ነበሩ፤ ሄደንም ከመጀመሪያዎቹ ደቀ መዛሙርት ወገን ከሆነው በቆጵሮስ በሚኖረው በምናሶን ቤት አደርን።'),
  ('2a011937-e8fa-5784-a238-d318081948e1', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 17, 17, 'ኢየሩሳሌም በደረስን ጊዜም ወንድሞቻችን በደስታ ተቀበሉን።'),
  ('98692b91-aeef-5c14-a29c-8a5c075772ea', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 18, 18, 'በማግሥቱም ጳውሎስ ከእኛ ጋር ወደ ያዕቆብ ገባ፤ ቀሳውስትም ሁሉ በዚያ ነበሩ።'),
  ('64313ff7-d05c-542e-ab9b-89c2a415c0a4', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 19, 19, 'ጳውሎስም ሰላምታ ካቀረበላቸው በኋላ በእርሱ ሐዋርያነት እግዚአብሔር በአሕዛብ ያደረገውን ሁሉ ነገራቸው።'),
  ('02d16bdd-4310-50c3-ae3e-e2adcaa52287', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 20, 20, 'እነርሱም ሰምተው እግዚአብሔርን አመሰገኑ፤ እንዲህም አሉ፥ “ወንድማችን ሆይ፥ ከአይሁድ መካከል ያመኑት ስንት አእላፋት እንደ ሆኑ ታያለህን? ሁሉም ለኦሪት የሚቀኑ ናቸው።'),
  ('e0e5da35-a0df-5cb4-a78a-0367477ac290', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 21, 21, 'ነገር ግን የማይሆነውን እንደምታስተምር፥ የሙሴንም ሕግ እንደምታስተዋቸው፥ በአሕዛብ መካከል ያሉ ያመኑ አይሁድንም ልጆቻቸውን እንዳይገርዙ፥ የኦሪትንም ሕግ እንዳይፈጽሙ እንደምትከለክላቸው ስለ አንተ ነግረዋቸዋል።'),
  ('9961bfa8-c990-5af2-abf2-12cbebe49642', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 22, 22, 'አሁንሳ ምን ይሁን? ሕዝቡ ወደዚህ እንደ መጣህ ይሰሙና ይሰበሰቡ ይሆናል።'),
  ('c6abb2ab-3fb6-5108-a819-c880d8247da3', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 23, 23, 'ስለዚህም ይህን የምልህን አድርግ፦ ብፅዐት ያላቸው አራት ሰዎች በእኛ ዘንድ አሉ።'),
  ('c90d9bc2-6bb1-5182-ab4c-647c14103c51', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 24, 24, 'ይዘሃቸው ሂድ፤ ከእነርሱም ጋር ራስህን አንጻ፤ ራሳቸውንም እንዲላጩ ስለ እነርሱ ገንዘብ ክፈልላቸው፤ የሚያሙህም በሐሰት እንደ ሆነ፥ አንተም የኦሪትን ሕግ እንደምትጠብቅ ሁሉም ያውቃሉ።'),
  ('08bf9b4e-37fb-5fae-a8c0-eabbced75e5b', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 25, 25, 'ስለሚአምኑት አሕዛብ ግን እርም ከሆነውና ለጣዖታት ከሚሠዉት፥ ከዝሙት፥ ሞቶ የተገኘውንና ደምን ከመብላት እንዲከለከሉ እኛ አዝዘናል።”'),
  ('de3140b1-8fed-5adb-ac81-39dc94a71723', 'dbd35292-5306-57fb-a927-176de45849f8', 'aef4688e-e41f-5dbd-af6a-231cf4727cc5', 26, 26, 'ያንጊዜም ጳውሎስ ሰዎችን ይዞ በማግሥቱ ከእነርሱ ጋር ነጻ። የመንጻታቸውንም ወራት መድረሱን ከነገራቸው በኋላ ሁሉም እየአንዳንዳቸው መሥዋዕት ያቀርቡ ዘንድ ወደ ቤተ መቅደስ ይዞአቸው ገባ።'),
  ('3d680f0f-1b5f-516a-ac83-3f79c03541de', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 1, 27, 'በሰባተኛውም ቀን ከእስያ የመጡ አይሁድ ጳውሎስን በመቅደስ አዩት፤ ሕዝቡንም ሁሉ በእርሱ ላይ አነሳሥተው ያዙት።'),
  ('7b10e288-6443-54bc-ace9-c39ea4cd5634', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 2, 28, 'እየጮሁም እንዲህ አሉ፥ “እናንተ የእስራኤል ወገኖች ሆይ፥ ርዱን፤ በየስፍራው ሕዝባችንን፥ ኦሪትንም፥ ይህንም ስፍራ የሚቃወም ትምህርት ለሰው ሁሉ የሚያስተምር እነሆ፥ ይህ ሰው ነው፤ አሁንም አረማውያንን ወደ መቅደስ አስገባ፤ ቤተ መቅደስንም አረከሰ።'),
  ('d5360842-55c1-50f0-af0e-c6ac30994af7', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 3, 29, 'የኤፌሶን ሀገር ሰው የሆነ ጥሮፊሞስን ከጳውሎስ ጋር በከተማ አይተውት ነበርና፤ ጳውሎስም ወደ ቤተ መቅደስ ያስገባው መስሎአቸው ነበርና።'),
  ('42cd00bd-b86a-58d8-a7bf-57274c99af4f', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 4, 30, 'ከተማውም ሁሉ ታወከ፤ ሕዝቡም ሁሉ እየሮጡ ሄደው ጳውሎስን ጐትተው ከቤተ መቅደስ አወጡት፤ በሩንም ሁሉ ዘጉ።'),
  ('5d0a75d6-6faf-530d-a72d-6e53da1ca06c', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 5, 31, 'ሊገድሉትም ፈልገው ብዙ ደበደቡት፤ ወዲያውም ኢየሩሳሌም በመላዋ እንደ ታወከች የሚገልጥ መልእክት ወደ ሻለቃው ደረሰለት።'),
  ('ac1f737f-0bd9-57f5-a026-1d3573e3f879', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 6, 32, 'በዚያ ጊዜም ጭፍሮቹን ከአለቆቻቸው ጋር ይዞ ወደ እነርሱ ሄደ፤ እነርሱም የሻለቃውን ጭፍሮች ባዩ ጊዜ ጳውሎስን መምታታቸውን ተዉ።'),
  ('e426a9c2-6bbe-57e2-abef-db5b8062f761', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 7, 33, 'የሻለቃውም ቀረብ ብሎ ያዘው፤ በሁለት ሰንሰለትም እንዲታሰር አዘዘ፤ “ምንድነው? ምንስ አደረገ?” ብሎም ጠየቀ።'),
  ('54c0213c-bea7-5365-afc6-75945ddacdff', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 8, 34, 'ሕዝቡም እኩሌቶቹ እንዲህ ነው፤ እኩሌቶቹም እንዲህ አይደለም እያሉ ይጮሁ ነበር፤ ሻለቃውም ሕዝቡ የሚታወክበትን ርግጡን ማወቅ ተሣነው፤ ወደ ወታደሮቹም ሰፈር እንዲወስዱት አዘዘ።'),
  ('51b45c1a-0ccf-570a-a9c3-44dfc9679b84', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 9, 35, 'ደረጃውንም በሚወጣበት ጊዜ ወታደሮች ተሸክመው አወጡት፤ ሰው ይጋፋ ነበርና።'),
  ('88bc920d-51b6-5963-a7ac-2144b190ebe5', 'dbd35292-5306-57fb-a927-176de45849f8', 'fe7b9346-760b-5cb7-a936-fda1bd270cf8', 10, 36, 'ብዙዎችም ይከተሉት ነበር፤ ሕዝቡም፥ “አስወግዱት” እያሉ ይጮሁ ነበር።'),
  ('db3af165-8691-50be-a961-7c1c2cdcee4f', 'dbd35292-5306-57fb-a927-176de45849f8', '7e3fe43e-88d9-54cd-a673-f3f1553f8edd', 1, 37, 'ወደ ሰፈርም በደረሰ ጊዜ ጳውሎስ ሻለቃውን፥ “ላነጋግርህ ትፈቅድልኛለህን?” አለው፤ ሻለቃውም፥ “የጽርዕ ቋንቋ ታውቃለህን?” አለው።'),
  ('77e62798-961d-5ee5-a7b1-50e2eafaefda', 'dbd35292-5306-57fb-a927-176de45849f8', '7e3fe43e-88d9-54cd-a673-f3f1553f8edd', 2, 38, '“ምናልባት ከዚህ በፊት ወንጀል የሠራህና ከነፍሰ ገዳዮች አራት ሺህ ሰዎችን ይዘህ ወደ ምድረ በዳ የወጣህ ያ ግብፃዊ አንተ አይደለህምን?” አለው።'),
  ('4051c643-7626-582d-afef-db0561e97286', 'dbd35292-5306-57fb-a927-176de45849f8', '7e3fe43e-88d9-54cd-a673-f3f1553f8edd', 3, 39, 'ጳውሎስም፥ “እኔስ አይሁዳዊ ሰው ነኝ፤ የተወለድሁባትም ሀገር ጠርሴስ የታወቀች የቂልቅያ ከተማ ናት፤ ለሕዝቡም እንድነግራቸው ትፈቅድልኝ ዘንድ እለምንሃለሁ” አለው።'),
  ('7cb2e0d0-2f36-5c29-ac55-b38484d29fa9', 'dbd35292-5306-57fb-a927-176de45849f8', '7e3fe43e-88d9-54cd-a673-f3f1553f8edd', 4, 40, 'በፈቀደለትም ጊዜ ጳውሎስ በደረጃው ላይ ቆሞ እጁን ወደ ሕዝቡ ዘረጋ፤ እጅግም ጸጥታ በሆነ ጊዜ ጳውሎስ በዕብራይስጥ ቋንቋ ተናገረ፤ እንዲህም አለ።'),
  ('7e11416c-cd96-583c-a24a-a000fdec1ad0', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '34a7c804-c3c0-5028-a5ab-579d0744ac7c', 1, 1, '“እናንተ ወንድሞችና አባቶች፥ አሁን በፊታችሁ የምናገረውን ስሙኝ።”'),
  ('25701f13-e34c-59f0-ac0f-9b94b7502e3e', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '34a7c804-c3c0-5028-a5ab-579d0744ac7c', 2, 2, 'በዕብራይስጥ ቋንቋ እንደሚነግራቸው በሰሙም ጊዜ ጸጥ ብለው አዳመጡት።'),
  ('517312ea-7cce-5b6f-a7f3-988fb20b00de', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '34a7c804-c3c0-5028-a5ab-579d0744ac7c', 3, 3, 'ጳውሎስም እንዲህ አላቸው፥ “እኔ አይሁዳዊ ሰው ነኝ፤ የቂልቅያ ክፍል በምትሆን በጠርሴስ ከተማ ተወለድሁ፤ በዚችም ከተማ ከገማልያል እግር ሥር ሆኜ አደግሁ፤ የአባቶችንም ሕግ ተማርሁ፤ እናንተ ሁላችሁ ዛሬ እንደምታደርጉትም ለእግዚአብሔር ቀናተኛ ነበርሁ።'),
  ('e666c757-2af6-5e45-ac30-2e8567cb8a86', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '34a7c804-c3c0-5028-a5ab-579d0744ac7c', 4, 4, 'ይህን ትምህርት የሚከተሉ ወንዶችንም ሴቶችንም እያሰርሁ ወደ ወህኒ ቤት አሳልፌ በመስጠት እስከ ሞት ድረስ አሳደድኋቸው።'),
  ('03f6dc06-2d4a-53c1-a297-917ba39880ec', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '34a7c804-c3c0-5028-a5ab-579d0744ac7c', 5, 5, 'እንዲቀጡም ከዚያ ያሉትን አስሬ ወደ ኢየሩሳሌም አመጣቸው ዘንድ በደማስቆ ወደ አሉ ወንድሞች እንድሄድ ከእነርሱ ዘንድ የሥልጣን ደብዳቤ የተቀበልኋቸው ሊቀ ካህናቱና መምህራን ሁሉ ይመሰክራሉ።'),
  ('d30e9d2e-a869-5c2d-a908-8d7fe1f3f707', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 1, 6, '“ከዚህ በኋላ ወደ ደማስቆ ስሄድ ቀትር በሆነ ጊዜ ወደ ከተማው አቅራቢያ ደርሼ ሳለሁ ድንገት ታላቅ መብረቅ ከሰማይ በእኔ ላይ አንፀባረቀ።'),
  ('8ed48936-5bc7-54c9-a47e-fc10c4642ede', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 2, 7, 'በምድር ላይም ወደቅሁ ‘ሳውል ሳውል ለምን ታሳድደኛለህ?’ የሚል ቃልንም ሰማሁ።'),
  ('e1764996-3c14-530a-ad74-875518df4a08', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 3, 8, 'እኔም መልሼ፦ ‘አቤቱ፥ አንተ ማነህ?’ አልሁት፤ እርሱም፦ ‘አንተ የምታሳድደኝ የናዝሬቱ ኢየሱስ ነኝ’ አለኝ።'),
  ('00cf7d36-580c-5a6e-aa2a-7f1fa1c74381', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 4, 9, 'አብረውኝ የነበሩትም መብረቁን አይተው ደነገጡ፤ ነገር ግን ይናገረኝ የነበረውን ቃል አልሰሙም።'),
  ('bc9ef333-55ac-53c0-a7e6-75fd0ba6ab6d', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 5, 10, '‘አቤቱ፥ ጌታዬ ምን ላድርግ?’ አልሁ፤ ጌታም፦ ‘ተነሥና ወደ ደማስቆ ሂድ፤ ልታደርገው የሚገባህንም ሁሉ በዚያ ይነግሩሃል’ አለኝ።'),
  ('4a6b2a3d-e792-57d5-ad58-34e768652984', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 6, 11, 'ከዚያም በኋላ ከመብረቁ ነፀብራቅ የተነሣ ዐይኔን ታወርሁ፤ አብረውኝ የነበሩትም እየመሩኝ ወደ ደማስቆ ደረስሁ።')
